/**
 * REBOUND — shared contract (M2, "Restraint has a game; run 2 is different"; M1 "v1, honest" underneath).
 *
 * This file is the single source of truth between the workstreams:
 *   - src/core/      pure simulation core (implements ModelApi, no DOM); module map in src/core/README.md;
 *                    public entry src/core/index.ts (`model`)
 *   - src/content/   data for sectors, ages, applications, upgrades, levers, Commons, Charters… (src/content/index.ts
 *                    exports `content: Content`); module map in src/content/README.md
 *   - src/ui/        DOM interface (reads Derived, GameState and the views, calls ModelApi); the world scene engine is
 *                    src/ui/scene/ (its only reader of this contract is src/ui/scene/adapter.ts)
 *
 * Do not edit this file from a workstream. If the contract is wrong or missing something,
 * work around it locally and report it in your final message.
 *
 * Words
 *   - SECTOR (code) = one service + resource economy with its applications, efficiency path, pressure and levers.
 *     It opens at some point in a run and keeps running beside the others. ON SCREEN a sector is an "Industry"
 *     (plural "Industries"). No player-facing text says "sector" or "era" for this unit.
 *   - AGE (code and screen) = a period of the calendar: a year span, the page theme, and the sectors that belong to it.
 *     An age will later own a prestige layer (Reckoning / Treaty / Long Now); nothing here designs that yet.
 *   - v1 called both of these "era". The full old → new mapping is in design/m1-contract-notes.md.
 *
 * Conventions
 *   - All rates are per real second of play. `dt` is in seconds.
 *   - "Model years" = seconds × YEARS_PER_SECOND. Every timer, streak, decade and budget runs on model years.
 *     The *calendar* year shown to the player (Derived.year) is a separate, cosmetic quantity (see AgeDef.yearSpan).
 *   - ModelApi functions are PURE: never mutate the state passed in, always return a new state.
 *     No Date.now(), no Math.random() (use state.seed with a small deterministic PRNG if needed).
 *   - Money is "£" in every sector for simplicity.
 *   - Optional content fields state their default. Search for "M1 CHANGE" for semantics that differ from v1, "M2 CHANGE"
 *     for semantics that differ from M1, and "M2:" for what M2 adds. design/m2-contract-notes.md gives the reasons.
 *   - Nothing in the contract assumes a number of sectors or ages: iterate content.sectorOrder and content.ages.
 *   - "Model decade" = 10 model years of run time (200 s); decade k of a run covers run time × YEARS_PER_SECOND in
 *     [10k, 10k + 10).
 *
 * Forward compatibility (see design/roadmap.md): per-sector run state (budget, levers, settlement) lives in
 * SectorState / LeverState so that M5 can hold one copy per region; meta-level choices (loadout, slots, orders, the
 * Charter) live in MetaState. The unions below (EffectDef, StatKey, LeverRecycle, HeadlineKey, EventKind, Actor,
 * OrderId) will grow; code switching on them must have a default branch that ignores unknown members. M2 keeps the
 * shapes later milestones extend: Actor gains 'dispatch' (M3), 'rival' (M5) and 'agent' (M7); OrdersState gains
 * dispatch defaults (M3); SettledState is self-contained so M4's capstone can create settled sectors at run start;
 * RunSummary carries peak adoption and pressure for M3's before-and-after pictures; MetaState.opening seeds M5's
 * rival; decisions per model decade feed shift 3 (M3). Shared stocks and `feeds` (M4) are not here yet.
 *
 * M3 ("Every Industry its own"): search for "M3:" for what M3 adds and "M3 CHANGE" for semantics that differ from M2.
 * design/m3-contract-notes.md gives the reasons; the lane briefs are briefs/m3-*.md. In one paragraph: four general
 * mechanic kinds on SectorDef (seams, load, travel, priceSeen; see "M3 MECHANICS" above SectorDef), levers that bite
 * back (LeverKind 'measure', LeverDef.sideEffects), the cast and dispatches with timed modifiers, ambient news,
 * Histories, the household return (fileReturn) and the Proprietor's Day, the Archive, the first ending with its
 * retrospective, and optional banked time. Every M3 system is GATED by the feature mechanism of M2.1 (Content.features,
 * Derived.features): each names an M3FeatureId below, and nothing it adds is visible, and no action of it is accepted,
 * before that feature is on. Until the M2.1 contract is merged, "feature f is on" reads as true.
 *
 * M4 ("The Coal Age complete"; the shift is The Survey): search for "M4:" for what M4 adds and "M4 CHANGE" for
 * semantics that differ from M3 (every M4 CHANGE applies only when content uses the new field, so content without the
 * M4 fields, such as the test fixture, plays exactly as M3). design/m4-contract-notes.md is the specification and
 * design/m4-design.md the reasons; the lane briefs are briefs/m4-*.md. In one paragraph: Acts with an ending each and a
 * capstone afterwards (ActDef, MetaState.world.capstone, arrears), Preview Industries; a shared reserve
 * (SectorDef.resourceStock) and the order book (ApplicationDef.feeds); a renewable stock with a threshold, a scar, a
 * lying gauge and foreign fleets (RenewableDef, ForeignDef, pressureSource 'depletion'); the survey (EffectDef
 * 'survey', the Board's free first survey, Content.surveyReveal) and the full account it brings (feature 'estimates':
 * SectorDerived.fullR / embodied / yearsLeft, BudgetState.account); the 'quota' lever kind and settle.requires; wager
 * arms on letters. World-scoped records live under MetaState.world so that M7's prestige shift (The Inheritance) is a
 * migration, not a rewrite; ReckoningCause is open (M7 adds 'generation').
 *
 * M5 ("The Other Chair"): search for "M5:" for what M5 adds and "M5 CHANGE" for semantics that differ from M4 (every
 * M5 CHANGE applies only when content uses the new field: content with no `chair`, `rival` or `office` never has a
 * Ministry, and a sector with no `hiddenFlow` solves as M4, so the test fixture and M4 content play exactly as before).
 * design/m5-contract-notes.md is the specification and design/m5-design.md the reasons; the lane briefs are
 * briefs/m5-*.md. In one paragraph: Take office (OfficeDef, MetaState.office, GameState.officeOffer) turns every later
 * run into a Ministry (GameState.chair): the Industries of an act with `chair: 'government'` are run by the rival
 * (RivalDef, RivalState), who buys by the Market's rule with his own purse and answers each lever with the cheapest
 * response on a table the player can read (comply, evade through a loophole rung, lobby, litigate; concealment of his
 * returns beside them); the player legislates, inspects (inspect), amends loopholes (amend), wins elections on a
 * Confidence line (ChairDef, PledgeDef, choosePledges, campaign; Opposition; ReckoningCause 'defeated'), and spends a
 * Treasury fed by the rival's tax (compensate; LeverKind 'subsidy' and 'charge'). Plenty's hidden flow
 * (SectorDef.hiddenFlow). The Treaty (treaty, Precedent, ArticleDef, PlaybookDef) is the second reset. Every M5 system
 * is gated by an M5 feature (M5FeatureId).
 */

/** M1 CHANGE: was the five-member union EraId. Ids are content-defined, e.g. 'steam'. */
export type SectorId = string;
export type AgeId = string;

/** Model years that pass per real second (3 a minute). Drives every streak, budget and timer. */
export const YEARS_PER_SECOND = 0.05;
/** Model years of unbroken decoupling (see SectorDerived.decoupling) needed for a sector's Steady State. */
export const STEADY_STATE_YEARS = 50;
/** Calendar year used only when content has no ages (fallback clock: START_YEAR + run time × YEARS_PER_SECOND). */
export const START_YEAR = 1780;
/** Past its age's last year, the calendar advances at this fraction of the normal rate (until a later age begins), and
 *  then levels off (see AgeDef.yearSpan). */
export const CALENDAR_LATE_RATE = 0.1;
/** A stock reserve counts as exhausted at or below this fraction of reserveMax (0.2%): the run must end. */
export const EXHAUSTED_BELOW = 0.002;
/** R may exceed the budget line by this fraction and still count as within budget (solver noise, a cap at 1.0). */
export const BUDGET_TOLERANCE = 0.005;
/** Horizon of the "this decade" projection on upgrade cards, in model years (200 s). */
export const PROJECTION_YEARS = 10;
/** tick() never advances more than this many seconds per call; longer gaps go through fastForward(). */
export const MAX_TICK_SECONDS = 60;
/** M2: GameState.events keeps at most this many events (the oldest are dropped first). */
export const EVENTS_MAX = 50;
/** M2: MetaState.runs keeps the most recent this-many RunSummary entries (the oldest are dropped first). */
export const RUN_HISTORY_MAX = 20;
/** M2: RunStats.opening records at most this many purchase and founding actions per run. */
export const OPENING_MAX = 40;
/** M2: GameState.pendingDividends holds at most this many offers; see GameState.pendingDividends for the overflow rule. */
export const PENDING_DIVIDENDS_MAX = 8;
/** M2: RunStats.decisionsByDecade / automatedByDecade hold at most this many model decades; later decades add to the last. */
export const DECISION_DECADES_MAX = 600;
/**
 * M2: "pressure not rising" tolerance for clear skies (SectorDerived.clear): the net pressure rate must be at most this
 * fraction of collapseAt per second (1e-6 × collapseAt per second; solver noise).
 */
export const CLEAR_RATE_TOLERANCE = 1e-6;
/* --- M3 constants --- */
/** M3: GameState.dispatch.answered keeps at most this many entries (the oldest dropped). */
export const ANSWERED_MAX = 60;
/** M3: GameState.modifiers holds at most this many timed modifiers; a new one beyond it replaces the one ending soonest. */
export const MODIFIERS_MAX = 12;
/** M3: SectorDef.load profiles have exactly this many hourly weights (hour 0 = midnight to 1 a.m.). */
export const LOAD_HOURS = 24;
/** M3: a household-return figure above this is refused as implausible (validation of untrusted input). */
export const RETURN_FIGURE_MAX = 10_000_000;
/** M3: MetaState.milestones and the retrospective keep at most this many keys. */
export const MILESTONES_MAX = 200;
/**
 * M3: the feature ids M3 adds to the M2.1 feature mechanism (merge them into its FeatureId union). Each is switched on
 * by its Content.features entry's `when` (content); while off, everything listed for it is hidden and refused.
 *   'seams'        Steam's seam ladder: SectorDerived.seams shown; sinkSeam accepted. (Seams never sunk change nothing.)
 *   'load'         the load-curve widget (SectorDerived.load shown). The load arithmetic itself acts from the moment
 *                  an Industry with `load` opens: it is that Industry's economics, not a choice.
 *   'travel'       the travel-time dial and sprawl (SectorDerived.travel shown); as 'load', the arithmetic always acts.
 *   'freeAtUse'    the "free" price tag (SectorDerived.free, AppDerived.priceSeen shown); the arithmetic always acts.
 *   'sideEffects'  the "bites back" line on levers (LeverView.bite shown, 'biteBack' headline and event). The bite
 *                  itself always acts (the lever's `catch` line states it from the start).
 *   'dispatches'   the scheduler draws letters (none are drawn while off); answerDispatch accepted; Derived.dispatch.
 *   'ambient'      ambient headlines are printed (none while off).
 *   'histories'    the History picker; chooseHistory accepted.
 *   'archive'      the Archive viewer. Notes are recorded (MetaState.archive) whether or not it is on.
 *   'survey'       the return filer and the second twin gauges; fileReturn accepted (withdrawReturn always is).
 *   'bank'         banked time accrues and useBank is accepted (also needs GlobalParams.offline.bankRate > 0).
 */
export type M3FeatureId =
  | 'seams' | 'load' | 'travel' | 'freeAtUse' | 'sideEffects' | 'dispatches' | 'ambient' | 'histories' | 'archive'
  | 'survey' | 'bank';
/* --- M4 constants --- */
/** M4: default ActDef.capstone.incomeShare: the share of a capstoned Industry's recorded (per-head scaled) income paid. */
export const CAPSTONE_INCOME_SHARE = 0.25;
/** M4: a capstoned Industry in arrears never collapses the run: its pressure is held below this fraction of collapseAt. */
export const ARREARS_COLLAPSE_HOLD = 0.99;
/** M4: a renewable stock's step is split into substeps when |dQ| over the step exceeds this fraction of K … */
export const RENEWABLE_SUBSTEP_SHARE = 0.05;
/** M4: … into n = ceil(|dQ| / (RENEWABLE_SUBSTEP_SHARE × K)) substeps, at most this many (deterministic). */
export const RENEWABLE_SUBSTEPS_MAX = 8;
/** M4: a renewable stock never falls below this fraction of K (it never exhausts; see SectorDef.resourceKind). */
export const RENEWABLE_FLOOR = 1e-6;
/** M4: default ForeignDef.announceAt: the foreign share at which the 'foreignFleets' headline is printed (once a run). */
export const FOREIGN_ANNOUNCE_AT = 0.15;
/** M4: the survey reveal's variant is 'small' when reported − true < this (Content.surveyReveal). */
export const SURVEY_SMALL_GAP = 0.15;
/**
 * M4: the feature id M4 adds (merged into FEATURE_IDS after 'survey').
 *   'estimates'   the full account and the growing-rate years left: while off, SectorDerived.fullR, embodied and
 *                 yearsLeft.growing read null and every budget line is drawn on the 'own' (chimney) account
 *                 (BudgetState.account). Content's `when` is { flag: 'survey:fishing' }: it arrives with the Survey.
 * Nothing else M4 adds is feature-gated: the order book and the stock chart arrive with their Industries.
 */
export type M4FeatureId = 'estimates';
/* --- M5 constants --- */
/** M5: Confidence (ChairState.confidence) is clamped to [0, CONFIDENCE_MAX]. */
export const CONFIDENCE_MAX = 100;
/** M5: default OfficeDef.prospectusItems: opening items the prospectus quotes (a repeated upgrade folds into one). */
export const PROSPECTUS_ITEMS = 5;
/** M5: FileView.accepted and FileView.declined hold at most this many entries each. */
export const FILE_ITEMS = 3;
/** M5: LoopholeDef.escape is clamped to [0, LOOPHOLE_ESCAPE_MAX]. */
export const LOOPHOLE_ESCAPE_MAX = 0.9;
/** M5: SectorDef.hiddenFlow: the return share r is clamped to [floor ?? 0, RETURN_SHARE_MAX]. */
export const RETURN_SHARE_MAX = 0.95;
/** M5: a 'subsidy' lever's value (the Treasury's share of a capital cost) is clamped to [0, SUBSIDY_MAX]. */
export const SUBSIDY_MAX = 0.9;
/** M5: StatKey 'yearsSinceInspection' reads this for a sector never inspected in this Ministry. */
export const NEVER_INSPECTED_YEARS = 1e9;
/**
 * M5: the feature ids M5 adds (merged into FEATURE_IDS after 'estimates', in arrival order; design/m5-design.md §8).
 * Each is switched on by its Content.features entry's `when` (content). A feature absent from Content.features is
 * always on (as every feature), so content with no M5 features plays as before; every one of them gates something that
 * exists only in a Ministry, so outside one they change nothing.
 *   'chair'       Confidence, elections, pledges, Opposition, the answer line (LeverView.rivalAnswer) and the rival's
 *                 panel (Derived.chair). Content's `when`: { flag: 'office' }. M5 CHANGE to the unfolding: takeOffice
 *                 unlocks it at once (ignoring featureGapSeconds) when its `when` holds, so a Ministry never runs without
 *                 it. While it is off in a Ministry (only a hand-built state), the Chair's rules do not run and
 *                 Derived.chair is null; the rival still owns and buys (ownership is not a feature).
 *   'loopholes'   ladders (LeverDef.ladder): no rung opens, the rival never evades (ResponseDef 'evade' unavailable),
 *                 amend() refuses, ChairView.loopholes is [].
 *   'inspection'  inspect() and Standing inspection refuse; the rival never conceals (concealment stays 0);
 *                 SectorDerived.reportedR = R, inspectedUntil and found null; Derived.chair.inspectors total 0.
 *   'treasury'    compensate() refuses; ChairView.treasury null (the tax still accrues into capital regardless).
 *   'statecraft'  nothing in core: content gates the Statecraft nodes with KnowhowDef.when { feature: 'statecraft' }.
 *   'charge'      nothing in core: content gates charge levers with LeverDef.requires ['charge'].
 *   'treaty'      treaty() and buyArticle() refuse; Derived.treaty null; the Articles tab is not shown.
 */
export type M5FeatureId = 'chair' | 'loopholes' | 'inspection' | 'treasury' | 'statecraft' | 'charge' | 'treaty';
/**
 * Save format version. M2 CHANGE: 3. M3 CHANGE: 4 (the v3 → v4 steps are at the end of this comment).
 * Migration rule (implemented in ModelApi.deserialize; versions chain: 1 → 2 → 3):
 *   - version > SAVE_VERSION → null (a save from the future is refused).
 *   - version 2 → 3, then stamped 3. Every field M2 adds that a fresh state supplies is filled by the deep merge
 *     below; the rules here are the ones a merge cannot get right. Applied to a JSON copy, in this order:
 *       1. GameState: pendingDividends [], commons { levels: {}, fund: 0 }, events [], lastOffline null,
 *          charterOffer [] (but see step 6).
 *       2. Every SectorState (open or closed): clearYears 0; settled null; settledBefore false; dividends [];
 *          decadesLean = an array of `false` as long as decadesWithin (M1 decades were judged at the full target, so
 *          none is lean); windowLean false; peakPressure = pressure.
 *          Every AppState: peakAdoption 0.
 *       3. Every BudgetState: pace = the id of the FIRST resolved pace of its sector (see SteadyParams.paces);
 *          w0 = −1 and p0 = −1 as markers, replaced in step 7; clearAt absent; heldAt kept.
 *       4. RunStats: leanDecades 0, decisions 0, decisionsByDecade [], automated 0, automatedByDecade [], opening [],
 *          firstBudgetAt null.
 *       5. MetaState: charter null; orders = the default OrdersState (see OrdersState); runs = [lastRun] if
 *          meta.lastRun exists (its new optional fields stay absent), else []; opening and firstOpening absent;
 *          eventSeq 0; knowhowPeak = a copy of meta.knowhow; peakPopulationEver = max(1, state.peakPopulation).
 *       6. After the state is built: if Derived.freshRun holds and meta.reckonings ≥ 1, charterOffer = the offer
 *          reckon() would draw for this state (see GameState.charterOffer); else [].
 *       7. After the state is built: every budget with the w0/p0 markers gets w0 = Derived.wellbeing of the loaded
 *          state and p0 = that sector's current pressure (the "day drawn" becomes the day loaded).
 *     The v2 field GlobalParams.offlineCapSeconds is content, not save data: nothing to migrate.
 *   - version 1 (or missing) → migrated to version 2 as follows, then to version 3 as above:
 *       top-level `eras` → `sectors` (same keys: the v1 ids 'steam' … 'code' are kept as sector ids); every
 *         `history[i].eras` → `history[i].sectors`; every `news[i].era` → `news[i].sector`;
 *         meta.lastRun.eras → .sectors and .causeEra → .causeSector;
 *       meta.steadyEras → meta.steadySectors; run.steadyEras → run.steadySectors;
 *       meta.furthestEra (an index n) → meta.sectorsOpened = { s: true } for the first n ids of content.sectorOrder;
 *       meta.institutions: `true` → level 1;
 *       meta.slots = max(content.global.startingSlots ?? 2, number of owned institutions);
 *       meta.loadout = every owned institution id still in content, in content order (v1 players are grandfathered:
 *         everything they owned stays seated);
 *       meta.backfiredSectors = { s: true } for every sector whose current-run state has backfired true;
 *       every SectorState: etaAtBase kept if present (the v1 model stored it as an extra), else baseD / baseR, else
 *         baseEta; serviceDelivered 0; decadesWithin []; steadyYears 0; budget null, EXCEPT that a sector with an
 *         active cap lever whose ref > 0 gets budget = { r0: ref, since: state.time, drawnYear: current calendar year };
 *       steadyYearsAll 0; run.decoupledYears 0 (the v1 trend-based definitions do not carry over);
 *       run.wellbeingYears, run.yearsAtTarget, run.budgetDecades 0; run.firstBackfires {};
 *       lever levels clamped to the lever's maxLevel; recycle left unset (default applies);
 *       meta.lastRun's new optional fields stay absent.
 *   - At every version: sectors in the save but not in content are dropped; sectors in content but not in the save are
 *     rebuilt closed; ids of upgrades, levers, Know-how, Institutions, Commons projects, dividends and Charters no
 *     longer in content are dropped (a meta.charter or pending dividend naming an unknown id is cleared or removed;
 *     orders keep only known sector, lever and project ids).
 *   - Any missing field of a version-3 save is rebuilt from a fresh state (deep merge), as in v1. Map- and array-valued
 *     fields the merge cannot type-check (levels, events, pendingDividends, runs, opening, settled) are validated
 *     element by element and invalid entries dropped.
 * The unfolding (no version change; MetaState.features is optional): a version-3 save whose meta has no `features`
 * object was made before the unfolding and is grandfathered, so a player keeps every system the old build showed
 * them: meta.features gets every feature in content, stamped meta.totalSeconds, whose old gate holds for the save —
 * 'population' always; 'reboundMeter', 'levers', 'moreLevers', 'budget', 'leverRepeat', 'dividendChoice',
 * 'budgetPace', 'clearSkies', 'steadyState' and 'settlement' when flags.revealed or meta.reckonings ≥ 1; 'market'
 * and 'charters' when meta.reckonings ≥ 1; 'commons' when meta.reckonings ≥ 2. (Older versions migrate to 3 first.)
 * A save with a `features` object keeps its known ids with finite values.
 * The UI may keep its localStorage key; deserialize does the migration.
 *
 * M3: version 3 → 4 (versions chain 1 → 2 → 3 → 4; a version > 4 → null). Applied to a JSON copy, in this order; the
 * deep merge from a fresh state supplies every other M3 field (all of which a fresh state has):
 *   1. GameState: modifiers []; ambientLast {}; orderLog {}; historyLifted false;
 *      dispatch = { pending: [], queue: [], answered: [], offered: [], draws: 0, standing: [], nextAt: (step 7) }.
 *   2. Every SectorState (open or closed): seamsSunk 0. LeverState and AppState: nothing (bite and bitten are
 *      optional, absent = 0 / false; lockInDecay acts on the existing peakD). Every SettledState: load, travel and
 *      appPriceSeen absent (their views are null while it stays settled).
 *   3. RunStats: dispatchesAnswered 0, dispatchesDefaulted 0.
 *   4. MetaState: dispatches { seen: {}, arms: {}, playerArms: {} }; history null; histories {}; unlocks {};
 *      returns {}; archive {}; flags {}; endings {}; bankedSeconds 0;
 *      milestones = { 'sectorOpened:<s>': { run: 0, at: 0, year: 0 } for every s in meta.sectorsOpened, 'steady:<s>' likewise for meta.steadySectors, 'backfire:<s>' likewise for
 *      meta.backfiredSectors } (run 0 and at 0 mark "before the records began"; the retrospective prints them as
 *      "earlier"); orders.dispatch = { on: false, cast: {} }.
 *   5. RunSummary entries (meta.runs, meta.lastRun): the M3 optional fields stay absent.
 *   6. If state.flags.won is true: meta.endings.steadyAll = an EndingRecord for the loaded state (run = reckonings + 1,
 *      runSeconds = state.time, totalSeconds = meta.totalSeconds, year = Derived.year rounded down), and the milestone
 *      'won' likewise; no event (nothing is replayed).
 *   7. After the state is built: dispatch.nextAt = max(dispatchFirstAt(content), state.time + dispatchGap(state, 0))
 *      (see GameState.dispatch), so a loaded game does not receive a letter at once; archive notes whose subject is
 *      owned or seen in the loaded state (ArchiveDef.subject rules), or is a sector in meta.sectorsOpened, are unlocked
 *      with at = meta.totalSeconds and no event.
 *   Validation (as M2, element by element, invalid entries dropped): modifiers (unknown source or arm dropped),
 *   dispatch.pending / queue / answered / offered (unknown dispatch ids dropped), meta.returns (re-validated as
 *   fileReturn validates; an invalid return is dropped), meta.archive, meta.histories, meta.unlocks (ids no longer in
 *   content dropped), meta.history (unknown → null), orders.dispatch.cast (unknown cast ids dropped).
 *
 * M4 CHANGE: 5. Version 4 → 5 (versions chain 1 → 2 → 3 → 4 → 5; a version > 5 → null). Applied to a JSON copy, in this
 * order; the deep merge from a fresh state supplies every other M4 field (all optional or with fresh defaults):
 *   1. MetaState: world { capstone: {}, scars: {} }.
 *   2. Every SectorState (open or closed): nothing (crossed, capstoned, arrears absent = false). Sectors in content but
 *      not in the save (Iron, Fishing) are rebuilt closed by the existing rule.
 *   3. The M3 ending record: meta.endings.steadyAll, if present, is kept as is (the retrospective prints it under its own
 *      template: "Everything settled, under the earlier rule"). It does NOT count as 'actOne': the Act I ending needs
 *      Iron and Fishing, which no v4 save has.
 *   4. flags.won in a loaded mid-run state that won under the M3 rule: kept true for the rest of that run (it is the
 *      run's history), but steadyYearsAll is reset to 0 so that the Act I streak starts from the new rule's first step.
 *   5. Previews: nothing to migrate: Motion, Compute and Code stay openable through { owns: '<id>' } (ActDef.preview).
 *   6. Dispatches: answered lists keep their entries; AnsweredDispatch.won absent on old entries.
 *   7. Validation (element by element, invalid entries dropped): meta.world.capstone (unknown sectors or acts dropped; a
 *      record whose SettledState fails the M2 validation dropped), meta.world.scars (unknown or non-renewable sectors
 *      dropped; yearsLeft finite and ≥ 0).
 *   No event is replayed. Round trip v5 lossless; a v4 save from before the M3 finish (with steadyAll under the earlier
 *   rule) loads the same way. The Survey adds nothing to migrate: BudgetState.account absent = 'own';
 *   meta.flags['survey:<s>'] absent; feature 'estimates' locked until the moment (a save that already reached it keeps
 *   its flag). The other optional M4 state fields (SectorState.minStock, lastSurvey, foreignAnnounced, feedPeak;
 *   GameState.surveyReveal) are absent = none and need no step; a v5 save's are validated as their types say (non-finite
 *   numbers and unknown sector ids dropped). Modifier validation keeps a source 'survey:<s>' (arm 0) when s is a
 *   renewable sector with RenewableDef.firstSurvey (see ActiveModifier).
 *
 * M5 CHANGE: 6. Version 5 → 6 (versions chain 1 → 2 → 3 → 4 → 5 → 6; a version > 6 → null). Applied to a JSON copy, in
 * this order; the deep merge from a fresh state supplies the rest (every M5 field is optional or has a fresh default):
 *   1. MetaState: precedent 0, precedentEarned 0, articles {}, treaties 0, playbooks [], pledgesKept {}; office absent;
 *      dispatches.lastPlayer absent (= {}).
 *   2. GameState: chair null; officeOffer false, then step 6.
 *   3. LeverState: since and raisedAt absent (= never). SectorState: decadesCertified absent (= all false). RunStats:
 *      certifiedDecades absent (= 0).
 *   4. Institutions "unlocked with no level": M5 represents it as meta.institutions[id] = 0 (an own key with 0). Every
 *      reader that tests "owned" (level ≥ 1) is unchanged; the shop shows level 0 as "unlocked, not bought"
 *      (InstitutionView.unlocked) and buyInstitution accepts level 1 at the level-1 cost (def.cost). v5 saves have no
 *      zeros; nothing to migrate. M5 CHANGE to validation: a 0 is a valid level (it was dropped before as "not ≥ 1").
 *   5. Previews: a v5 save after the Act I ending keeps Motion, Compute and Code openable as Previews until office is
 *      taken (unchanged rules); at takeOffice Compute and Code close (ActDef.closedInOffice), their meta records kept.
 *   6. After the state is built: if Derived.freshRun and meta.reckonings ≥ 1 and office is not taken and the last run
 *      (meta.lastRun) satisfies OfficeDef.when as far as a summary can say (meta.endings.actOne exists and
 *      lastRun.sectors.motion exists with resourceUsed > 0: a v5 RunSummary keeps no openFor, so "Motion ran in the last
 *      run" stands in for "open five minutes"), officeOffer = true. (M5 adds RunSummary.sectors[s].openFor, so later
 *      summaries can say it exactly; the stand-in names 'motion' and 'actOne' only in this migration step.)
 *   7. Validation (element by element, invalid entries dropped): meta.articles and meta.playbooks (unknown ids dropped);
 *      meta.pledgesKept (unknown ids dropped); meta.office (a profile with a non-finite number → RivalDef.defaultProfile;
 *      handedOver unknown Know-how ids dropped, non-finite levels dropped; record numbers non-finite → 0; ministries
 *      non-finite → 1; a prospectus or file that fails its shape → recomputed from meta as takeOffice would); chair (rebuilt
 *      fresh, as inherit.ts builds a Ministry's, if it fails its shape; otherwise unknown lever, pledge, loophole and
 *      sector ids dropped, numbers finite, confidence clamped to [0, CONFIDENCE_MAX]); orders.inspection (unknown sector
 *      → null).
 *   Round trip v6 lossless; v7 → null. No event is replayed. The owner has said there are no other players (20 Nov
 *   2026): a v5 save must load without crashing, but no step above exists to preserve a mid-game state exactly; a
 *   loaded state that fails a step may land somewhere odd (e.g. a Ministry rebuilt fresh).
 */
export const SAVE_VERSION = 6;

/* ------------------------------------------------------------------ */
/* CONDITIONS (data-only "when X")                                     */
/* ------------------------------------------------------------------ */

export type CmpOp = '<' | '<=' | '>' | '>=';

/**
 * Statistics a Cond can read. Scope:
 *   - Global (sector/app ignored): 'time' (run seconds), 'year' (calendar, Derived.year), 'wellbeing', 'population',
 *     'capital', 'mandate', 'reckonings' (meta.reckonings), 'steadyYearsAll', 'clicks' (run.clicks).
 *   - Sector (`sector` required; if the sector is absent from content, closed, or the value is null, the leaf is
 *     FALSE): 'etaFold', 'rFold', 'frontierFold', 'peakRFold' (SectorState.peakR / baseR), 'rebound',
 *     'resourceUse' (R), 'demand' (D), 'servicePrice' (p_s), 'serviceDelivered', 'reserveFraction', 'pressureFraction',
 *     'crises' (SectorState.crisesFired), 'steadyYears', 'budgetDecades' (decadesWithin.length),
 *     'withinBudget' (1 or 0), 'appsFounded' (count of founded applications).
 *   - Application (`app` required, sector inferred from the app; FALSE if that sector is closed):
 *     'adoption', 'appDemand' (AppDerived.demand).
 *   - M2, global: 'decisions' (run.decisions), 'automated' (run.automated), 'commonsLevels' (Σ GameState.commons.levels),
 *     'sectorsSettled' (open sectors with SectorState.settled ≠ null), 'leanDecades' (run.leanDecades),
 *     'fullDecades' (run.budgetDecades − run.leanDecades).
 *   - M2, sector: 'settled' (1 or 0), 'clear' (SectorDerived.clear, 1 or 0), 'clearYears' (SectorState.clearYears),
 *     'leanDecades' and 'fullDecades' with `sector` set (that sector's, this run); global without `sector`.
 * Every value is the one Derived/SectorDerived/AppDerived would report for the same state.
 * M3, global: 'steadySectors' (count of run.steadySectors), 'dispatchesAnswered' (run.dispatchesAnswered: by the
 *   player), 'historiesCleared' (count of meta.histories with cleared true), 'totalHours' (meta.totalSeconds / 3600),
 *   'bankedSeconds' (meta.bankedSeconds).
 * M3, sector: 'seamsSunk' (SectorState.seamsSunk); 'loadFactor' (SectorDerived.load.factor; FALSE without `load`);
 *   'travelHours' (SectorDerived.travel.hoursPerHead; FALSE without `travel`); 'sprawl' (SectorDerived.travel.sprawl;
 *   FALSE without `travel`); 'bite' (the largest LeverState.bite among the sector's levers, 0 if none).
 * M4, sector (FALSE, as other sector stats, when the sector is absent or closed, and where marked):
 *   'openFor'        SectorState.openFor (seconds since it opened this run);
 *   'stockFraction'  Q / K, the TRUE stock (renewable only; FALSE otherwise);
 *   'reportedStock'  (Q / K)^beta, catch per trip (renewable only; FALSE otherwise);
 *   'foreignShare'   the foreign share now (renewable with RenewableDef.foreign; FALSE otherwise);
 *   'scarYears'      meta.world.scars[s]?.yearsLeft ?? 0 (renewable only; FALSE otherwise);
 *   'surveyed'       1 while a survey effect is in force on the sector (SectorDerived.stock.surveyed), else 0;
 *   'budgetHeadroom' 1 − R / budgetR, on the line's own account (FALSE without a line);
 *   'feedFactor'     Π of every feed factor into this sector now (1 if none; SectorDerived.feeds of the sources);
 *   'arrears'        1 or 0 (SectorState.arrears).
 * M4, global: 'capstoned' (count of sectors with SectorState.capstoned this run).
 * M4 (amend), sector: 'feedShare' = Σ over feed sources of rAdded into this sector ÷ its R now (the share of its burn
 *   that the feeds add; SectorDerived.fed.share), 0 with no feed; FALSE when R is 0. The combined factor into a sector is
 *   the existing 'feedFactor'.
 * M4: a sector stat read on a capstoned sector reads its settled (scaled) values, as on any settled sector.
 * M5, global:
 *   'confidence'        ChairState.confidence (0 outside office);
 *   'inOffice'          1 while GameState.chair is non-null (a Ministry), else 0;
 *   'inOpposition'      1 while ChairState.inOpposition, else 0;
 *   'electionsWon'      ChairState.electionsWon (this Ministry; 0 outside office);
 *   'ministries'        meta.office?.ministries ?? 0 (Ministries begun, this one included);
 *   'treaties'          meta.treaties ?? 0;
 *   'precedent'         meta.precedent ?? 0;
 *   'settledFromChair'  office.record.settledFromChair + this run's chair sectors settled now (0 outside office);
 *   'parliamentWagers'  wager arms answered by the player since this Parliament's start (GameState.dispatch.answered
 *                       entries with by 'player', t ≥ parliament.start and a wager arm; 0 outside office);
 *   'rivalCapital'      RivalState.capital (0 outside office).
 * M5, sector (FALSE, as other sector stats, when absent or closed, and where marked):
 *   'concealment'          the TRUE concealed share RivalState.concealment[s] (0 when none; FALSE outside office);
 *   'yearsSinceInspection' (time − ChairState.inspected[s]) × YEARS_PER_SECOND, NEVER_INSPECTED_YEARS if never this
 *                          Ministry (FALSE outside office);
 *   'certifiedDecades'     count of true in SectorState.decadesCertified (0 when absent);
 *   'waterApplied', 'waterConsumed', 'returnShare'   SectorDerived.water's applied, consumed, returnShare (FALSE
 *                          without hiddenFlow);
 *   'loopholesUsed'        rungs of the sector's levers whose LoopholeState.status is 'used' or 'closed' this run (0
 *                          outside office).
 */
export type StatKey =
  | 'time' | 'year' | 'wellbeing' | 'population' | 'capital' | 'mandate' | 'reckonings' | 'steadyYearsAll' | 'clicks'
  | 'etaFold' | 'rFold' | 'frontierFold' | 'peakRFold' | 'rebound' | 'resourceUse' | 'demand' | 'servicePrice'
  | 'serviceDelivered' | 'reserveFraction' | 'pressureFraction' | 'crises' | 'steadyYears' | 'budgetDecades'
  | 'withinBudget' | 'appsFounded'
  | 'adoption' | 'appDemand'
  /* --- M2 --- */
  | 'decisions' | 'automated' | 'commonsLevels' | 'sectorsSettled' | 'leanDecades' | 'fullDecades'
  | 'settled' | 'clear' | 'clearYears'
  /* --- M3 --- */
  | 'steadySectors' | 'dispatchesAnswered' | 'historiesCleared' | 'totalHours' | 'bankedSeconds'
  | 'seamsSunk' | 'loadFactor' | 'travelHours' | 'sprawl' | 'bite'
  /* --- M4 --- */
  | 'openFor' | 'stockFraction' | 'reportedStock' | 'foreignShare' | 'scarYears' | 'surveyed' | 'budgetHeadroom'
  | 'feedFactor' | 'arrears' | 'capstoned'
  /* --- M4 (amend) --- */
  | 'feedShare'
  /* --- M5 --- */
  | 'confidence' | 'inOffice' | 'inOpposition' | 'electionsWon' | 'ministries' | 'treaties' | 'precedent'
  | 'settledFromChair' | 'parliamentWagers' | 'rivalCapital'
  | 'concealment' | 'yearsSinceInspection' | 'certifiedDecades' | 'waterApplied' | 'waterConsumed' | 'returnShare'
  | 'loopholesUsed';

/**
 * A data-only condition, evaluated by the core against a state (and the flows it derives).
 *   - { stat, op, value }: compare a statistic (see StatKey for scope rules).
 *   - { owns: id }: id is looked up across all content (ids are unique game-wide) and is true when:
 *       upgrade level ≥ 1 this run · application founded this run · lever level ≥ 1 · institution level ≥ 1 (owned,
 *       seated or not; a Charter's institutionLoan does not count) · know-how level ≥ 1 · achievement earned ·
 *       M2: Commons project level ≥ 1 this run · Charter in force this run (meta.charter === id) · dividend chosen this
 *       run (id in any SectorState.dividends) · a sector id: opened in any run (meta.sectorsOpened). Unknown id → false
 *       (the content lint catches it).
 *   - M2: sector-scoped stat leaves on a SETTLED sector read the values SectorDerived reports for it (see SettledState).
 *   - { flag }: state.flags[flag] === true ('revealed', 'won'; unknown flag → false).
 *   - all / any / not: logical combinators. Empty `all` is true, empty `any` is false.
 * `label` is the player-facing wording of this node ("Own the Separate condenser"), used by checklists
 * (Derived.nextSector). Content should label every direct child of an unlock's top-level `all`.
 * Unknown leaf shapes evaluate false.
 * M3:
 *   - `owns` also resolves: a seam id → sunk this run; a History id → cleared in any run (meta.histories[id].cleared);
 *     an Archive note id → unlocked (meta.archive); a cast id → false (use `answered`).
 *   - M3 CHANGE: { flag } is true when state.flags[flag] === true OR meta.flags[flag] === true (permanent flags set by
 *     the one-off metaFlag effect, e.g. 'proprietor').
 *   - { returned: id }: a return with this id is on file (meta.returns[id] exists). With `figure`, `op` and `value`:
 *     compares that stored figure (a key of the filed figures; a missing key → FALSE). See ModelApi.fileReturn.
 *   - { answered: dispatchId }: that dispatch has been answered (by anyone, default included) in any run
 *     (meta.dispatches.arms[id] or the run's answered list). `arm`: only answers with that arm index. `run: true`: this
 *     run only (GameState.dispatch.answered). `by: 'player'`: only answers the player chose.
 * M4:
 *   - { ending: id }: true once meta.endings[id] exists (an Act's ending reached in any run; 'actOne'). The M3 record
 *     'steadyAll' is a valid id too, but content should not gate on it.
 *   - `owns` with a sector id is unchanged ("opened in any run"), which is what keeps the Previews of a save that already
 *     opened them (ActDef.preview).
 * M5:
 *   - { loophole: id, status? }: that rung's LoopholeState this run (ChairState.loopholes[id]); with `status`, true when
 *     the rung's status equals it; without, true when it is 'used' or 'closed'. FALSE outside office or when the rung has
 *     no state yet. (An exempt application's ApplicationDef.when is { loophole: id, status: 'used' }.)
 *   - `owns` also resolves: a pledge id → in force now (ChairState.pledges) or kept in any Ministry (meta.pledgesKept);
 *     an Article id → bought (meta.articles); a playbook id → learnt (meta.playbooks); a loophole id → used or closed
 *     this run (as { loophole } without status).
 *   - { flag: 'office' } is meta.flags.office, set by takeOffice (no new leaf).
 */
export type Cond = (
  | { stat: StatKey; sector?: SectorId; app?: string; op: CmpOp; value: number }
  | { owns: string;
      /** M4 (polish): with an achievement id, true only if it was earned in an EARLIER run (MetaState.milestones
       *  'ach:<id>', recorded when a `when` achievement is granted): a chain of achievements across runs ("three
       *  springs"). Ignored for any other kind of id. Absent = false (plain owns). */
      earlier?: boolean }
  | { flag: string }
  /* --- M3 --- */
  | { returned: string; figure?: string; op?: CmpOp; value?: number }
  | { answered: string; arm?: number; run?: boolean; by?: 'player' }
  /** True once the feature is unlocked (Derived.features[id]; a feature not listed in Content.features is always on). */
  | { feature: FeatureId }
  /* --- M4 --- */
  /** M4: true once meta.endings[ending] exists (see above). */
  | { ending: string }
  /* --- M5 --- */
  /** M5: a loophole rung's state this run (see above). */
  | { loophole: string; status?: LoopholeStatus }
  | { all: Cond[] }
  | { any: Cond[] }
  | { not: Cond }
) & { label?: string };

/* ------------------------------------------------------------------ */
/* FEATURES (the unfolding: systems that arrive one at a time)         */
/* ------------------------------------------------------------------ */

/**
 * The unfolding (owner's direction, 19 Nov 2026: "options should be unlocked more slowly"). A FEATURE is a system the
 * player meets at a moment, not from the start. FEATURE_IDS is also the priority order when several are due at once.
 * What each gates, in the core (a gated action is refused, returning the same state; a gated accrual does not run) and
 * on the page (a locked feature is not shown at all):
 *   'reboundMeter'   the rebound meter reading and the cards' projection lines (both also need flags.revealed, as
 *                    before). The core gates nothing; it is the anchor the next feature is spaced from.
 *   'levers'         every lever and Mandate on the page. LeverView.visible needs it (a seated Institution's startLever
 *                    lever is visible regardless); setLever refuses an invisible lever.
 *   'population'     the population gauge (page only).
 *   'market'         the Market: OrdersView.market.available needs it as well as GlobalParams.orders.marketFromReckoning.
 *   'moreLevers'     the fuller lever: levers whose LeverDef.requires names 'moreLevers', and the recycle choice
 *                    (LeverView.recycleChoices holds only the default option; setLeverRecycle refuses).
 *   'charters'       the Charter offer: reckon() draws GameState.charterOffer only once it is unlocked.
 *   'budget'         budget lines: drawBudget refuses; setLever draws no line; an active cap draws no standing line (so
 *                    no decade streak can run); levers whose requires name 'budget' (the caps) are hidden.
 *   'leverRepeat'    "Tighten": levels past the authored ones. LeverView.maxLevel and next stop at levels.length;
 *                    setLever refuses a higher level.
 *   'dividendChoice' decade dividend offers: a decade appends no PendingDividend (it still pays its decadeEffects).
 *   'budgetPace'     the pace of a line: drawBudget refuses any pace but the sector's first.
 *   'clearSkies'     the clear level and the sink line: no 'clearSkies' headline or event and BudgetState.clearAt
 *                    stays unset; HistorySample.sink is not recorded; SectorDerived.clearP and sinkR read null. (Lean
 *                    against full decades is a page matter that arrives with it.)
 *   'steadyState'    the Steady streak: SectorState.clearYears does not accrue (so no Steady State), and
 *                    GameState.steadyYearsAll does not either.
 *   'commons'        the Commons: Derived.commons.available needs it as well as GlobalParams.commons.fromReckoning.
 *   'settlement'     Settlement: SectorDerived.canSettle and settle() need it.
 * A feature absent from Content.features is always unlocked, so content without `features` (the test fixture) plays
 * exactly as before.
 * M4: 'estimates' (see M4FeatureId), placed after 'survey'. (M3's 'survey' is the household return; M4's survey of a
 * stock is an effect, EffectDef 'survey', not a feature.)
 * M5: 'chair', 'loopholes', 'inspection', 'treasury', 'statecraft', 'charge', 'treaty' (see M5FeatureId), placed after
 * 'estimates' (so 'histories' and 'bank' move seven places later in the priority order).
 */
export const FEATURE_IDS = [
  'reboundMeter', 'levers', 'population', 'market', 'moreLevers', 'charters', 'budget', 'leverRepeat', 'dividendChoice',
  'budgetPace', 'clearSkies', 'steadyState', 'commons', 'settlement',
  // M3 (every M3FeatureId), in the order of their intended arrival (design/m3-contract-notes.md §0).
  'archive', 'ambient', 'dispatches', 'seams', 'load', 'travel', 'sideEffects', 'freeAtUse', 'survey',
  // M4 (M4FeatureId), inserted after 'survey' (design/m4-contract-notes.md §15.2).
  'estimates',
  // M5 (M5FeatureId), inserted after 'estimates', in arrival order (design/m5-contract-notes.md §11).
  'chair', 'loopholes', 'inspection', 'treasury', 'statecraft', 'charge', 'treaty',
  'histories', 'bank',
] as const;
export type FeatureId = typeof FEATURE_IDS[number];

/**
 * One feature's arrival (Content.features[id]). It unlocks on the first unlock check at which `when` holds and at least
 * GlobalParams.featureGapSeconds of play (meta.totalSeconds) have passed since the last feature unlocked; at most one
 * feature unlocks per check, the first due in FEATURE_IDS order. Unlock checks: in tick(), on each step that crosses a
 * multiple of 5 s of run time (reading the state at the start of the step, as achievements do; never inside fastForward, so nothing arrives unseen while
 * away: it arrives seconds after the player returns), and in reckon() on the new run (for features that wait on a
 * Reckoning). Once unlocked a feature stays unlocked for good, across Reckonings (MetaState.features): a lesson learnt
 * stays learnt. Unlocking records meta.features[id] = meta.totalSeconds, adds a news item whose text is `intro` (key
 * 'featureUnlocked'; none without an intro) and emits a 'featureUnlocked' event (id = the feature).
 */
export interface FeatureDef {
  when: Cond;
  /** The one line that introduces it, in the broadsheet's voice (a headline). Default: none. */
  intro?: string;
  /** Its name on the page's "New" mark ("Counter-levers"). Default: none (the page names it itself). */
  name?: string;
}

/* ------------------------------------------------------------------ */
/* CONTENT (static data, never changes during play)                    */
/* ------------------------------------------------------------------ */

export interface Content {
  /** M1 CHANGE (was `eras`): every sector, keyed by id. */
  sectors: Record<SectorId, SectorDef>;
  /**
   * M1: the order sectors are listed, iterated and (by default) unlocked in. Contains every key of `sectors` exactly
   * once. sectorOrder[0] is open at the start of every run.
   */
  sectorOrder: SectorId[];
  /** M1: the ages, in calendar order. Every sector belongs to exactly one age (AgeDef.sectors). */
  ages: AgeDef[];
  upgrades: UpgradeDef[];
  levers: LeverDef[];
  knowhow: KnowhowDef[];
  institutions: InstitutionDef[];
  achievements: AchievementDef[];
  /**
   * Broadsheet headline variants keyed by event (the fallback set). Placeholders substituted by the model:
   * `{sector}` sector name (on screen an industry), `{age}` age name, `{app}` application name, `{resource}`,
   * `{service}`, `{year}` calendar year (integer), `{n}` an event count (the decade number for 'decade', the crisis
   * number for 'crisis', else empty). M2: `{name}` the name of the Commons project ('commonsBuilt') or Charter
   * ('charter'), kept as authored (a proper name), else empty. Variant choice is deterministic from state.seed, time and the news count.
   * M1 balance: substitution is case-aware. `{app}`, `{resource}` and `{service}` are common nouns: away from the start
   * of a sentence their first letter is lower-cased ("demand for coal"), unless the name starts with an acronym ("AI
   * models") — only the first letter is touched, so later proper nouns survive. `{age}` lower-cases a leading "The"
   * mid-sentence ("Welcome to the Coal Age"). `{sector}` is the proper name of an industry and is kept as authored.
   * A sentence starts at the beginning of the template or after . ! or ? and a space (opening quotes allowed).
   * Content should therefore author those names in sentence case with any proper noun after the first word.
   */
  headlines: Record<HeadlineKey, string[]>;
  /**
   * M1: sector-specific variants. When an event belongs to a sector and `sectorHeadlines[sector][key]` is a non-empty
   * array, it is used instead of `headlines[key]`. Default: absent (everything falls back to `headlines`).
   */
  sectorHeadlines?: Record<SectorId, Partial<Record<HeadlineKey, string[]>>>;
  global: GlobalParams;
  /* --- M2 --- */
  /**
   * M2: every decade dividend, flat (ids unique game-wide). Pairs of ids are offered per decade (SteadyParams
   * .decadeChoices). Default: [] (no choices; decades pay only their decadeEffects, as in M1).
   */
  dividends?: DividendDef[];
  /** M2: the Commons projects, in display order. Default: [] (no Commons). */
  commons?: CommonsDef[];
  /** M2: the Charters, in content order (the order the deterministic draw indexes; see GameState.charterOffer). Default: []. */
  charters?: CharterDef[];
  /**
   * M2: display names of Know-how trees (KnowhowDef.tree), keyed by tree id. Default for a missing tree: the UI shows
   * the tree id with its first letter capitalised. Content should name every tree it uses (the lint checks).
   */
  knowhowTrees?: Record<string, { name: string; blurb?: string;
    /**
     * M5: 'rival': an industrial tree. At takeOffice its levels move from meta.knowhow to meta.office.handedOver (the
     * rival's head start; RivalDef.knowhowTransfer) and, while office is taken, its nodes are not bought (KnowhowView
     * .held true, canBuy false; buyKnowhow refuses). Absent: the player's tree (Statecraft; any tree not held). */
    holder?: 'rival' }>;
  /**
   * M2: player-facing wording of the recycle options (button name and one-line explanation). A lever may override the
   * blurb (LeverDef.recycleBlurb). Default for a missing option: name = the option id capitalised, blurb ''.
   * LeverView.recycleChoices carries the resolved wording; the UI does not resolve it itself.
   */
  recycleText?: Partial<Record<LeverRecycle, { name: string; blurb: string }>>;
  /** The unfolding: when each feature arrives (see FeatureDef). Default: absent (every feature unlocked from the start). */
  features?: Partial<Record<FeatureId, FeatureDef>>;
  /* --- M3 (all optional; absent = the M2 game) --- */
  /** M3: the recurring cast who write to the proprietor (CastDef). Default []. */
  cast?: CastDef[];
  /** M3: every dispatch, flat (ids unique game-wide; content order is the tie-break order of the draw). Default []. */
  dispatches?: DispatchDef[];
  /** M3: ambient headline templates (AmbientDef). Default []. */
  ambient?: AmbientDef[];
  /** M3: the Histories, in display order (HistoryDef). Default []. */
  histories?: HistoryDef[];
  /** M3: Archive notes (ArchiveDef), in display order. Default []. */
  archive?: ArchiveDef[];
  /** M3: the Proprietor's Day texts: the pamphlet and the return templates (ProprietorText). Default: absent (the
   *  core falls back to a one-line headline "Household survey published" and an empty body). */
  proprietor?: ProprietorText;
  /** M3: the first ending's credits and retrospective templates (EndingText). Default: absent (the UI shows a plain
   *  "Steady State" card with the core's retrospective items untitled). */
  ending?: EndingText;
  /* --- M4 (all optional; absent = the M3 game) --- */
  /** M4: the Acts, in order (ActDef). Default: absent (the M3 game: one implicit ending over sectorOrder, no capstone). */
  acts?: ActDef[];
  /**
   * M4: the Board's Survey card (the M4 moment; see RenewableDef.firstSurvey and Derived.surveyReveal). Placeholders,
   * formatted by the core: {reported} (catch per trip, integer per cent), {true} (the stock, integer per cent),
   * {sector}, {year}, plus the usual. The variant is chosen by the gap g = reported − true at the moment: 'failed' when
   * the sector has crossed its threshold this run (SectorState.crossed), else 'small' when g < SURVEY_SMALL_GAP (0.15),
   * else 'large'. Lint: one variant of each kind. Default: absent (no card; the 'surveyed' headline falls back to
   * Content.headlines.surveyed).
   */
  surveyReveal?: {
    variants: { when: 'small' | 'large' | 'failed'; headline: string; body: string }[];
    /** Column heads: "The skippers' report" / "The Board's survey". */
    columns: { reported: string; surveyed: string };
    /** The reach-back paragraph (the Statistics Office's two notes). */
    footer: string;
    /** "File the survey". */
    button: string;
    /** The headline printed on the step after the reveal ("Skippers dispute the survey…"), key 'surveyed'. Default: none. */
    followUp?: string;
  };
  /* --- M5 (all optional; absent = the M4 game: no office is ever offered, no Ministry exists) --- */
  /** M5: Take office: the invitation's condition and its texts (OfficeDef). Absent: office is never offered. */
  office?: OfficeDef;
  /** M5: the Chair's numbers (ChairDef). A Ministry needs `office`, `chair` and `rival` all present. */
  chair?: ChairDef;
  /** M5: the rival (RivalDef). */
  rival?: RivalDef;
  /** M5: every pledge, flat, in content order (the order the offer draw indexes; PledgeDef). Default []. */
  pledges?: PledgeDef[];
  /** M5: every loophole rung, flat (ids unique game-wide; LoopholeDef). Default []. */
  loopholes?: LoopholeDef[];
  /** M5: the Treaty's Articles, in display order (ArticleDef). Default []. */
  articles?: ArticleDef[];
  /** M5: the rival's playbooks (PlaybookDef). Default []. */
  playbooks?: PlaybookDef[];
}

/**
 * M4: an Act (Content.acts): a run of Ages with one ending, after which its Industries are settled for good (the
 * capstone). Acts are in order; the CURRENT act is the first whose ending has not been reached (meta.endings[ending.id]
 * absent; an act with no `ending` is never "reached", so it stays current once it is the first such), or null once
 * every act's has. Content without `acts` plays as M3 (the first ending is every Industry in sectorOrder settled; no
 * capstone). Lint: ids unique; each age in at most one act; ending.sectors belong to the act's ages and have `settle`.
 */
export interface ActDef {
  /** 'actOne'. Also the EndingRecord key of its ending when ending.id is the same (content's choice). */
  id: string;
  /** On screen: "Act I". */
  name: string;
  /** "The Coal Age". Shown on the Act title card with `name`. */
  title: string;
  /** Ages in this act, in order (each age in at most one act). */
  ages: AgeId[];
  /**
   * The ending: every sector in `sectors` open and settled (a capstoned sector counts as settled) at a step's start and
   * end, held GlobalParams.endingYears model years (GameState.steadyYearsAll). Reaching it writes meta.endings[id] and,
   * if `capstone`, meta.world.capstone (CapstoneRecord). Absent: this act has no ending (its Industries are never
   * capstoned; a Preview act).
   */
  ending?: { id: string; sectors: SectorId[] };
  /**
   * The capstone (after the ending): every sector in ending.sectors opens settled at the start of every later run.
   *   incomeShare  share of the recorded settled income paid while capstoned, 0–1. Default CAPSTONE_INCOME_SHARE (0.25).
   *   hindsight    whether capstoned sectors count in perSectorReached and perSettledSector. Default false.
   * Absent: no capstone.
   */
  capstone?: { incomeShare?: number; hindsight?: boolean };
  /**
   * This act's own rules are not built yet: its sectors play under Act I's rules and are labelled "Preview"
   * (SectorDerived.preview). They are never part of an act's ending set. Content sets it on Acts II and III in M4; M5
   * removes it from Act II. Default false. Re-gating the Previews is content only: their unlock.when becomes
   * { all: [ { any: [ { ending: 'actOne' }, { owns: '<self>' } ] }, …opening conditions… ] }.
   * M5 CHANGE: SectorDerived.preview = act.preview || (act.chair === 'government' && !meta.office).
   */
  preview?: boolean;
  /* --- M5 --- */
  /**
   * M5: the chair this act is played from once office is taken. 'government': while MetaState.office is absent the
   * act's sectors open as Previews under Act I's rules (exactly as `preview: true` in M4; SectorDerived.preview true);
   * from takeOffice on, every run is a Ministry (GameState.chair non-null) and the act's sectors are CHAIR SECTORS: they
   * open under the Chair, are run by the rival (RivalDef; buyUpgrade and foundApp refuse them; the Market skips them;
   * the rival buys and founds at order ticks) and are not Previews (SectorDerived.rival true). An act with `chair` has
   * no `ending` in M5 (the Act II ending is M6–M7's), so steadyYearsAll stays 0 while it is current. Default: absent
   * (the industrialist's chair: M4 behaviour).
   * Words: "chair sector" in this file = an open sector of an act with chair 'government', in a Ministry. "Rival
   * sector" = a chair sector or a capstoned sector (CapstoneRecord) in a Ministry: the rival owns both, reports both,
   * and conceals in both (the capstone is "held by Pryce Consolidated under the Settlement Acts").
   */
  chair?: 'government';
  /**
   * M5: the act's sectors cannot open while office is taken (a Ministry): Act III in M5. Their SectorState stays closed
   * (not opened, not in Derived.nextSectors); those in meta.sectorsOpened are listed in Derived.office.sealed so the
   * page can show a sealed postcard ("The Attention Age · in preparation · your record: …"); their meta records
   * (sectorsOpened, steadySectors, milestones, archive) are kept. Before office is taken they open as before (Previews).
   * Default false.
   */
  closedInOffice?: boolean;
}

/**
 * M1: a period of the calendar. The page theme belongs to the age; a sector adds only an accent.
 * Later an age may own a prestige layer (a field such as `layer` will be added then); nothing depends on that now.
 */
export interface AgeDef {
  id: AgeId;
  /** On screen: "The Coal Age", "The Great Acceleration"… */
  name: string;
  /** One line shown when the age begins. */
  tagline: string;
  /**
   * Calendar span [first, last]. last may be Infinity. Calendar of the age while any of its sectors is open:
   *   y = max( yearSpan[0] + T × YEARS_PER_SECOND,  max over its open sectors s of (s.firstYear ?? yearSpan[0]) + s.openFor × YEARS_PER_SECOND )
   *   with T = the largest openFor among its open sectors (time since the age began);
   *   if y > yearSpan[1]: y = yearSpan[1] + (y − yearSpan[1]) × CALENDAR_LATE_RATE.
   * Derived.year = max over ages with an open sector (so it never runs backwards when something opens).
   * QA FIX (B3, src/core/calendar.ts): the calendar never jumps and never runs absurdly far past an Age.
   *   - Each term above is a clock opened at a run time (an Age's own when its first sector opens; a sector's when it
   *     opens). A clock that opens AHEAD of the calendar as it then stands (Light's 1870 when Steam has reached 1810)
   *     catches up with it over CALENDAR_CATCHUP_SECONDS (120 s of run time, smoothstep) from the year it opened in,
   *     instead of jumping; once caught up the formula above holds exactly.
   *   - The slowing past yearSpan[1] starts at CALENDAR_LATE_RATE and levels off: yearSpan[1] + L × (1 − e^(−x × rate / L))
   *     with x = y − yearSpan[1] and L = CALENDAR_LATE_SPAN (36 years), so the Coal Age never reads past 1950.
   * Model years, decades and every timer are unaffected (the calendar is cosmetic). Headlines and events carry it.
   */
  yearSpan: [number, number];
  /**
   * Page theme key; the UI keeps a registry of looks. M1 looks: 'ledger', 'gaslight', 'chrome', 'terminal', 'agentic'.
   * Unknown keys fall back to the UI's default look.
   */
  theme: string;
  /** Sector ids that belong to (and can open in) this age, in display order. */
  sectors: SectorId[];
}

export interface GlobalParams {
  /** Starting capital of a fresh run. */
  startCapital: number;
  /**
   * Seconds of current income granted per manual click (the "sell power by hand" button).
   * Click value = clickFlat + clickSeconds × income per second (Derived.clickValue).
   */
  clickSeconds: number;
  /** Flat capital per click so the very first click does something. */
  clickFlat: number;
  /**
   * Population growth rate per second per point of wellbeing above subsistence. Population starts at 1.
   * Growth per second g(W), with W wellbeing, s = subsistence, mul = Π popGrowthMul effects:
   *   W < s:                       g = popGrowth · mul · (W − s) · 0.25            (decline at a quarter strength)
   *   W ≥ s, no demography:        g = popGrowth · mul · (W − s)                   (v1)
   *   W ≥ s, demography.W_t > s:   g = popGrowth · mul · (W − s) · max(0, 1 − ((W − s) / (W_t − s))²)
   * dN/dt = g · N. Each crisis multiplies N by (1 − crisisPopLoss). N never falls below 0.01.
   * With demography, growth peaks at W = s + (W_t − s)/√3 and stops at W ≥ W_t (the demographic transition).
   */
  popGrowth: number;
  /** Wellbeing (0–100 scale) below which population does not grow. */
  subsistence: number;
  /** Wellbeing the player must hold for decoupling (and so Steady State). Must be below demography.transitionWellbeing. */
  wellbeingTarget: number;
  /** Mandate per second per point of wellbeing above `mandateFloor`. */
  mandateRate: number;
  mandateFloor: number;
  /** Mandate granted by each Pressure crisis (the political window). */
  crisisMandate: number;
  /** Fraction of population lost in each Pressure crisis. */
  crisisPopLoss: number;
  /**
   * M1 CHANGE: Hindsight weights. See ModelApi.hindsightOnReckon and HindsightTerms; every term is ≥ 0.
   *   perWellbeingYear   × wellbeing-years (∫ max(0, W − subsistence) d(model years)) ÷ max(1, intensity)^intensityExponent
   *   intensityExponent  0 ignores how much was burnt; 1 divides by the run's average burn fold
   *   perBudgetDecade    × FULL decades completed within budget this run (all sectors): M2 CHANGE, run.budgetDecades −
   *                      run.leanDecades (a lean decade is one judged against the drawn wellbeing; see SteadyParams)
   *   perLeanDecade      M2: × lean decades this run (run.leanDecades). Default 0: a lean decade pays its dividend and
   *                      no Hindsight (design/m2-contract-notes.md, decision (a))
   *   perUnburnt         × Σ over open stock sectors of (share of reserve left) × min(1, yearsAtTarget / STEADY_STATE_YEARS)
   *   perFirstBackfire   × sectors whose FIRST-EVER backfire happened this run (failure teaches, once per sector)
   *   perSectorReached   × (sectors open at the Reckoning − 1)
   *   perSteadySector    × sectors that reached Steady State this run
   *   perSettledSector   M2: × sectors settled (SectorState.settled ≠ null) at the moment of the Reckoning. Default 0.
   * M4: capstoned sectors (SectorState.capstoned) are left out of perSectorReached and perSettledSector unless their
   * act's capstone.hindsight is true; they count in wellbeing-years and in the intensity like any sector. perUnburnt
   * counts every open 'renewable' sector as Q / K (the true stock), ramped by yearsAtTarget as stock sectors are; a
   * sector with resourceStock is not counted (its reserve is the owner's, counted once).
   */
  hindsight: {
    perWellbeingYear: number;
    intensityExponent: number;
    perBudgetDecade: number;
    perUnburnt: number;
    perFirstBackfire: number;
    perSectorReached: number;
    perSteadySector: number;
    perLeanDecade?: number;
    perSettledSector?: number;
    /**
     * M4 (polish): once the 'budget' feature is on, perUnburnt is further × min(1, full decades this run ÷ this): coal
     * left in the ground counts when a line has been kept, not when the smoke stopped the burning first. Before the
     * budget arrives (runs 1–2) the term is as before. Absent (or ≤ 0): no factor (M1–M4 behaviour).
     */
    unburntDecades?: number;
  };
  /**
   * Offline progress cap in seconds. M2 CHANGE: DEPRECATED, replaced by `offline.capSeconds`; read only when `offline`
   * is absent. Default (both absent): 14400 (4 h).
   */
  offlineCapSeconds?: number;
  /**
   * M2: offline catch-up (ModelApi.fastForward). Default when absent:
   * { capSeconds: offlineCapSeconds ?? 14400, holdBefore: 'collapse' }.
   *   capSeconds  base cap; the effective cap (Derived.offlineCapSeconds) = capSeconds + Σ standing offlineCapAdd effects.
   *   holdBefore  what fastForward will not cross unseen. 'crisis': it stops one step before a step that would fire a
   *               crisis (any sector), collapse a sector or exhaust a stock; 'collapse': before a collapse or an
   *               exhaustion; null: it holds nothing (M1 behaviour: a run can end offline). See ModelApi.fastForward.
   *               M4: 'crisis' and 'collapse' also stop one step before a step that would put a capstoned sector into
   *               arrears (OfflineReport.heldBy 'arrears'). A depletion sector's crises are crises like any other.
   *   hindsightRate  M2 (offline fix): the rate, 0–1, at which Hindsight accrues inside fastForward. Default 1 (full
   *               rate). Everything else a catch-up does counts in full (capital, Mandate, population, the reserve and
   *               pressure, decades and their decadeEffects, the streaks, Steady State, unlocks); only the Hindsight a
   *               Reckoning would pay is entered at this rate. The rule, per fastForward call: let H0 and H1 be the
   *               unrounded sum of the seven weighted HindsightTerms at the start and at the end of the catch-up (the
   *               hold's discarded step excluded); run.hindsightWithheld += (1 − hindsightRate) × (H1 − H0), written
   *               only when that is not 0. Hindsight is a function of the state, so the sum telescopes: one 8-hour call
   *               and eight 1-hour calls withhold the same (to rounding), and an absence earns hindsightRate × what the
   *               same hours earn on the untouched board. See RunStats.hindsightWithheld and HindsightTerms.withheld.
   */
  offline?: {
    capSeconds: number; holdBefore: 'crisis' | 'collapse' | null; hindsightRate?: number;
    /**
     * M3: banked time (optional; default OFF). bankRate 0–1 (default 0 = nothing is banked). After each fastForward
     * that stopped short of its request because of a hold or the cap (OfflineReport.heldBy 'crisis' | 'collapse' |
     * 'exhausted' | 'cap'), and only while feature 'bank' is on:
     *   meta.bankedSeconds = min(bankMax, meta.bankedSeconds + bankRate × (requested − simulated))
     * (OfflineReport.banked records the addition). bankMax default 0, which also means OFF. Spent with ModelApi.useBank.
     * Time forfeited because a Reckoning was already pending ('pending') is not banked.
     */
    bankRate?: number;
    bankMax?: number;
  };
  /**
   * M1: the demographic transition (see popGrowth). Default: absent = v1 linear growth with no ceiling.
   * transitionWellbeing W_t must exceed subsistence, and should exceed wellbeingTarget so a steady economy can hold
   * the target without growing.
   */
  demography?: { transitionWellbeing: number };
  /**
   * M1: budgets and Steady State (see SectorState.budget, SectorDerived.decoupling). Default when absent:
   * { budgetDeclinePerDecade: 0.05, decadeYears: 10, decadeEffects: [], firstSteadyEffects: [] }.
   *   budgetDeclinePerDecade  budgetR(t) = max(floor · r0, r0 · (1 − d)^(y / 10)), y = model years since drawn,
   *                           counted only until the line is HELD (BudgetState.heldAt). A sector may override.
   *                           M1 BALANCE CHANGE: the line declines until the sector reaches Steady State on it, then
   *                           holds level for the rest of the run (until redrawn). Steady State is earned by real
   *                           decline (50 streak years ≥ five decades of it); once earned it is keepable indefinitely.
   *   budgetFloor             M1 BALANCE: the line never falls below this fraction of r0. Default 0 (no floor).
   *   standingDrawYears       M1 BALANCE: an active cap with no budget (an institution's standing cap) draws its line
   *                           automatically only once the sector has been open this many model years (on the first step
   *                           with demand after that), so it is drawn across a grown economy rather than the opening
   *                           one. Default 0 (the first step with demand). A sector may override.
   *   decadeYears             streak length of one "decade within budget" (milestone). Default 10.
   *   decadeEffects           applied each time any sector completes a decade within budget (unless it overrides).
   *                           One-off effects pay at that moment; standing effects stay for the rest of the run, once
   *                           per decade earned (two decades of `wellbeingAdd 1` give +2).
   *   firstSteadyEffects      applied once, the first time EVER a given sector reaches Steady State (meta.steadySectors
   *                           flips true); typically `slotAdd`.
   * M2 adds the fields of SteadyParams (see there): decadeWellbeing, drawnSlack, clearBelow, clearFloor, clearCeiling,
   * paces, decadeChoices. M2 CHANGE: one-off amounts of decadeEffects (mandateAdd, capitalAdd) are multiplied by the
   * line's pace dividendMul.
   */
  steady?: SteadyParams;
  /**
   * M1: levy (duty and cap permit) revenue routed by the 'treasury' recycle option. Default: { mandateShare: 0.1 }.
   * mandateShare of treasury-routed revenue becomes Mandate per second; the rest is general taxation and vanishes.
   * Levy revenue is never player income.
   */
  levy?: { mandateShare: number };
  /** M1: Institution seats a brand-new player has (MetaState.slots of a fresh meta). Default 2. */
  startingSlots?: number;
  /* --- M2 --- */
  /**
   * M2: standing orders (see OrdersState). Default when absent:
   * { marketFromReckoning: 1, marketPaybackMax: 120, paybackChoices: [30, 120, 600], intervalYears: 1 }.
   *   marketFromReckoning  the Market is available once meta.reckonings ≥ this (run 2 by default), or earlier while a
   *                        standing orderUnlock 'market' effect is in force.
   *   marketPaybackMax     paybackMax of a fresh OrdersState, in seconds.
   *   paybackChoices       the payback settings the UI offers (seconds); setOrders accepts any value in [1, 86400].
   *   intervalYears        model years between order ticks (1 = every 20 s of run time). See OrdersState.
   */
  orders?: { marketFromReckoning?: number; marketPaybackMax?: number; paybackChoices?: number[]; intervalYears?: number };
  /**
   * M2: the Commons (see CommonsDef). Default when absent: { fromReckoning: 2, fundShare: 1 }.
   *   fromReckoning  Commons projects are offered once meta.reckonings ≥ this (run 3 by default).
   *   fundShare      share of levy revenue routed to 'commons' that reaches GameState.commons.fund (the rest vanishes).
   */
  commons?: { fromReckoning?: number; fundShare?: number };
  /**
   * M2: the share of the Hindsight spent on Know-how that respecKnowhow refunds, 0–1. Default 1 (a free respec
   * between runs; design/m2-contract-notes.md, decision (h)).
   */
  respecRefund?: number;
  /** The unfolding: least play (meta.totalSeconds) between two features unlocking (see FeatureDef). Default 0. */
  featureGapSeconds?: number;
  /* --- M3 --- */
  /**
   * M3: the dispatch scheduler (see GameState.dispatch). Default when absent:
   * { firstYears: 30, intervalYears: 8, jitter: 0.5, expiryYears: 12, maxPending: 1 }.
   *   firstYears    run time (model years) of the first draw of a run.
   *   intervalYears gap (model years) between a dispatch being RESOLVED (answered or defaulted) and the next draw,
   *                 before jitter. 8 model years = 160 s: about one letter every three minutes of play.
   *   jitter        0–1: the gap is intervalYears × (1 − jitter/2 + jitter × u), u ∈ [0, 1) from the seed (see
   *                 GameState.dispatch).
   *   expiryYears   default life of a pending dispatch (DispatchDef.expiryYears overrides), model years.
   *   maxPending    how many dispatches may wait at once (1–3). A draw is skipped while the list is full.
   */
  dispatch?: { firstYears?: number; intervalYears?: number; jitter?: number; expiryYears?: number; maxPending?: number };
  /**
   * M3: ambient news (AmbientDef). Default when absent: { everyYears: 4, cooldownYears: 30 }.
   *   everyYears     an ambient tick is a step from t0 to t1 with floor(t1 × YPS / everyYears) > floor(t0 × YPS /
   *                  everyYears); at each tick at most one ambient headline is printed.
   *   cooldownYears  default AmbientDef.cooldownYears.
   */
  ambient?: { everyYears?: number; cooldownYears?: number };
  /**
   * M3 (finish): model years the first ending must be held: every Industry in Content.sectorOrder open and settled at
   * once, without a break, for this long (see GameState.steadyYearsAll). Default STEADY_STATE_YEARS (50 model years,
   * 1000 s of run time: long enough that every settlement has to be defended through it, so the ending is a held
   * achievement rather than the instant the fifth Industry settles). ≥ 0; 0 means the moment all are settled.
   * M4: with Content.acts, the same length applies to every act's ending (over ActDef.ending.sectors).
   */
  endingYears?: number;
  /**
   * M3 (finish): what holding settlements costs together, so that five at once is a Mandate economy built over many
   * runs (Institutions, the Commons, levy income), not the moment the fifth Steady State arrives. With n Industries
   * settled now, EACH settled Industry costs holdUpkeep + holdStep × (n − 1) Mandate per second, on top of its own
   * excess defence (SectorDef.settle.upkeepPerSpill); the total is n × (holdUpkeep + holdStep × (n − 1)). It is part of
   * SectorDerived.settleDefence (and so of the lapse rule: once no lever upkeep is left to drop, the settled Industry
   * with the largest defence unsettles) and of Derived.mandatePerSec. Defaults 0 and 0 (M2's behaviour).
   */
  settleHold?: { holdUpkeep?: number; holdStep?: number };
  /**
   * M3 (finish): how many Industries may be settled at once, before any settleSlotAdd effect (Institutions bought
   * with Hindsight raise it). ModelApi.settle and SectorDerived.canSettle refuse a settlement beyond it; settlements
   * already held are never undone by it. Default: no limit. The first ending needs every Industry settled, so it waits
   * until the player has built the room for all of them (Derived.ending.room).
   */
  settleMax?: number;
}

/**
 * M2: the Steady State parameters (GlobalParams.steady, with per-sector overrides in SectorDef.steady). The M1 fields
 * keep their M1 meaning except where marked.
 */
export interface SteadyParams {
  /** M1 (see GlobalParams.steady). M2 CHANGE: used only to build the implicit pace when no `paces` are given. */
  budgetDeclinePerDecade: number;
  budgetFloor?: number;
  standingDrawYears?: number;
  decadeYears?: number;
  decadeEffects: EffectDef[];
  firstSteadyEffects?: EffectDef[];
  /**
   * M2: the wellbeing a DECADE is judged against (the decade streak; SectorDerived.decoupling).
   *   'drawn'  (default) decadeWellbeing = min(wellbeingTarget, BudgetState.w0 × (1 − drawnSlack)): nobody worse off
   *            than on the day the line was drawn, and never more than the target;
   *   'target' decadeWellbeing = wellbeingTarget (M1).
   * Steady State always needs the full wellbeingTarget (see SectorDerived.sinkHeld).
   */
  decadeWellbeing?: 'drawn' | 'target';
  /** M2: slack on the drawn wellbeing, 0–1. Default 0.05. */
  drawnSlack?: number;
  /**
   * M2: clear skies (the sink line). The clear level of a sector with a budget is
   *   clearP = clamp(clearBelow × BudgetState.p0, clearFloor × collapseAt, clearCeiling × collapseAt)
   * (the lower bound wins if the bounds cross). Defaults: clearBelow 0.5, clearFloor 0.03, clearCeiling 0.25.
   * The ceiling stops a line drawn at a pressure peak from making "half of it" easy (design/m2-contract-notes.md (b)).
   * A sector may override each (SectorDef.steady).
   */
  clearBelow?: number;
  clearFloor?: number;
  clearCeiling?: number;
  /**
   * M2: the paces a line can be drawn at, in display order; the FIRST is the default (used by drawBudget without a
   * pace, by the line a lever raise draws, and by a standing cap's line). Recommended ids 'gentle', 'firm', 'severe'.
   * Resolution for a sector: SectorDef.steady.paces ?? GlobalParams.steady.paces ?? [the implicit pace
   * { id: 'gentle', name: 'Gentle', declinePerDecade: SectorDef.steady.declinePerDecade ?? budgetDeclinePerDecade
   * ?? 0.05, dividendMul: 1 }]. A BudgetState whose pace id is not in its sector's resolved list uses the first pace.
   */
  paces?: PaceDef[];
  /**
   * M2: the dividend pairs offered at decades (ids into Content.dividends). The n-th decade a sector completes this run
   * (n = its decadesWithin.length after recording, 1-based) offers pair (n − 1) mod decadeChoices.length. Resolution:
   * SectorDef.steady.decadeChoices ?? GlobalParams.steady.decadeChoices ?? [] (empty: no offer). Pairs naming an
   * unknown id are skipped as if absent from the list (the lint catches them). See GameState.pendingDividends.
   */
  decadeChoices?: [string, string][];
}

/** M2: the pace of a budget line. */
export interface PaceDef {
  id: string;
  /** On screen: "Gentle", "Firm", "Severe". */
  name: string;
  /** One line ("5% a decade; the dividend as it stands"). Default ''. */
  blurb?: string;
  /** d in budgetR (see BudgetState), 0–1. */
  declinePerDecade: number;
  /** Multiplies the one-off amounts (mandateAdd, capitalAdd) of the decade's decadeEffects and of the dividend chosen
   *  for it. Standing effects and slotAdd are not scaled. ≥ 0. */
  dividendMul: number;
}

/**
 * M2: one decade dividend. Chosen with ModelApi.chooseDecadeDividend. One-off effects fire when chosen (mandateAdd and
 * capitalAdd × the offer's `mul`; capitalAdd measured against income at that moment; reserveAdd acts at once like a
 * purchase; reveal sets flags.revealed). Standing effects stay in force for the rest of the run, once per time chosen.
 * Content must not use slotAdd here (seats matter only between runs; the lint forbids it).
 */
export interface DividendDef {
  id: string;
  name: string;
  blurb: string;
  effects: EffectDef[];
  /**
   * QA FIX (the unfolding): offered only once this feature is on (an endowment of the Commons is no offer before the
   * Commons exist). A decade whose pair (in the sector's decadeChoices order) holds an option whose feature is off is
   * offered the next pair in that order whose options are all on (wrapping); if none is, the pair as authored.
   * Absent = always.
   */
  requires?: FeatureId;
}

/**
 * M2: a Commons project: where restraint's money goes, and itself a rebound. Bought with ModelApi.buyCommons; levels
 * last for the run (a Reckoning wipes them).
 *   Cost of the next level (L = levels owned): capital cost × costGrowth^L, Mandate mandateCost (flat per level).
 *   Wellbeing of the project at L levels: max × (1 − exp(−L × perLevel / max)) × Π commonsYieldMul (standing effects);
 *     the first level gives about `perLevel`, and no number of levels gives more than `max`. Added to W with the
 *     wellbeingAdd effects (before the ≥ 0 clamp). Not per head: population growth acts through demography as usual.
 *   Intensity (its own direct rebound): the project adds L × perLevel × N service units per second of price-proof
 *     demand to `intensity.sector` (as drawsOn does; N = population), only while that sector is open. A library is lit.
 *   Effects: standing effects × L (typically the time rebound: a satMul > 1 on a leisure application); one-off effects
 *     fire once per level bought.
 * The economy-wide rebound (more wellbeing, more people) needs no field: it is demography.
 */
export interface CommonsDef {
  id: string;
  name: string;
  blurb: string;
  /** Scene prop key (the scene keeps a library keyed by it; unknown keys get a generic civic building). */
  icon: string;
  /** The Industry it is listed under and drawn in. Absent: a general project, listed apart and drawn in no scene. */
  sector?: SectorId;
  cost: number;
  /** Default 1. */
  costGrowth?: number;
  /** Default 1 (a one-off project). */
  maxLevel?: number;
  /** Default 0. */
  mandateCost?: number;
  wellbeing: { max: number; perLevel: number };
  intensity?: { sector: SectorId; perLevel: number };
  effects?: EffectDef[];
  /** Offered only while this holds (and the Commons are open, and `sector`, if given, is open). Default: always. */
  requires?: Cond;
  /** M3: hidden (not visible, not buyable, not bought by Treasury rules) unless meta.unlocks[id] (a History reward) or
   *  a standing `unlock` effect names it. Default false. */
  locked?: boolean;
}

/**
 * M2: a Charter: one of two starting situations offered at each Reckoning, for the next run (ModelApi.chooseCharter).
 * Its effects act like a seated institution for that run only: standing effects in force, start-of-run effects
 * (startCapitalMul, reserveAdd, startLever, reveal, startFounded, institutionLoan) applied when the run is built,
 * one-off effects ignored. Mild, always on, no goal.
 */
export interface CharterDef {
  id: string;
  name: string;          // "The Northern Coalfield"
  blurb: string;         // names the rebound it tilts
  effects: EffectDef[];
  /** Offered only if this holds against the fresh run reckon() builds (see GameState.charterOffer). Default: always. */
  requires?: Cond;
  /** The Industry it mainly concerns (the UI shows its name; the scene may mark its landmark). Default: none. */
  sector?: SectorId;
  /** Optional scene key of a landmark the Charter adds to its sector's picture. Default: none. */
  landmark?: string;
  /** M3: left out of the offer draw (set E of GameState.charterOffer) unless meta.unlocks[id] (a History reward).
   *  Default false. Appending a locked Charter to content does not change the offers of saves that have not unlocked it. */
  locked?: boolean;
}

/* ------------------------------------------------------------------ */
/* M3 MECHANICS: four general kinds, attached to SectorDef by field    */
/* ------------------------------------------------------------------ */

/*
 * Each kind is optional on SectorDef; a sector without the field solves exactly as in M2. Several may be combined in one
 * sector; inside the solve they apply in this order for a trial service price p:
 *   1. priceSeen   each application's demand responds to its own seen price p_i(p) instead of p (ApplicationDef.priceSeen,
 *                  priceSeen effects);
 *   2. travel      the demand of the travel applications is scaled by the speed index v(D), which falls with total demand
 *                  D: demand at p is the unique fixed point D* of D = demandAt(p, v(D)) (TravelDef);
 *   3. load        the capital cost per unit of service c is scaled up by the idle plant: c_eff = c × ((1 − k) + k /
 *                  max(floor, LF)), LF the load factor of the demand mix at p (LoadDef). c_eff replaces c EVERYWHERE c
 *                  appears in the solve (p_pre, the substitution cost 1.5 × c, the cap's permit inversion, the Market's
 *                  pPre, SectorDerived.capCost, SettledState.pPre), each evaluated at the demand mix of the price tried.
 *   4. seams       the resource price of a stock sector is multiplied by the price multiplier of the deepest seam sunk
 *                  (SeamDef). Seams are state (SectorState.seamsSunk), not part of the fixed point.
 * Solve paths: a stock sector without substitution and without `load` keeps the closed form (p_s does not depend on D;
 * travel's inner fixed point in D is solved inside demand(p)); a sector WITH `load` uses the bisection on p that flow
 * sectors use (44 iterations), because c, and so p_s, depends on the mix. The shadow solve (η frozen) runs the same
 * mechanics (its own mix, its own congestion), so the rebound meter stays a counterfactual of the whole system.
 * Each kind teaches one named rebound and has a widget and a prop: seams (supply-side: cheap power reaches the next
 * seam; depletion postponed and enlarged), load (utilisation: idle plant makes the next unit cheapest to sell), travel
 * (induced demand and lock-in: speed buys distance; sprawl stays), priceSeen (the frontier at its limit: a price seen
 * as nil cannot be lowered). Code needs no new kind: its flow resource, upkeep and deletion are its mechanic, now
 * exposed as SectorDerived.upkeep.
 * Later kinds attach the same way, as one optional field each (design/m3-contract-notes.md §4): Fishing's renewable
 * stock is a new resourceKind; Iron's shared stock points at Steam's (seams then live on the owner of the stock);
 * Plenty's second gauge is a second stock; Comfort's ratchet is ApplicationDef.ratchet beside lockInDecay;
 * Proof-of-Work's difficulty is its own solve path.
 *
 * M4 kinds (each optional, absent = M3 behaviour):
 *   - feeds (ApplicationDef.feeds): a factor on the TARGET's c, joined before step 3 (load's c_eff multiplies whatever c
 *     results). A feed is an edge source → target in the solve order, beside spill and drawsOn.
 *   - the shared reserve (SectorDef.resourceStock): the drawer's p_r is the owner's (after step 4 on the owner) × the
 *     drawer's own resourcePriceMul.
 *   - the renewable stock (resourceKind 'renewable', RenewableDef): p_r = basePrice × reported^(−alpha) × Π
 *     resourcePriceMul, reported = (Q/K)^beta, in place of the stock price (seams do not apply). Q is state, not part
 *     of the fixed point. Foreign fleets (ForeignDef) drain Q outside the solve.
 * The shadow solve sees the feeds into a sector (they are not that sector's efficiency) and the owner's / reported
 * resource price as the live solve does.
 */

/** M3: one seam of a stock sector's ladder (SectorDef.seams), sunk in order with ModelApi.sinkSeam. */
export interface SeamDef {
  /** Unique game-wide ('steam.seam.barnsley'). Archive notes and `owns` refer to it. */
  id: string;
  /** "The Barnsley Bed". */
  name: string;
  /** One line. Default ''. */
  blurb?: string;
  /** Depth for display, in the sector's own words (the UI prints it as authored: "300 fathoms"). Default ''. */
  depth?: string;
  /** Resource units this seam adds to BOTH reserve and reserveMax when sunk (not scaled by any effect). */
  tons: number;
  /** Capital to sink it, × costMul effects (global) × costMulOf effects naming this seam id or its sector. */
  cost: number;
  /**
   * Resource-price multiplier from the moment this seam is sunk (deeper coal is dearer to raise), ≥ 0. For a stock
   * sector with seamsSunk = n ≥ 1: p_r = basePrice × seams[n − 1].priceMul × (reserveMax / Q)^alpha × Π resourcePriceMul;
   * with n = 0 the multiplier is 1. The deepest seam's multiplier applies to all the coal (the marginal ton sets the price).
   */
  priceMul: number;
  /** Reachable only while the sector's service price p_s ≤ this (cheap pumping power reaches it). Default Infinity. */
  reachBelow?: number;
  /** Also reachable only while this holds. Default: always. */
  requires?: Cond;
}

/**
 * M3: Light's load curve, a general utilisation kind (SectorDef.load). Capacity is built for the peak hour; the plant is
 * idle the rest of the day; the idle share is paid for by every unit sold.
 *   shape_a[h] = LOAD_HOURS × w_a[h] / Σ_h' w_a[h'] for the profile w_a of application a (mean 1 over the day);
 *     a profile whose weights sum to ≤ 0 is treated as flat (all 1).
 *   H[h] = Σ over founded applications a of D_a × shape_a[h]  +  extraD × shape_default[h]   (service per second, hour h)
 *   D = mean_h H[h] (the sector's demand);  peak = max_h H[h];  LF = D / peak (1 when D ≤ 0).
 *   c_eff = c × ((1 − fixedShare) + fixedShare / max(floor, LF))   with c = capCost × Π capCostMul.
 * Efficiency lowers p_s, the cheap night uses (low halfPrice, night profiles) adopt, LF rises, c_eff falls, p_s falls
 * again: the utility is paid to sell the hollows. Content compensates capCost so that the opening price is as before.
 */
export interface LoadDef {
  /** Named hourly profiles: each exactly LOAD_HOURS non-negative weights (hour 0 = midnight). Others are ignored (lint). */
  profiles: Record<string, number[]>;
  /** The profile of applications without ApplicationDef.profile, and of extra demand (drawsOn, Commons intensity). */
  defaultProfile: string;
  /** k, 0–1: the share of capCost that is plant built for the peak. */
  fixedShare: number;
  /** Lowest load factor used in c_eff. Default 0.05. */
  floor?: number;
}

/**
 * M3: Motion's travel-time budget, congestion and sprawl, a general kind (SectorDef.travel).
 *   K = roads × Π travelMul.roads (service per second at which traffic halves the speed);
 *   s = Π travelMul.speed (free speed index; 1 = the sector's opening speed);
 *   v(D) = s / (1 + (D / K)^b),  b = exponent ?? 4   (the speed index at total sector demand D, extraD included);
 *   each TRAVEL application's saturation S_a is multiplied by v(D) (non-travel applications and extraD are not);
 *   demand at price p is the unique D* ≥ 0 with D* = extraD + Σ_a max(F_a, S_a × g_a(D*) / (1 + (p_a / P_a)^k_a)),
 *     g_a = v for travel apps, 1 otherwise (the right side falls as D rises, so the root is unique; bisection on D in
 *     [extraD + Σ F_a, extraD + Σ max(F_a, S_a × max(1, s))], 40 iterations).
 * Marchetti's constant falls out: at saturation D ≈ N × S × v, so the time per head D / (N × v) stays put while the
 * miles grow with speed. Roads (K) fill again: more K, faster v, more demand until v falls back (Duranton & Turner).
 * Display: hoursPerHead = hoursScale × (D / N) / max(v, 1e-6) (hours a day; content scales it to about 1 at the start).
 * Sprawl is the lock-in floor (ApplicationDef.lockIn × peakD) made a stock that decays slowly (ApplicationDef.lockInDecay).
 * With roads very large and speed 1, v ≈ 1 and the sector behaves as in M2.
 */
export interface TravelDef {
  roads: number;
  /** b. Default 4. */
  exponent?: number;
  /** Display scale for hoursPerHead. */
  hoursScale: number;
  /** Ids of the travel applications. Default: every application of the sector. */
  apps?: string[];
}

/**
 * M4: a renewable stock (SectorDef.renewable; required with resourceKind 'renewable', which requires pressureSource
 * 'depletion': lint). K = SectorDef.reserve (the natural size; reserveAdd effects do not change it), reserveMax = K,
 * SectorState.reserve = Q.
 *   G(Q) = regen × Q × (1 − Q/K) × d × s      d = collapsed if Q < threshold × K, else 1; s = scar.mul while scarred, else 1
 * THE STEP for an open, unsettled renewable sector (module renewable.ts; one line in step.ts), per step of dt:
 *   1. R_home from the solve (as any sector); R_foreign by ForeignDef (0 without one).
 *   2. Q ← Q + (G(Q) − R_home × (1 − circularity share) − R_foreign) × dt, explicit; when |dQ| over the step exceeds
 *      RENEWABLE_SUBSTEP_SHARE × K the step is split into n = min(RENEWABLE_SUBSTEPS_MAX, ceil(|dQ| /
 *      (RENEWABLE_SUBSTEP_SHARE × K))) equal substeps (G and R_foreign re-evaluated per substep at the new Q, R_home held
 *      at the step's solve); Q is clamped to [RENEWABLE_FLOOR × K, K] after each.
 *   3. If Q < threshold × K and not SectorState.crossed: crossed = true; the scar is written; 'thresholdCrossed' event
 *      and 'threshold' headline.
 *   4. P = (1 − Q/K) × collapseAt (derived; pressureSource 'depletion'), crises at crisisAt as usual.
 *   5. The scar's yearsLeft decremented (see `scar`).
 * Settled (and capstoned): Q frozen, not stepped. In arrears: Q stepped with the arrears R (see SettledState).
 */
export interface RenewableDef {
  /** r: intrinsic regrowth rate per second (see G). > 0. */
  regen: number;
  /** θ: threshold as a fraction of K, 0–1. Below it d = collapsed; at or above it d = 1. */
  threshold: number;
  /** d below the threshold, 0–1 (depensation: the remnant cannot regrow). */
  collapsed: number;
  /** β of the reported stock (catch per unit effort = q × A^β; β < 1 is hyperstability). 0 < beta ≤ 1. */
  beta: number;
  /**
   * The scar written the first time Q falls below θK in a run (that step: 'thresholdCrossed' event and 'threshold'
   * headline; SectorState.crossed = true): meta.world.scars[s] = { yearsLeft: years, since: meta.totalSeconds }
   * (replacing an existing scar only if its yearsLeft is shorter). While a scar has yearsLeft > 0: s = mul in G (0–1);
   * yearsLeft −= the step's model years on every step the sector is open and unsettled (tick, fastForward and useBank
   * alike; not while settled or capstoned, not while closed); when it reaches 0 the scar is removed ('scarHealed' event
   * and headline).
   */
  scar: { mul: number; years: number };
  /**
   * The stock a run starts with (and the stock when the sector opens mid-run): K, unless scarred
   * (meta.world.scars[s] present), in which case min(K, startScarred × K): the bank does not refill between runs while
   * the scar lasts. Read in the carry-over step (inherit.ts), never assumed K. Default: `threshold`.
   */
  startScarred?: number;
  /** Foreign fleets (ForeignDef). Default: none. */
  foreign?: ForeignDef;
  /**
   * M4 (The Survey): the Board's first survey. Once per save per sector (meta.flags['survey:<s>'] absent), on the first
   * LIVE step (tick; never inside fastForward or useBank: it waits for the first live step after, as a letter does) at
   * which this sector, open and unsettled, has SectorState.crisesFired ≥ atCrisis OR openFor ≥ afterSeconds, the core:
   * adds a timed modifier { source: 'survey:<s>', arm: 0, since: time, until: time + years / YEARS_PER_SECOND } whose
   * effects are [{ type: 'survey', sector: s }] (ActiveModifier sources beginning 'survey:' are resolved by the core,
   * not looked up in dispatches; ModifierView.label = `label`); sets meta.flags['survey:<s>'] = true; stores
   * GameState.surveyReveal; emits 'surveyed' with first: true and label 'reveal' (and the reveal headline, see
   * Content.surveyReveal). Default: none (no free survey).
   *   label  the modifier's name on the page. Default "The Board's survey".
   */
  firstSurvey?: { atCrisis: number; afterSeconds: number; years: number; label?: string };
}

/**
 * M4: foreign fleets (RenewableDef.foreign). Rivals on the same stock whose fishing power follows the home fleet's
 * cheapness:
 *   share = clamp(share0 × (basePs / p_s)^growth × Π foreignMul, 0, cap)    (basePs: SectorState.basePs; share0 before
 *                                                                           the baseline exists)
 *   R_foreign = R_home × share / (1 − share)                                 (share is the foreign part of the TOTAL catch)
 * R_foreign drains Q and earns nothing; it is not on the home budget line, not in fullR, not in Hindsight's intensity,
 * not in spill. A settled (or capstoned) sector has no foreign catch (the settlement is a treaty as well as a quota).
 * cap < 1 (lint).
 */
export interface ForeignDef {
  share0: number;
  growth: number;
  cap: number;
  /**
   * M4 (finish): the foreign fleets fill the room the home fleet leaves: besides the share above, they take
   *   R_room = room × foreignMul × max(0, G(Q) − R_home)
   * (the surplus the bank grows beyond the home catch), so a home fleet held back on a healthy bank draws boats in, as
   * the commons do. R_foreign = R_home × share / (1 − share) + R_room; the reported foreign share (StatKey
   * 'foreignShare', SectorDerived.stock.foreign.share) is R_foreign / (R_foreign + R_home); the sink line and the survey
   * quota count it (the home catch that holds the clear level with the room taken). room in [0, 1) (lint). Default 0
   * (no field, no change).
   */
  room?: number;
  /** The share at which the 'foreignFleets' headline is printed, the first time it passes it in a run (no event;
   *  SectorState.foreignAnnounced). Default FOREIGN_ANNOUNCE_AT (0.15). */
  announceAt?: number;
}

/** M1 CHANGE (was EraDef): one service + resource economy. On screen: an "Industry". */
export interface SectorDef {
  id: SectorId;
  name: string;            // "Steam"
  /** Display only ("1780–1870"). */
  years: string;
  /**
   * M1: calendar year this sector's own clock starts at when it opens (see AgeDef.yearSpan). QA FIX: a sector opening
   * before its firstYear opens in the current year and the calendar catches up with its clock (no jump). Default: its
   * age's yearSpan[0].
   */
  firstYear?: number;
  tagline: string;         // one line shown when the sector opens
  /**
   * "Motive power", "hp" / "Coal", "tons". `unit` is the PLURAL form (as M1 content authored it: "features", "tons").
   * M2: `unitSingular` is the singular form ("feature", "ton"), used for exactly one unit and after "per" ("£1.57 per
   * feature"). Default: `unit` (for units with no plural, such as "hp" or "kWh").
   */
  service: { name: string; unit: string; unitSingular?: string };
  resource: { name: string; unit: string; unitSingular?: string };
  pressure: { name: string; crisisName: string }; // "Smog", "The Great Stink"
  /**
   * M1 CHANGE: the page theme moved to AgeDef.theme. `accent` is a small accent key the UI maps to a token set
   * (accent colour, pressure-weather tint) layered over the age's theme. Default: the age's own accent.
   */
  accent?: string;
  /**
   * M1 (transitional): full-theme override, used when this sector is selected. Lets the v1 looks ('gaslight' for
   * Light, 'agentic' for Code) survive inside a shared age until each age has its final look. Default: absent.
   * Expected to be removed when the ages get their final looks (M3–M4).
   */
  theme?: string;

  /* --- price side --- */
  /** p_0: base resource price. */
  basePrice: number;
  /** c: capital + labour cost per unit of service (before upgrades). Effective c = capCost × Π capCostMul. */
  capCost: number;
  /** m: the player's cut of spending on the service. Effective m = max(0, margin + Σ marginAdd). */
  margin: number;
  /** Starting efficiency η (service per unit resource). Usually 1. */
  baseEta: number;
  /**
   * Compute's twist. If > 0, η grows on its own by this exponential rate per second once the sector is open
   * (η = baseEta × Π etaMul × exp(autoEtaRate × openFor)). The player cannot switch it off.
   * Auto growth counts as efficiency gain: it is frozen out of the shadow solve like any other η gain.
   */
  autoEtaRate: number;

  /* --- resource side --- */
  /**
   * 'stock': a depletable reserve Q. p_r = basePrice × (reserveMax / Q)^alpha. Exhausted (forced Reckoning) once
   *          Q ≤ EXHAUSTED_BELOW × reserveMax (0.2%), not at exactly 0.
   *          M3 CHANGE: p_r = basePrice × seamPriceMul × (reserveMax / Q)^alpha × Π resourcePriceMul (see SeamDef;
   *          both factors are 1 by default).
   * 'flow' : a renewable capacity per second (Code's attention). p_r = basePrice × (1 / (1 − u))^alpha
   *          where u = min(0.98, R / usableCapacity). Never runs out; just gets scarce; service above u = 0.98 is rationed.
   *          M3 CHANGE: × Π resourcePriceMul.
   * M4: 'renewable': a stock Q that regrows (RenewableDef, required). K = `reserve` (the natural size, not changed by
   *          reserveAdd), reserveMax = K, SectorState.reserve = Q. Never exhausts (no forced Reckoning; Q floors at
   *          RENEWABLE_FLOOR × K). p_r = basePrice × reported^(−alpha) × Π resourcePriceMul, reported = (Q / K)^beta
   *          (the fleet's cost follows catch per trip, not the stock). Seams are ignored. Requires pressureSource
   *          'depletion' (lint). SectorDerived.reserveFraction reports the TRUE Q / K (the core's rules read it) and
   *          secondsLeft Infinity; the page reads SectorDerived.stock instead.
   */
  resourceKind: 'stock' | 'flow' | 'renewable';
  /** Q0 for 'stock'; capacity per second for 'flow'. Increased by reserveAdd effects (see EffectDef). */
  reserve: number;
  alpha: number;

  /* --- pressure side --- */
  /**
   * 'resource': P += R × intensity × dt  (smog, carbon)
   * 'service' : P += D × (1 − substituted share) × intensity × dt  (Code: every shipped feature adds to the code stock)
   * intensity = pressureIntensity × (1 − sharedLibs share). Then P decays: P ×= exp(−absorption × dt).
   * M4: 'depletion' (resourceKind 'renewable' only): P is not stepped; it is DERIVED each step as
   *   P = (1 − Q/K) × collapseAt.
   * absorption and pressureIntensity are ignored. Crises fire at crisisAt fractions as usual. collapseAt is never
   * crossed while Q > 0, so a depletion sector never collapses the run; its last crisis should sit at 1 − θ (lint) so
   * that crossing the threshold is a named crisis.
   * Clear skies and the sink line use the ordinary rules (SteadyParams.clearBelow × p0, clearFloor, clearCeiling): with
   * P derived, the net pressure rate is −collapseAt / K × dQ/dt (dQ/dt = G − R_home × (1 − circularity) − R_foreign),
   * so the Industry is clear when depletion has fallen to the clear level and the stock is not falling.
   * sinkR for a depletion sector: the home catch that holds the stock at its clear level Q_clear = K × (1 − clearP /
   * collapseAt), i.e. the R_home solving R_home × (1 − circularity) + R_foreign(R_home) = G(Q_clear) with today's foreign
   * share: sinkR = G(Q_clear) / ((1 − circularity) + share / (1 − share)). It is the TRUE value; SectorDerived.sinkR and
   * clearP read null while the sector is not surveyed (SectorDerived.stock).
   */
  pressureSource: 'resource' | 'service' | 'depletion';
  pressureIntensity: number;
  /** Fraction of P absorbed per second (plus absorptionAdd effects). 0 for Code (code never rots away on its own). */
  absorption: number;
  /** P at which the run collapses (forced Reckoning). */
  collapseAt: number;
  /** Crisis events fire the first time P crosses each of these fractions of collapseAt, e.g. [0.4, 0.7]. Ascending. */
  crisisAt: number[];
  /** Wellbeing points lost at P = collapseAt (scaled linearly below that). */
  pressureWellbeingCost: number;
  /**
   * Code's twist. Capacity eaten per unit of P per second (maintenance upkeep on the code stock).
   * effectiveCapacity = max(5% of capacity, capacity − P × pressureUpkeep); usable = effective × (1 − deletion share).
   * 0 elsewhere.
   */
  pressureUpkeep: number;

  /* --- wellbeing --- */
  /**
   * Weight of this service in wellbeing:
   *   W_s = wellbeingWeight × ln(1 + (D + D_div) / (N × wellbeingScale)) × defectFactor − pressureWellbeingCost × min(1, P / collapseAt)
   * D_div = (levy revenue of this sector routed to 'dividend') / p_s: the dividend counted as service it could buy.
   * defectFactor = 1 except in flow sectors (Code's unreviewed-work penalty, as v1).
   * W = max(0, Σ open sectors W_s + Σ wellbeingAdd effects).
   */
  wellbeingWeight: number;
  wellbeingScale: number;

  /* --- cross-sector links --- */
  /**
   * Indirect rebound. Money households save on this service is spent on another sector's.
   * Saturation of every application in `spill.to` is multiplied by
   *   1 + spill.rate × (1 − greenSpending share of this sector) × max(0, 1 − p_s / basePs)
   * (basePs = this sector's p_s when its baseline was recorded). Only while both are open.
   */
  spill?: { to: SectorId; rate: number };
  /** Code → Compute. Each unit of this sector's service adds this much service demand to `drawsOn.sector` (a price-proof floor). */
  drawsOn?: { sector: SectorId; perService: number };

  /* --- unlock --- */
  /**
   * sectorOrder[0] has no unlock and is open from the start. Any other sector opens on the first step at which ALL hold:
   *   - every sector in `after` is open (default: the sector before it in sectorOrder);
   *   - meta.reckonings ≥ minReckonings;
   *   - `when` evaluates true (M1: milestones that restraint does not block, e.g. an upgrade owned and an amount of
   *     service delivered);
   *   - only if `when` is ABSENT: the default predecessor's servicePrice < prevServicePriceBelow (DEPRECATED v1 gate;
   *     ignored whenever `when` is present).
   * A sector with no `unlock` (other than sectorOrder[0]) opens as soon as its predecessor is open.
   * Several sectors may open in the same step.
   */
  unlock?: { when?: Cond; minReckonings: number; after?: SectorId[]; prevServicePriceBelow?: number };

  /**
   * M1: per-sector overrides of GlobalParams.steady. Default: absent (global values).
   * declinePerDecade replaces budgetDeclinePerDecade; decadeEffects replaces the global decadeEffects for decades
   * this sector completes; budgetFloor and standingDrawYears replace the global ones (M1 balance).
   * M2: clearBelow, clearFloor, clearCeiling, paces and decadeChoices replace the global ones for this sector (see
   * SteadyParams). M2 CHANGE: declinePerDecade only shapes the implicit pace when no paces are given.
   */
  steady?: {
    declinePerDecade?: number; decadeEffects?: EffectDef[]; budgetFloor?: number; standingDrawYears?: number;
    clearBelow?: number; clearFloor?: number; clearCeiling?: number; paces?: PaceDef[]; decadeChoices?: [string, string][];
  };

  /**
   * M2: Settlement (ModelApi.settle). Absent: this sector can never be settled.
   *   dividend        effects of being settled: standing effects in force while settled; one-off effects fire on the
   *                   FIRST settlement of this sector in a run only (SectorState.settledBefore), so settling and
   *                   unsettling farms nothing.
   *   upkeepPerSpill  Mandate per second per unit of excess demand pressure on the settled sector (see SettledState).
   *   freeExcess      excess tolerated without upkeep. Default 0.05.
   *   blurb           one line for the Settle ceremony. Default ''.
   */
  settle?: {
    dividend: EffectDef[]; upkeepPerSpill: number; freeExcess?: number; blurb?: string;
    /**
     * M4: settling also needs this (Fishing: { stat: 'surveyed', sector: 'fishing', op: '>=', value: 1, label: 'The
     * stock surveyed' }). SectorDerived.canSettle and settle() test it; while the sector is at Steady State and it fails,
     * SectorDerived.settleBlocked is its label and Derived.ending.next.need is 'requires'. Once settled it is not
     * re-tested (a lapsed survey does not unsettle). Default: none.
     */
    requires?: Cond;
  };

  /* --- M3 mechanics (see "M3 MECHANICS" above; each optional, absent = M2 behaviour) --- */
  /** M3: the seam ladder ('stock' sectors only; ignored on 'flow'). Feature 'seams'. Default: none. */
  seams?: SeamDef[];
  /** M3: the load curve. Feature 'load' (widget only; the arithmetic always acts). Default: none. */
  load?: LoadDef;
  /** M3: travel time, congestion and sprawl. Feature 'travel' (widget only; the arithmetic always acts). Default: none. */
  travel?: TravelDef;
  /**
   * M3: the one-line names of this Industry's mechanic, for the UI's widget heading and the lint ("one mechanic per
   * Industry"): e.g. { name: 'The seams', rebound: 'Supply-side', blurb: 'Cheap pumping reaches deeper coal.' }.
   * Required by the lint for every Industry from M3; Code's names its existing mechanic. Default: absent (no heading).
   */
  mechanic?: {
    name: string; rebound: string; blurb: string;
    /**
     * M4 (amend): on a feed source (Iron): until this holds, the sector's feeds are not known to the page: AppDerived
     * .feeds reads null and AppDerived.feedsKnown false, SectorDerived.feeds (the order book) reads null, and an
     * application's wantedChange leaves out the fed Industries. The feeds still act. Iron: { owns: '<the research
     * card>' } ("Of the Economy of Fuel"). Default: known.
     */
    feedsKnownWhen?: Cond;
  };

  /* --- M4 (each optional, absent = M3 behaviour) --- */
  /**
   * M4: this sector draws its resource from another stock sector's reserve (Iron's coke from Steam's coal). Requires
   * resourceKind 'stock' on both and names a sector that has no resourceStock of its own (lint). Then:
   *   - this sector's p_r is the owner's p_r (seams, depletion and resourcePriceMul OF THE OWNER; this sector's own
   *     resourcePriceMul multiplies on top), and its own `reserve`, `alpha`, `basePrice` and `seams` are ignored (its
   *     SectorState.reserve / reserveMax mirror the owner's and are not stepped);
   *   - each step the owner's reserve is drained by R_owner × (1 − circ_owner) + Σ over open, unsettled drawers of
   *     R × (1 − circ of that drawer);
   *   - exhaustion is the owner's ('exhausted' names the owner; RunSummary.causeSector = the owner);
   *   - this sector's SectorDerived.reserveFraction and secondsLeft report the owner's;
   *   - a settled drawer drains nothing (as a settled owner: SettledState's simplification); a closed drawer nothing.
   * Budget lines stay per sector (this sector's R on its own line). reserveAdd effects naming the drawer are ignored
   * (lint: name the owner). Default: absent (its own reserve).
   */
  resourceStock?: SectorId;
  /** M4: the renewable stock (required with resourceKind 'renewable'; ignored otherwise). Default: none. */
  renewable?: RenewableDef;
  /* --- M5 (optional, absent = M4 behaviour) --- */
  /**
   * M5: hidden flow (Plenty): a share of the resource applied returns to the reserve. With
   *   r = clamp(returnShare × Π returnShareMul effects on this sector, floor ?? 0, RETURN_SHARE_MAX)
   * the PRICE side uses water APPLIED: pPre = p_r / η + c (as now) and R_applied = D / η (after substitution, as R is);
   * the RESOURCE side uses water CONSUMED: R = R_applied × (1 − r). The reserve drains by R (× (1 − circularity) as
   * before), pressure with pressureSource 'resource' is fed by R, and budget lines, caps and quotas (with LeverDef.basis
   * 'consumed', the default), decades, clear skies, the sink line, the instruments, Hindsight's intensity and
   * SectorDerived.resourceUse all read R (consumed). A cap or charge with basis 'applied' reads R_applied instead (see
   * LeverDef.basis). The shadow solve freezes η AND r at their values when the baseline was recorded (etaAtBase and
   * SectorState.returnAtBase). SectorDerived.water reports both flows. Settled: frozen as R is. Default: absent (R = D / η, M4).
   * (Pressure fed by applied water is not offered: content wanting nitrogen tied to output uses pressureSource
   * 'service'.)
   */
  hiddenFlow?: { returnShare: number; floor?: number };

  applications: ApplicationDef[];
}

export interface ApplicationDef {
  id: string;              // unique across the whole game, e.g. 'steam.mills'
  name: string;            // "Cotton mills"
  blurb: string;           // one line of flavour
  /** Small pictogram the UI draws (the UI owns a set of inline SVGs keyed by this). */
  icon: string;
  /** p_i: service price at which half of saturation is adopted. Effective p_i = halfPrice × Π halfPriceMul. */
  halfPrice: number;
  /**
   * S_i: demand at full saturation for population 1.
   * Effective S_i = N × saturation × AppState.satMul (sufficiency) × Π satMul effects × spill multiplier.
   */
  saturation: number;
  /** k_i: steepness (elasticity while the use is young). D_i = S_i / (1 + (p_s / p_i)^k_i). */
  steepness: number;
  /**
   * Frontier rebound. The application becomes *available* the first time p_s ≤ visibleBelow
   * (Infinity = from the start). The player then pays `foundCost` capital to found it.
   * Demand is zero until founded. foundCost 0 = founded automatically when available.
   */
  visibleBelow: number;
  foundCost: number;
  /**
   * Steam's twist: each unit of this application's demand adds this much to BOTH reserve and reserveMax per second.
   * Balance rule: keep reserveGainPerService × η × (this app's share of sector demand) < 1 at every reachable η, or the
   * app regenerates more coal than the sector burns and the reserve can never run out.
   */
  reserveGainPerService?: number;
  /** Motion's twist: demand never falls below this fraction of the application's own peak (lock-in). 0 = none. */
  lockIn?: number;
  /* --- M3 --- */
  /**
   * M3: sprawl that fades. Per second, while this application's demand is below its peak, AppState.peakD decays:
   * peakD ← max(d, peakD × exp(−lockInDecay × dt)), d = its demand this step. Default 0 (M2: the peak never falls).
   * The sector's sprawl stock (SectorDerived.travel.sprawl) is Σ lockIn × peakD over founded apps.
   */
  lockInDecay?: number;
  /** M3: key into SectorDef.load.profiles (unknown key → defaultProfile). Ignored without `load`. Default defaultProfile. */
  profile?: string;
  /**
   * M3: the price this application's users see, as p_a = share × p_s + flat (a nil or flat price: "free at the point of
   * use", a subscription, a flat-rate tariff). Its demand is S_a / (1 + (p_a / P_a)^k_a): with share 0 it ignores p_s.
   * The service is still bought at p_s (income, R and levies are unchanged): the bill is paid elsewhere
   * (SectorDerived.free.bill = Σ (p_s − p_a) × D_a over apps with p_a < p_s). A standing priceSeen effect on the app (or
   * its sector) replaces this definition (see EffectDef 'priceSeen'). Availability (visibleBelow) still reads p_s.
   * Price-proof demand: an app with share 0 counts as a floor in the cap's squeeze limit (its demand at any p is
   * max(F_a, S_a / (1 + (flat / P_a)^k_a))). Feature 'freeAtUse' (display only). Default: absent (p_a = p_s).
   */
  priceSeen?: { share: number; flat?: number };
  /* --- M4 --- */
  /**
   * M4: inputs (the order book). While this application is founded, each target sector's capital cost per unit is
   * multiplied by
   *   f = 1 − (1 − capCostMul) × a,    a = this app's AppDerived.adoption (0–1) in the same solve
   * `sector` is a sector id, or '*' for every OTHER open sector (not this app's own). Several feeds into one sector
   * multiply. A feed acts only while both are open; a SETTLED source feeds its settled adoption
   * (SettledState.appAdoption); a settled target is not solved, so it is not fed. The factor joins c before load's
   * c_eff (c_eff multiplies whatever c results). Solve order: a feed is an edge source → target in contentIndex's
   * topological order, beside spill and drawsOn ('*' expands to every other sector); the lint refuses a cycle. The
   * shadow solve of the TARGET sees the same factor (it is not efficiency of the target, so it is not frozen out): the
   * target's rebound meter stays its own direct rebound, and the feed shows in its frontierFold, as spill does.
   * capCostMul in (0, 1] (lint). Default: none.
   *
   * M4 (finish): a feed may also widen the target's DEMAND (rails let the railways carry more; iron plate enlarges the
   * steamers): `satMul` (≥ 1, lint) multiplies the saturation of the target's application `app` (an id of the target's
   * own applications), or of every application of the target when `app` is absent, by
   *   g = 1 + (satMul − 1) × a,    a as above
   * in the same solve (several multiply). With '*' `app` must be absent. The full account hands this application's share
   * of the source's R to its targets in proportion to (1 − f_t) + (g_t − 1); the order book's rAdded and a 'full' line
   * see it as they see f. Absent satMul: as before (no field, no change).
   */
  feeds?: { sector: SectorId | '*'; capCostMul: number; /** M4 (finish) */ satMul?: number; /** M4 (finish) */ app?: string }[];
  /* --- M5 --- */
  /**
   * M5: available only while this holds, in addition to visibleBelow (calendar-dated uses: { stat: 'year', … }; the
   * exempt use of a loophole: { loophole: '<rung id>', status: 'used' }). Evaluated on the state at the start of each
   * step, as visibleBelow is. A FOUNDED application whose `when` stops holding keeps its adoption but cannot grow: its
   * effective saturation (S_i after population, satMul, effects and spill) is capped at the value it had on the last
   * step `when` held (AppState.frozenSat; it may still fall) until `when` holds again. An unfounded one becomes unavailable (AppState.available false) and is
   * not offered to anyone. Default: always.
   */
  when?: Cond;
}

/**
 * Effects. Two families:
 *   - STANDING effects are modifiers in force while their source is held: an upgrade owned this run (× its level), a
 *     know-how node (× its level), a SEATED institution (each owned level's effects once), or a decade reward earned
 *     this run (× decades earned). They are recomputed, never written into state.
 *     M2 sources of standing effects: a dividend chosen this run (× times chosen), a Commons project (× its level), the
 *     Charter in force (once), a settled sector's settle.dividend (once, while settled), and an institutionLoan (the
 *     loaned levels, once).
 *   - ONE-OFF effects ('mandateAdd', 'capitalAdd', 'slotAdd') fire once at the moment they are granted: an upgrade
 *     level bought, a know-how level bought, a decade completed, a sector's first Steady State. They are ignored on
 *     institutions (an institution is re-applied every run). 'reserveAdd', 'startCapitalMul' and 'startLever' are
 *     standing but act on the state at specific moments, as described per variant.
 *     M2 moments: a dividend chosen, a Commons level bought, a sector's first settlement in a run. They are ignored on
 *     Charters. M2 CHANGE: a know-how level's one-offs fire only the first time that level is ever owned
 *     (MetaState.knowhowPeak), so a respec and re-buy grants nothing twice.
 * Unknown effect types are ignored.
 * M3 sources of standing effects: a lever's side effects (× bite × level; LeverDef.sideEffects); a 'measure' lever's
 *   effects (× its level value); a timed modifier (once, until it ends; GameState.modifiers); the standing effects of a
 *   dispatch arm answered this run (once per answer, for the rest of the run); the History in force (once; like a
 *   Charter: start-of-run effects at build, one-offs ignored).
 * M3 ONE-OFF effects (fire once at the moment granted, wherever one-offs fire: an upgrade bought, a know-how level
 *   above its peak, a decade, a first Steady State, a dividend chosen, a Commons level, a first settlement, a dispatch
 *   arm answered): 'populationMul', 'pressureAdd', 'metaFlag', besides M1's mandateAdd, capitalAdd, slotAdd. Ignored on
 *   institutions, Charters, Histories and timed modifiers, as all one-offs are. A one-off negative capitalAdd or
 *   mandateAdd takes what there is: capital and Mandate floor at 0.
 *   'reserveAdd' in a dispatch arm or a modifier acts at the moment granted, like a purchase (stock: reserve and
 *   reserveMax += value × reserve; flow: capacity while in force).
 * M5 sources of standing effects (all only in a Ministry except Articles and playbooks, which are inert outside one by
 *   their effect types): the pledges in force (ChairState.pledges; once each), the Articles bought (meta.articles; once
 *   each), the playbooks learnt (meta.playbooks; once each), a loophole rung's effects while its status is 'used'
 *   (LoopholeDef.effects, times = the lever's effective level), and the Know-how transfer (an etaMul on every chair
 *   sector: RivalDef.knowhowTransfer). M5 ONE-OFF: 'confidenceAdd' (wherever one-offs fire; letters in practice).
 * M5: a lever's effective level (ChairState: carve-outs and litigation; LeverView.effectiveLevel) replaces its level
 *   wherever a level multiplies an effect (measure effects, side effects' times, rung effects).
 */
export type EffectDef =
  | { type: 'etaMul'; sector: SectorId; value: number }          // efficiency ×value
  | { type: 'capCostMul'; sector: SectorId; value: number }      // c ×value
  | { type: 'marginAdd'; sector: SectorId; value: number }       // m += value (negative = a royalty or premium; m floors at 0)
  /** 'stock': reserve and reserveMax += value × SectorDef.reserve, at run start (know-how, institution) or at
   *  purchase (upgrade); 'flow': capacity = SectorDef.reserve × (1 + Σ value), recomputed. */
  | { type: 'reserveAdd'; sector: SectorId; value: number }
  | { type: 'absorptionAdd'; sector: SectorId; value: number }   // absorption += value
  | { type: 'reveal' }                                           // sets flags.revealed (The Coal Question)
  | { type: 'startCapitalMul'; value: number }                   // know-how / institutions: run starts with startCapital ×value
  | { type: 'mandateRateMul'; value: number }                    // mandateRate ×value
  /** Institution: the lever starts each run at this level, free, and its levels up to `level` cost no Mandate and no
   *  upkeep (net upkeep = upkeep(current level) − upkeep(min(level, current level))). */
  | { type: 'startLever'; lever: string; level: number }
  | { type: 'costMul'; value: number }                           // all upgrade capital costs ×value
  /* --- M1 --- */
  | { type: 'satMul'; sector: SectorId; app?: string; value: number }       // saturation ×value (one app, or every app of the sector)
  | { type: 'halfPriceMul'; sector: SectorId; app?: string; value: number } // p_i ×value (> 1: adopted at higher prices = more demand)
  | { type: 'popGrowthMul'; value: number }                      // popGrowth ×value
  | { type: 'wellbeingAdd'; value: number }                      // flat wellbeing points added to W (before the ≥ 0 clamp)
  | { type: 'unlock'; id: string }                               // makes the `locked` upgrade or lever with this id available
  | { type: 'slotAdd'; value: number }                           // ONE-OFF: meta.slots += value
  | { type: 'mandateAdd'; value: number }                        // ONE-OFF: mandate += value
  | { type: 'capitalAdd'; value: number }                        // ONE-OFF: capital += value × current income per second
  /* --- M2 --- */
  /** Start-of-run: the application is available and founded, free, when the run is built (if its sector is open then)
   *  or when its sector opens later in the run. Its foundCost is not charged. */
  | { type: 'startFounded'; app: string }
  /** Acts as if institution `id` were SEATED at `level` (its levels 1…level), without using a seat or being owned.
   *  If the player seats it at a lower level, the higher of the two applies (never both). Counts as seated for
   *  LeverDef.requires; does not count for Cond `owns`. Meant for Charters ("a different starting Institution"). */
  | { type: 'institutionLoan'; id: string; level: number }
  /** Standing: the offline cap (Derived.offlineCapSeconds) += seconds. */
  | { type: 'offlineCapAdd'; seconds: number }
  /** Standing: makes a standing order available (see OrdersState). */
  | { type: 'orderUnlock'; order: OrderId }
  /** Standing: every Commons project's wellbeing ×value (multiplicative across effects). */
  | { type: 'commonsYieldMul'; value: number }
  /* --- M3 (standing unless marked ONE-OFF) --- */
  /** Resource price p_r × value (before the permit), multiplicative across effects: a strike, a shock, a dumped price. */
  | { type: 'resourcePriceMul'; sector: SectorId; value: number }
  /** pressureIntensity × value (multiplicative): a tall chimney, a wet summer. */
  | { type: 'intensityMul'; sector: SectorId; value: number }
  /** Player income from the sector (or every sector if absent) × value: m_eff = m × value (multiplicative; after
   *  marginAdd and its floor at 0). "Raise the rents." */
  | { type: 'incomeMul'; sector?: SectorId; value: number }
  /** Capital or found cost × value of one thing: `id` an upgrade, an application (foundCost), a Commons project
   *  (capital cost), a seam; or a sector id (every upgrade, founding and seam of that sector). Multiplies with costMul. */
  | { type: 'costMulOf'; id: string; value: number }
  /** Cannot be bought, founded, sunk, built or raised while in force: `id` (an upgrade, application, seam, Commons
   *  project or lever), or every lever of `leverKind` (in `sector` if given). Lowering a lever is always allowed; levels
   *  already held stay. Forbidden things stay visible with a reason (UpgradeView.forbidden, LeverView.forbidden). The
   *  Market and the Civil Service skip them. */
  | { type: 'forbid'; id?: string; leverKind?: LeverKind; sector?: SectorId }
  /** Travel (TravelDef): speed × speed, roads × roads (each default 1; multiplicative across effects). */
  | { type: 'travelMul'; sector: SectorId; speed?: number; roads?: number }
  /** Sets the seen price of one application (or every application of the sector) to share × p_s + flat, replacing
   *  ApplicationDef.priceSeen. Several in force: the one with the lowest share applies, then the lowest flat. */
  | { type: 'priceSeen'; sector: SectorId; app?: string; share: number; flat?: number }
  /** ONE-OFF: population × value (≥ 0.01 after; an epidemic, an influx). */
  | { type: 'populationMul'; value: number }
  /** ONE-OFF: the sector's pressure += value × collapseAt (negative lowers it; floors at 0). A crisis threshold crossed
   *  this way fires on the next step, as any crossing does. Ignored on a settled sector. */
  | { type: 'pressureAdd'; sector: SectorId; value: number }
  /** ONE-OFF: meta.flags[flag] = true, for good (read by Cond { flag }). 'proprietor' is the Proprietor's Day: the
   *  moment it is first set, an unpublished household return on file is published (see ModelApi.fileReturn). */
  | { type: 'metaFlag'; flag: string }
  /* --- M3 (finish): three kinds the letter-writer asked for (standing; in a dispatch arm, a modifier or anywhere) --- */
  /** A lever's Mandate cost to raise × cost, and its upkeep × upkeep (each default 1; multiplicative across effects),
   *  for the lever `lever`, or every lever of `leverKind` (in `sector` if given), or every lever of `sector`; with none
   *  of the three, every lever. Applies to LeverView.nextCost and upkeep, setLever, the Civil Service, the lapse rule and
   *  Derived.mandatePerSec alike; an Institution's free levels stay free. "The House makes the duty cheaper to pass." */
  | { type: 'leverCostMul'; lever?: string; leverKind?: LeverKind; sector?: SectorId; cost?: number; upkeep?: number }
  /** The standing order does not act while in force (no order ticks for it; its settings are kept): OrdersView's
   *  `available` reads false for it (the Market's marketWhy 'unavailable', as when a History suspends it). For a timed
   *  modifier: "a week without the Market". */
  | { type: 'suspendOrder'; order: OrderId }
  /** A cap's leak in the sector × value (multiplicative; the leak share stays within 0–1): above 1 the barrels arrive
   *  by other routes sooner, below 1 the customs men are keener. */
  | { type: 'leakMul'; sector: SectorId; value: number }
  /** The sector's spill (SectorDef.spill: the demand its savings add to the sector it spills into) × value
   *  (multiplicative; `sector` is the source). */
  | { type: 'spillMul'; sector: SectorId; value: number }
  /** M3 (finish): standing: GlobalParams.settleMax + Σ value Industries may be settled at once (an Institution's). */
  | { type: 'settleSlotAdd'; value: number }
  /* --- M4 (standing) --- */
  /** M4: the sector is surveyed while in force (SectorDerived.stock.surveyed): the true stock, the true depletion and
   *  the sink line are shown, 'quota' levers are visible, and settle.requires may test it (stat 'surveyed'). Sources: a
   *  seated Institution, a measure lever's effects (while held), a timed modifier (a survey letter; the Board's first
   *  survey, RenewableDef.firstSurvey), a Charter's institutionLoan. Several in force = one. Meaningful on 'renewable'
   *  sectors only (ignored elsewhere). */
  | { type: 'survey'; sector: SectorId }
  /** M4: the sector's foreign share (ForeignDef) × value (multiplicative across effects; the fishery limits). */
  | { type: 'foreignMul'; sector: SectorId; value: number }
  /**
   * M4 (finish): ONE-OFF (dispatch arms and wager branches only; lint): RunStats.letterShare += value. At a Reckoning the
   * seven terms' sum is multiplied by max(0, 1 + letterShare) (HindsightTerms.letters is the difference): a letter's
   * stake in what Hindsight is made of, the same share of a short run as of a long one.
   */
  | { type: 'hindsightShare'; value: number }
  /* --- M5 (standing unless marked ONE-OFF). Effects that make no sense outside a Ministry are inert there. --- */
  /** M5: Plenty's return share r × value on the sector (SectorDef.hiddenFlow; multiplicative across effects; an
   *  irrigation card's value < 1). Ignored on a sector without hiddenFlow. */
  | { type: 'returnShareMul'; sector: SectorId; value: number }
  /** M5: Inspectors + value (ChairState.inspectors; additive; the total floors at 0). */
  | { type: 'inspectorAdd'; value: number }
  /** M5: an amendment's drafting years × value (multiplicative; amend()). */
  | { type: 'amendYearsMul'; value: number }
  /** M5: pledges offered at an election + value (additive; `keep` unchanged; ChairDef.elections.offer). */
  | { type: 'pledgeOfferAdd'; value: number }
  /** M5: the rival's litigation delay (ResponseDef.litigate.delayYears) × value (multiplicative). */
  | { type: 'litigateYearsMul'; value: number }
  /** M5: ChairDef.inspection.fineMul × value (multiplicative): the fine at inspection and the expected fine the
   *  concealment rule weighs. */
  | { type: 'fineMul'; value: number }
  /** M5: every lever's LeverDef.popularity.years × value (multiplicative): support arrives sooner. */
  | { type: 'popularityYearsMul'; value: number }
  /** M5: compensate()'s cost × value (multiplicative). */
  | { type: 'compensationMul'; value: number }
  /** M5: the rival's quiet period + value model years (additive; negative from a playbook; the total floors at 0). */
  | { type: 'quietYearsAdd'; value: number }
  /** M5: every Parliament after the first lasts termYears + value model years (additive; floors at 1). */
  | { type: 'termYearsAdd'; value: number }
  /** M5: no lever is repealed in Opposition while in force (the Ratchet Clause). */
  | { type: 'ratchet' }
  /** M5: the rival's concealment on the sector is held at 0 while in force (an Independent Statistics Board). */
  | { type: 'certify'; sector: SectorId }
  /** M5: the cost to the rival of `response` × value (multiplicative across effects; playbooks: lobbying cheaper). */
  | { type: 'rivalCostMul'; response: ResponseKind; value: number }
  /** M5: ONE-OFF: Confidence += value at once (letters; clamped to [0, CONFIDENCE_MAX]; inert outside office). */
  | { type: 'confidenceAdd'; value: number };

export interface UpgradeDef {
  id: string;              // 'steam.condenser'
  sector: SectorId;
  name: string;            // "Separate condenser"
  blurb: string;           // "Watt, 1769. Stop cooling the cylinder."
  /** 'efficiency' cards show the promise line; 'efficiency' and 'capital' cards show the projection lines. */
  kind: 'efficiency' | 'capital' | 'prospect' | 'research';
  /** Capital cost of the first purchase. */
  cost: number;
  /** For repeatable upgrades: cost of level n = cost × costGrowth^n (n = levels already owned). */
  repeatable?: boolean;
  costGrowth?: number;
  maxLevel?: number;
  /** Ids of upgrades that must be owned (level ≥ 1) first. Unknown ids are treated as unmet. */
  requires?: string[];
  /**
   * M1: forks. Ids of upgrades this one excludes for the rest of the run. Exclusion is symmetric: an upgrade is
   * excluded if any owned upgrade lists it, or it lists any owned upgrade. Excluded cards stay visible (so the fork
   * reads as a choice) but cannot be bought. Content should list both sides. Default: none.
   */
  excludes?: string[];
  /** M1: hidden and unbuyable unless a standing `unlock` effect names this id. Default false. */
  locked?: boolean;
  /**
   * M2: the visual machine stage this card brings its sector to, an integer ≥ 1 (the scene draws 0–3 today: e.g.
   * Steam Newcomen 0 → Watt 1 → Cornish 2 → turbine hall 3; it clamps larger values). The sector's stage is the
   * largest `stage` among its owned upgrades, 0 if none (SectorDerived.stage). Normally set on efficiency cards only.
   * Default: none (the card does not move the machines).
   */
  stage?: number;
  /* --- M3 --- */
  /** M3: the display name of the machine at this card's `stage` ("Watt engine"); carried on 'stageReached' events
   *  (GameEvent.label). Default: the card's name. */
  machine?: string;
  /** M3: visible only while this holds, in addition to `requires` (both must hold). Used by The Proprietor's Day and
   *  by M4's revivals. Once owned, a card stays owned whatever `when` says later. Default: always. */
  when?: Cond;
  effects: EffectDef[];
}

export type LeverKind =
  /** Tax that holds the service price up as η rises. With strength s (0–0.999) and p the price before duty
   *  (pre-levy price + permit part):  dutyPart = s × max(0, p_ref − p), p_ref = p when the lever first went above 0
   *  (LeverState.ref). The strongest duty lever of a sector applies. Revenue = dutyPart × D (never player income). */
  | 'duty'
  /** M1 CHANGE: hard ceiling capR = value × budgetR(t) — a fraction of the sector's declining BUDGET LINE, not of
   *  "R when enacted". The tightest cap of a sector applies. If the sector has no budget when a cap is active, one is
   *  drawn at the current R on the first step with demand once the sector has been open steady.standingDrawYears
   *  (M1 balance; default 0); until then the cap has no line and does nothing. A permit price is added to p_r until R meets the cap.
   *  Leak: when permit > value2 × p_r (leakAbove), the effective cap rises by up to 25%:
   *    leak = 0.25 × clamp(permit / (leakAbove × p_r) − 1, 0, 1), solved self-consistently; value2 absent = no leak.
   *  Squeeze limit: a cap never squeezes out more than 95% of the demand above the floors (lock-in floors and drawsOn
   *  demand, which no price removes): effective target = max(capR × (1 + leak), R_floor + 0.05 × (R_free − R_floor)),
   *  R_free = R with no cap. Below that the cap is simply not met. Permit revenue = permit × R (never player income). */
  | 'cap'
  /** Saturation of the sector's applications drifts toward `value` × S_i at rate value2 per second (default 0.01):
   *  satMul −= (satMul − target) × (1 − exp(−rate × dt)). Relaxed, it recovers toward 1 at 0.01 per second. */
  | 'sufficiency'
  /** A share σ = min(value, value2 / D) of the service comes from a renewable flow: uses no resource, makes no
   *  pressure, costs 1.5 × c per unit (blended into the pre-levy price). value2 = flowCap in service units per second
   *  (absent = unlimited). Several substitution levers in one sector: shares add (≤ 1), flowCaps add. */
  | 'substitution'
  /** A share of resource used returns to the reserve ('stock' only): drain = R × (1 − share). Shares add, ≤ 0.95. */
  | 'circularity'
  /** Cuts this sector's indirect spill by a share. Shares add, ≤ 1. */
  | 'greenSpending'
  /** Code: spends `value` share of effective capacity (≤ 0.9) to shrink P at value2 (default 1) per unit capacity per second. */
  | 'deletion'
  /** Code: shipped service limited to reviewed service; removes `value` of the defect penalty and cuts D accordingly. */
  | 'reviewGate'
  /** Code: pressureIntensity × (1 − share). Shares add, ≤ 0.95. */
  | 'sharedLibs'
  /** M3: a policy acting through effects: LeverDef.effects are standing effects applied with times = the current level's
   *  `value` (multiplicative effects to the power value, additive ones × value). Range 0–∞ (repeat bounded by maxSteps).
   *  A fuel-economy standard (etaMul), a road programme (travelMul roads), a scrappage scheme. value2 unused. */
  | 'measure'
  /** M4: a cap on the TRUE sustainable catch: capR = value × sinkR (the depletion sector's sink line; see SectorDef
   *  .pressureSource) instead of value × budgetR. Visible only while the sector is surveyed (LeverView.visible needs
   *  SectorDerived.stock.surveyed, besides the usual gates); while unsurveyed a HELD quota acts on the last surveyed
   *  sinkR (SectorState.lastSurvey.sinkR, the Board's last figure; nothing if there is none). Otherwise exactly a 'cap'
   *  (permit price, leak via value2, squeeze limit, levy, recycle). value 0 = a moratorium (D held at the price-proof
   *  floors only). Range 0–1. Requires a budget line as a cap does (drawn at today's R if absent). The tightest of the
   *  sector's caps and quotas applies. */
  | 'quota'
  /** M5: the Treasury pays `value` (0–SUBSIDY_MAX) of the capital cost of the lever's LeverDef.targets (upgrade or
   *  application ids of its sector) when the RIVAL buys or founds one: his payback is computed at (1 − value) × cost; the
   *  Treasury (GameState.capital) is charged value × cost at the purchase, if it can pay in full (else the rival pays
   *  the whole and nothing is charged). Several subsidy levers naming one target: the largest value applies. No effect
   *  outside a Ministry (the player's own purchases are never subsidised). Revenue: none (it is spending). Range
   *  0–SUBSIDY_MAX. value2 unused. */
  | 'subsidy'
  /** M5: a price on the service, fixed when enacted (unlike a duty, which tops the price back up as η rises). On enact
   *  from level 0, LeverState.ref = p_s (the service price at that moment) or, with LeverDef.basis, the resource price
   *  p_r per unit of that water. chargePart (per unit of service) = value × ref, or with `basis` value × ref × R_basis /
   *  D (R_basis = R_applied or R consumed); it is added to the service price after the duty (p_s = pPre + permitPart +
   *  dutyPart + chargePart; the duty's p_ref compares the price BEFORE the charge). Levy revenue = chargePart × D (×
   *  (1 − concealment) in a Ministry: the rival pays on what he reports); recycled as a duty's (LeverDef.recycle).
   *  Several charges in a sector add. Works in and out of a Ministry (content gates it with requires ['charge']). Range
   *  0–1 (repeat allowed). value2 unused. */
  | 'charge';

/**
 * M1: where a levy's revenue goes (meaningful for 'duty' and 'cap' only).
 *   'treasury': GlobalParams.levy.mandateShare of it becomes Mandate (v1 behaviour); the rest vanishes.
 *   'dividend': returned to households per head: counted as service in wellbeing (see SectorDef.wellbeingWeight); no
 *               Mandate. Wellbeing up means population up: an economy-wide rebound the card should name.
 *   'commons':  M2: GlobalParams.commons.fundShare of it accrues to GameState.commons.fund per second, money that only
 *               Commons projects can spend (buyCommons draws on the fund before capital). No Mandate, no wellbeing
 *               until spent. Selectable only once the Commons are open (Derived.commons.available); its rebound is the
 *               projects' own (intensity, time, population), which the catch line should name.
 */
export type LeverRecycle = 'treasury' | 'dividend' | 'commons';

export interface LeverDef {
  id: string;              // 'steam.duty'
  sector: SectorId;
  kind: LeverKind;
  name: string;            // "Fuel duty escalator"
  blurb: string;
  /** What the catch is, in the UI's words. Required (content lint). */
  catch: string;
  /**
   * QA FIX (the unfolding): clauses of the catch that name a system the player may not have met yet, keyed by the
   * feature that brings it (the duty's "Paid out as a dividend instead…" waits for 'moreLevers', which brings the
   * recycling choice). The UI appends each, after a space and in FEATURE_IDS order, while Derived.features[id] is on.
   * Absent = none.
   */
  catchAfter?: Partial<Record<FeatureId, string>>;
  /** One entry per authored level (level 1 = index 0). Level 0 = off. */
  levels: LeverLevelDef[];
  /**
   * Visibility gates, all must hold. Each entry is one of:
   *   'revealed'        → flags.revealed;
   *   an upgrade id     → owned (level ≥ 1) this run;
   *   an institution id → SEATED this run (M1 CHANGE: was "owned"; M2: or loaned by an institutionLoan in force);
   *   a FeatureId       → that feature unlocked (MetaState.features; always met if the feature is not in content);
   * any other string is treated as met (the content lint flags it).
   * M4: a 'quota' lever is also hidden while its sector is not surveyed (see LeverKind 'quota'); a capstoned sector's
   * levers are hidden as a settled sector's are.
   * Independently of `requires`, every lever is hidden until flags.revealed and the 'levers' feature, unless a seated
   * institution starts it (startLever), and hidden while `locked` and not unlocked. M2: every lever of a SETTLED sector is hidden and
   * unraisable (settle sets them to 0; see ModelApi.settle).
   */
  requires?: string[];
  /** M1: hidden and unusable unless a standing `unlock` effect names this id. Default false. */
  locked?: boolean;
  /**
   * M1: "Tighten" beyond the authored levels. With L = levels.length and last = levels[L − 1], level L + k (k ≥ 1) is:
   *   value = last.value + k × valueStep;  value2 = last.value2 (+ k × value2Step if given);
   *   mandateCost = last.mandateCost × costGrowth^k;  mandateUpkeep = last.mandateUpkeep × upkeepGrowth^k;
   *   label = `label` with {pct} = round(value × 100), {value} = value to 2 dp, {n} = level; default `${last.label} +k`.
   * A repeat level exists only while its value stays inside the kind's range (M3: measure 0–∞; duty 0–0.999, cap 0.05–∞, sufficiency
   * 0.05–1, substitution/greenSpending/reviewGate 0–1, circularity/sharedLibs 0–0.95, deletion 0–0.9) and k ≤ maxSteps.
   * For a cap, valueStep is negative (each Tighten lowers the cap as a fraction of the budget). Default: no repeat.
   * M4: quota 0–1 (valueStep negative, as a cap's).
   */
  repeat?: {
    valueStep: number;
    value2Step?: number;
    costGrowth: number;
    upkeepGrowth: number;
    maxSteps?: number;
    label?: string;
  };
  /** M1: recycle options offered for this lever's revenue ('duty'/'cap' only); the first is the default.
   *  Default: ['treasury']. M2: the first must not be 'commons' (it is not selectable before the Commons open). */
  recycle?: LeverRecycle[];
  /** M2: per-option override of Content.recycleText[option].blurb for this lever (the dividend's rebound named for
   *  this levy, say). Default: none. */
  recycleBlurb?: Partial<Record<LeverRecycle, string>>;
  /* --- M3 --- */
  /** M3: the standing effects of a 'measure' lever (see LeverKind 'measure'). Ignored on other kinds. Default []. */
  effects?: EffectDef[];
  /**
   * M4 (amend): the lever is hidden and cannot be raised until this holds (Fishing's fishery limits wait for the foreign
   * share). Once it has held in a run (LeverState.seen) the lever stays shown for the rest of the run, so it does not
   * flicker; a lever already above level 0 counts as seen. LeverView.waiting carries the condition's label while it
   * hides the lever. Default: always (no condition).
   */
  when?: Cond;
  /**
   * M3: a lever that bites back: its own success breeds its undoing, unless paired with the right companion.
   *   bite (LeverState.bite, 0–1) is a ramp in model years. Each step, with dy = dt × YEARS_PER_SECOND:
   *     active = level ≥ 1 AND NOT `unless` (evaluated on the state at the start of the step);
   *     active:   bite ← bite + (1 − bite) × (1 − exp(−dy / rampYears));
   *     inactive: bite ← bite × exp(−dy / (decayYears ?? rampYears)).
   *   `effects` are standing effects with times = bite × level (the integer level; repeat levels count). So the side
   *   effect grows with the lever's level and with time, and fades when paired or lowered as slowly as it grew (an SUV
   *   fleet is not scrapped overnight).
   *   The first time in a run that bite reaches 0.5, LeverState.bitten = true and a 'biteBack' headline and event fire
   *   (feature 'sideEffects' gates the headline and the UI line, not the bite).
   *   `blurb`: the "bites back" line, one sentence ("Heavier cars fill the forecourt"); the `catch` line already names
   *   the risk up front (lint). `unlessLabel`: the pairing in words ("unless a fuel duty is in force").
   * Examples: a fuel-economy standard (etaMul) whose side effect is satMul on the heavy car, unless { owns: 'motion.duty'
   * }; renewables without a cap (substitution) whose side effect is satMul on the sector (additions, not displacement),
   * unless { owns: 'light.cap' }; an announced phase-out whose side effect is resourcePriceMul < 1 (the rush to extract).
   * Settled sectors' levers are at 0, so their bite decays. A Reckoning resets bite (a fresh run). Default: none.
   */
  sideEffects?: {
    effects: EffectDef[];
    rampYears: number;
    decayYears?: number;
    unless?: Cond;
    blurb: string;
    unlessLabel?: string;
  };
  /* --- M5 --- */
  /**
   * M5: the lever's term in Confidence's target C* (ChairDef, §2.1 of the notes) per level held, moving from `start` to
   * `after` over `years` model years of being held at ≥ 1 (since LeverState.since):
   *   term = effectiveLevel × (start + (after − start) × min(1, held / (years × Π popularityYearsMul)))
   *   held = (time − LeverState.since) × YEARS_PER_SECOND (0 while the level is 0).
   * The congestion charge: start −3, after +1, years 10 (Stockholm). LeverView.popularity reports the term now. Inert
   * outside a Ministry. Default: none (the lever's effect on Confidence is only through prices and jobs).
   */
  popularity?: { start: number; after: number; years: number };
  /**
   * M5: the loophole ladder of this lever: LoopholeDef ids, in rung order (each LoopholeDef.lever must be this id). Only
   * in a Ministry, only while feature 'loopholes' is on. Rules: LoopholeDef. Default: none (no ladder).
   */
  ladder?: string[];
  /** M5: 'subsidy' only: the upgrade or application ids (of the lever's sector) it pays towards. Ignored on other kinds. */
  targets?: string[];
  /**
   * M5: on a sector with SectorDef.hiddenFlow, which water a 'cap', 'quota' or 'charge' is written on: 'applied' (metered
   * at the pump: R_applied) or 'consumed' (R; the default). A cap (or quota) on 'applied' follows the budget line's
   * path but is written in applied water: on enact from level 0, LeverState.ref = R_applied at that moment, and
   *   capR_applied = value × ref × budgetR(t) / BudgetState.r0
   * (the line's decline, applied to the pumped figure); the permit is solved so that R_applied ≤ capR_applied (squeeze
   * limit and leak as a cap's, in applied water). So a licence holds applied water while consumed water can rise as the
   * return share falls (the lesson). A charge on 'applied' charges per unit of R_applied (LeverKind 'charge'). Budget
   * lines, decades and the instruments still read R (consumed). Ignored on a sector without hiddenFlow. Default
   * 'consumed'.
   */
  basis?: 'applied' | 'consumed';
}

export interface LeverLevelDef {
  /** One-off Mandate to reach this level from the one below. */
  mandateCost: number;
  /** Mandate per second while held at this level. If Mandate hits 0 the costliest-upkeep lever drops one level,
   *  repeatedly, until upkeep is covered. */
  mandateUpkeep: number;
  /** Meaning depends on kind: duty strength, cap fraction of the budget line, sufficiency target, substitution share,
   *  circularity share, greenSpending share, deletion share of capacity, reviewGate share, sharedLibs share. */
  value: number;
  /** Secondary knob: sufficiency rate, substitution flowCap, cap leakAbove, deletion rate. */
  value2?: number;
  /** Short label for the level button: "Hold price at 60%". */
  label: string;
}

/**
 * Permanent, bought with Hindsight, the tempting kind: makes runs faster and shorter.
 * M1: nodes form trees with tiers and exclusive forks. Efficiency nodes should carry a visible rebound side-effect
 * (satMul or halfPriceMul > 1) so "runs start faster and hit the wall sooner" is printed on the node.
 */
export interface KnowhowDef {
  id: string;
  name: string;
  blurb: string;
  /** Hindsight cost of level n = cost × costGrowth^n (n = levels already owned). */
  cost: number;
  costGrowth: number;
  maxLevel: number;
  /** Applied once per level owned (standing), or once per level bought (one-off effects). */
  effects: EffectDef[];
  /** M1: tree this node belongs to (UI groups by it). Default 'general'. */
  tree?: string;
  /** M1: row in the tree. A node of tier t ≥ 2 is visible and buyable only once some node of tier t − 1 in the same
   *  tree has level ≥ 1. Default 1. */
  tier?: number;
  /** M1: exclusive fork group. Once any node of a branch has level ≥ 1, every other node with the same branch id is
   *  excluded. M2 CHANGE: until a respec (ModelApi.respecKnowhow) clears the branch. Default: none. */
  branch?: string;
  /** M5: visible and buyable only while this holds, evaluated on the state between runs (Statecraft: { feature:
   *  'statecraft' }). Levels already owned stay owned and act. Default: always. */
  when?: Cond;
}

/** M1: a further level of an institution. Its effects are added to those of the levels below. */
export interface InstitutionLevelDef {
  /** Hindsight to buy this level. */
  cost: number;
  effects: EffectDef[];
  /** One line saying what this level adds. */
  label?: string;
  /** M4 (polish): this level is bought only while this holds (as InstitutionDef.needs). Absent = no condition. */
  needs?: Cond;
}

/**
 * Permanent, bought with Hindsight, the slow kind: counter-levers in place from the start.
 * M1 CHANGE: institutions have levels and act only while SEATED in the loadout (see ModelApi.setLoadout).
 */
export interface InstitutionDef {
  id: string;
  name: string;
  blurb: string;
  /** Hindsight cost of level 1 (unlocking it). */
  cost: number;
  requires?: string[];     // other institution ids (level ≥ 1)
  /**
   * M4 (amend): the Institution is offered (InstitutionView.visible; buyInstitution accepts it) only while this holds,
   * evaluated on the state between runs (meta-scoped leaves are the useful ones: { owns: '<sector>' } is "opened in any
   * run"). One already owned is always shown and can always be seated. The Fishery Board: { owns: 'fishing' }.
   * Default: always.
   */
  when?: Cond;
  /**
   * M4 (polish): level 1 is bought (buyInstitution accepts it, InstitutionView.canBuy) only while this holds, evaluated
   * on the state between runs; unlike `when` the Institution is shown meanwhile, with InstitutionView.needs naming the
   * condition (the evidence a sitting waits on: meta-scoped leaves, e.g. an achievement). Absent = no condition.
   */
  needs?: Cond;
  /** Effects of level 1. */
  effects: EffectDef[];
  /** M1: levels 2, 3… (nextLevels[0] is level 2). Default: none (a one-level institution). */
  nextLevels?: InstitutionLevelDef[];
  /** M1: loadout seats it occupies while seated. Default 1. */
  slots?: number;
}

export interface AchievementDef {
  id: 'jevonsWasRight' | 'degrowthByAccident' | 'steadyState' | 'firstReckoning' | 'backfire' | string;
  name: string;
  blurb: string;
  hidden?: boolean;
  /** QA FIX (the unfolding): until this feature is on, the UI lists the achievement as hidden (it names a system the
   *  player has not met). Absent = never. Display only. */
  feature?: FeatureId;
  /**
   * M1 (brought forward from M3): granted the first time this holds, checked at least once per real second of play.
   * Without `when`, only the five built-in ids above are granted, by the core's own rules (see ModelApi.tick);
   * any other id without `when` is never granted.
   */
  when?: Cond;
  /** M4 (polish): printed in the broadsheet (key 'achievement') when the core grants it by `when`, for an achievement
   *  that is a step the player works towards (the spring survey). At most 70 characters. Absent = granted silently. */
  headline?: string;
}

export type HeadlineKey =
  | 'appFounded' | 'appAvailable'
  | 'sectorOpened'    // M1 CHANGE: was 'eraOpened'
  | 'crisis' | 'collapse' | 'exhausted'
  | 'backfire'        // first time a sector's (direct) rebound passes 100% this run
  | 'reveal' | 'leverEnacted' | 'leverLapsed'
  | 'steadySector'    // M1 CHANGE: was 'steadyEra'. A sector reaches Steady State (once per sector per run)
  | 'steadyAll' | 'reckoning' | 'efficiency'
  /* --- M1 --- */
  | 'ageBegins'       // the first sector of an age opens (sectorOrder[0]'s age at run start does not fire it)
  | 'budgetDrawn'     // a budget line is drawn or redrawn for a sector
  | 'decade'          // a sector completes a decade within budget ({n} = decade number this run)
  | 'budgetBroken'    // a streak holding at least one completed decade ends
  /* --- M2 --- */
  | 'clearSkies'      // a sector becomes clear for the first time on its current line (BudgetState.clearAt is set)
  | 'settled'         // a sector is settled
  | 'unsettled'       // a settlement ends (by the player, or because its defence could not be paid)
  | 'commonsBuilt'    // a Commons level is bought ({name} = the project; by the player or Treasury rules)
  | 'charter'         // a Charter is chosen for the run ({name} = the Charter; {sector} its sector, if any)
  /* --- the unfolding --- */
  | 'featureUnlocked' // a feature arrives; the text is its FeatureDef.intro, never drawn from Content.headlines
  /* --- M3 (Content.headlines must list each key; an empty array falls back to the core's one-line default) --- */
  | 'seamSunk'        // a seam is sunk ({name} = the seam)
  | 'biteBack'        // a lever's side effect first reaches half strength this run ({name} = the lever)
  | 'dispatch'        // a dispatch arrives: the text is DispatchDef.headline, never a variant (the key marks the item)
  | 'answered'        // a dispatch is answered: the arm's `reply`, if it has one (no item otherwise)
  | 'ambient'         // an ambient headline: the text comes from the AmbientDef (the key marks the item)
  | 'history'         // a History is cleared ({name} = the History)
  | 'return'          // the household return is published (text from Content.proprietor)
  | 'returnWithdrawn' // the household return is withdrawn ("…discontinued for want of funding")
  | 'ending'          // the first ending, beside 'steadyAll' ({year}; printed once ever, in the run that reached it)
  /* --- M4 (Content.headlines must list each key; an empty array falls back to the core's one-line default) --- */
  | 'threshold'       // a renewable stock first falls below its threshold this run (event 'thresholdCrossed')
  | 'scarHealed'      // a scar heals (event 'scarHealed')
  | 'surveyed'        // a sector is first surveyed this run (event 'surveyed'); the Board's first survey prints
                      //   Content.surveyReveal's variant headline instead, and its followUp on the next step
  | 'arrears'         // a capstoned Industry goes into arrears (event 'arrears')
  | 'foreignFleets'   // the foreign share first passes ForeignDef.announceAt this run (no event)
  /* --- M4 (polish) --- */
  | 'achievement'     // an achievement with a `headline` is granted: the text is AchievementDef.headline, never a variant
  | 'actEnding'       // an Act's ending is reached ({name} = ActDef.title, {year}); with Content.acts it replaces
                      //   M3's 'ending' headline (printed once ever per act, after 'steadyAll')
  /* --- M5 (Content.headlines must list each key; an empty array falls back to the core's one-line default). {name} is
   *     the lever, pledge, rung, Article or playbook named; {n} the number stated. Order within a step: EventKind. --- */
  | 'acquisition'     // takeOffice: the Gazette's "PRYCE CONSOLIDATED ACQUIRES THE WORKS" (text: OfficeDef.text, never a
                      //   variant; the key marks the item; printed before 'officeTaken'); headline only
  | 'officeTaken'     // takeOffice: "New Ministry formed; the first election is due in {year}" ({year} = polling year)
  | 'electionCalled'  // the pledge offer is drawn ({year} = the polling year)
  | 'electionWon'     // polling day, won ({n} = Confidence, integer)
  | 'electionLost'    // polling day, lost ({n} = Confidence, integer)
  | 'leverRepealed'   // the incoming government repeals a lever level ({name} = the lever)
  | 'ministryDefeated' // the second loss in a row: the Reckoning 'defeated' falls due
  | 'concealmentFound' // an inspection finds concealment ({sector}; {n} = the share found, integer per cent)
  | 'inspectedClean'  // an inspection finds nothing ({sector}); headline only
  | 'rivalAnswered'   // the rival's answer to a lever changes kind ({name} = the lever; the variant may be keyed by
                      //   sectorHeadlines; no headline for 'comply' after no previous answer: the first comply is silent)
  | 'loopholeOpened'  // a rung opens ({name} = the rung)
  | 'loopholeUsed'    // the rival evades through a rung ({name} = the rung)
  | 'loopholeClosed'  // an amendment closes a rung ({name} = the rung)
  | 'litigated'       // the rival takes a lever to court ({name} = the lever)
  | 'carveOut'        // lobbying wins a carve-out ({name} = the lever)
  | 'compensated'     // compensation is paid ({sector})
  | 'treaty'          // the Treaty is signed (between runs, printed into the rebuilt run's news)
  | 'playbookLearnt'  // the rival learns a playbook ({name})
  | 'articleBought';  // an Article is bought ({name})

/* ------------------------------------------------------------------ */
/* M3 CONTENT: the cast, dispatches, ambient news, Histories, Archive  */
/* ------------------------------------------------------------------ */

/*
 * Authored text in this block takes the headline placeholders with the same case rules (Content.headlines): {sector},
 * {resource}, {service}, {age}, {year}, {app} (when the item names one), plus {cast} (the writer's name, a proper noun,
 * substituted as written), and the per-kind numbers listed at each type. A placeholder with no value is left as typed
 * (the lint catches it). The core substitutes; the UI prints what Derived gives it.
 */

/** M3: a recurring member of the cast (Content.cast). */
export interface CastDef {
  /** 'whitlow', 'fenwick', 'pryce', 'ashworth', 'correspondent', 'minister'. */
  id: string;
  /** As printed: "Mr Whitlow". Later generations are separate CastDefs ('missWhitlow'). */
  name: string;
  /** One line under the name: "Economist; a pupil of Mr Jevons". */
  role: string;
  /** For writers, never shown: the voice, the tics, what they always want. */
  voice?: string;
  /** Scene key of the figure the picture may show (the scene keeps a library; unknown → none). Default: none. */
  figure?: string;
  /** Writes only while this holds (e.g. reckonings ≥ 2): how the cast grows from one correspondent. Default: always. */
  when?: Cond;
}

/** M3: one answer to a dispatch. Every arm has a price (lint): a cost, a downside effect, or both, stated in `price`. */
export interface DispatchArm {
  /** Button text, imperative, at most 28 characters: "Sink the shaft". */
  label: string;
  /** What happens, in the paper's words, one sentence (shown under the label). */
  outcome: string;
  /** What it costs, one short phrase ("£ and the mill owners' patience"). Required (lint). */
  price: string;
  /** Hard costs, refused unless affordable when the PLAYER answers: Mandate, and capital in seconds of current income
   *  (capital cost = capitalSeconds × Derived.incomePerSec at the moment, at least 0). A default answer pays what there
   *  is (floors at 0). Default: none. */
  cost?: { mandate?: number; capitalSeconds?: number };
  /** One-offs fire at once; standing effects stand for the rest of the run (once per answer). Default []. */
  effects?: EffectDef[];
  /** A timed modifier: standing effects for `years` model years from the answer (GameState.modifiers). Default: none. */
  modifier?: { effects: EffectDef[]; years: number; label?: string };
  /** A follow-up queued to come next (GameState.dispatch.queue), if eligible then. Default: none. */
  next?: string;
  /** The paper's line when this arm is chosen (headline 'answered'), ≤ 70 characters. Default: no item. */
  reply?: string;
  /* --- M4 --- */
  /**
   * M4: a wager. When this arm is answered, `when` is evaluated on the TRUE state at that moment (after `cost` is paid,
   * before any effect): if it holds, `win` is applied, else `lose`. Order of application: the cost; the arm's own
   * `effects`, `modifier` and `reply`, if any; then the branch's effects (one-offs at once, standing ones for the rest of
   * the run, once per answer, as an arm's own: GameState.dispatch.standing records [id, arm] and the core resolves the
   * branch from AnsweredDispatch.won), its modifier (an ActiveModifier with source = the dispatch id, arm = this arm and
   * branch 'win' | 'lose', beside the arm's own modifier if it has one) and its reply (a second 'answered' item, after
   * the arm's own reply).
   * `hint` is the condition in the paper's words, shown under the label with both outcomes ("Pays if the shoals are as
   * thick as the catch says"). AnsweredDispatch.won records the result; the 'dispatchAnswered' event carries n = arm and
   * label 'won' | 'lost'. Lint: a wager arm is never the default arm; win and lose each have at least one effect or a
   * modifier; `when` resolves; hint ≤ 70 characters; each outcome ≤ 120 characters. Default: none (an ordinary arm).
   */
  wager?: {
    when: Cond;
    hint: string;
    win: WagerBranch;
    lose: WagerBranch;
  };
  /* --- M5 --- */
  /**
   * M5: tags the arm for the rival's `pliant` reading (RivalDef.profileFrom.casts: player answers with stance 'accept' ÷
   * all player answers to those casts' dispatches) and for the file card (FileView.accepted / declined: 'accept' →
   * accepted; 'refuse' → declined; 'bargain' counts as an answer, in neither list). Content tags every arm of the Pryce
   * letters (both generations, Act I and the Previews): a content-only change to M3/M4 dispatches, no save impact.
   * Default: untagged (counts as an answer when its dispatch is of a counted cast, in neither list).
   */
  stance?: 'accept' | 'refuse' | 'bargain';
}

/** M4: one outcome of a wager arm (DispatchArm.wager). */
export interface WagerBranch {
  /** What happens, in the paper's words (≤ 120 characters). */
  outcome: string;
  effects?: EffectDef[];
  modifier?: { effects: EffectDef[]; years: number; label?: string };
  /** ≤ 70 characters (headline 'answered'). */
  reply?: string;
}

/**
 * M3: a dispatch (Content.dispatches): a letter from the cast with two or three answers, expiring to a default.
 * Eligible for a draw (see GameState.dispatch) when ALL hold: feature 'dispatches' on; its cast member's `when` holds;
 * `sector` absent, or open (settled counts as open); `age` absent, or Derived.age === age; `when` holds; not offered
 * already this run (GameState.dispatch.offered); if `once`, never offered before (meta.dispatches.seen[id] absent).
 * Pools EXTEND one another: sector and age dispatches join the general ones; nothing replaces anything.
 * Text: headline ≤ 70 characters; body ≤ 400 characters, a letter in the cast member's voice; placeholders as above.
 */
export interface DispatchDef {
  id: string;
  cast: string;
  sector?: SectorId;
  age?: AgeId;
  when?: Cond;
  /** Relative chance among equally fresh candidates. Default 1. */
  weight?: number;
  /** At most once in the save. Default false (it may return once the eligible pool has all been seen as often). */
  once?: boolean;
  /**
   * M5 (amend): 'parliament': in a Ministry the letter may recur within a run, once per Parliament: it is eligible (its
   * other conditions holding) while it is not pending and it was not answered or lapsed since the current Parliament
   * began (GameState.dispatch.answered; an entry trimmed from that list no longer blocks). Outside a Ministry, as
   * without it (not offered already this run). `once` still wins. Default: absent (never twice in a run).
   */
  recur?: 'parliament';
  headline: string;
  body: string;
  /** Two or three arms (lint). */
  arms: DispatchArm[];
  /** The arm taken on expiry (and by the dispatch standing order). Default 0. Lint: it has no `cost` and no standing
   *  `effects` (only one-offs and a timed modifier), so defaults never compound. */
  defaultArm?: number;
  /** Model years before it expires to the default. Default GlobalParams.dispatch.expiryYears. */
  expiryYears?: number;
  /** The named rebound it dramatises (for the Archive and the lint; not shown). */
  rebound?: string;
}

/**
 * M3: an ambient headline template (Content.ambient), printed at ambient ticks (GlobalParams.ambient) while feature
 * 'ambient' is on, never inside fastForward or a projection, never while a Reckoning is pending or the run is fresh.
 * At a tick: candidates = defs whose `sector` (if any) is open and unsettled, whose `when` holds, and whose last print
 * this run (GameState.ambientLast[id]) is at least cooldownYears ago (or never); pick the least recently printed
 * (never first), ties by weight with u = mix32(seed ^ (tick index × 0x85EBCA6B)) / 2^32 over content order. The variant
 * is text[mix32(seed ^ tick index) mod text.length]. No event; a NewsItem with key 'ambient'.
 * Numbers: with `stat`, {value} = the stat's value to 3 significant figures with thousands commas; {pct} = round(value
 * × 100) as an integer; {fold} = value to 1 decimal place (no "×"). Without `stat` those placeholders stay as typed.
 */
export interface AmbientDef {
  id: string;
  sector?: SectorId;
  when: Cond;
  /** Variants, each ≤ 70 characters after substitution at typical values (lint at value 1234.5). */
  text: string[];
  stat?: { stat: StatKey; sector?: SectorId; app?: string };
  cooldownYears?: number;
  weight?: number;
}

/**
 * M3: a History (Content.histories): a named counterfactual run, chosen between runs (ModelApi.chooseHistory), with a
 * goal. THE HISTORY RULES (design/genre-audit.md rec. 14; the lint enforces the mechanical ones):
 *   1. Rewards are options, never power needed to progress: only `reward.unlock` of locked Commons projects or locked
 *      Charters, an achievement, a cosmetic scene key and a title. Never an upgrade, lever, Know-how node, Institution,
 *      seat, Hindsight or Mandate.
 *   2. No quality-of-life feature or automation is ever locked behind a History: no orderUnlock, offlineCapAdd or
 *      slotAdd in `reward`, and nothing a History unlocks is needed by any other system.
 *   3. The ladder (stacking several Histories) is post-game only and capped at 30 rungs: M9, not here; nothing in M3
 *      stacks Histories (one in force at a time).
 *   4. Each History is cleared by the balancer's generic `budget` strategy within 2× the median clearing time.
 * In force (meta.history === id) it acts like a second Charter for that run: standing effects in force, start-of-run
 * effects at build, one-offs ignored; it COMPOSES with the Charter (both apply; effects multiply or add as usual)
 * unless `suspend` lists 'charter'.
 */
export interface HistoryDef {
  id: string;
  /** "Coal-rich", "No Watt", "Laissez-faire". */
  name: string;
  blurb: string;
  /** The rebound it isolates, in words ("The resource curse"). */
  rebound: string;
  effects: EffectDef[];
  /** Meta systems that do not apply in this run: Know-how, the seated Institutions, the Charter, the Market. Default []. */
  suspend?: ('knowhow' | 'institutions' | 'charter' | 'market')[];
  /** The History's `forbid` effects lift for the rest of the run the first step this holds (GameState.historyLifted;
   *  "no levers until the second crisis"). Default: never. */
  forbidUntil?: Cond;
  /** Completion: checked about once a real second while in force; the first time it holds the History is cleared. */
  goal: Cond;
  /** The goal in words, for the picker ("Steady State in Steam within the run"). */
  goalLabel: string;
  reward: { unlock?: string[]; achievement?: string; cosmetic?: string; title?: string };
  /** Offered in the picker only while this holds against the fresh run. Default: always (once feature 'histories'). */
  requires?: Cond;
}

/**
 * M3: an Archive note (Content.archive): the real history behind a thing in the game, unlocked the first time its
 * subject is owned or seen, kept for good (MetaState.archive). Rules by subject kind (checked at least once per real
 * second of play, and at the end of every action; recorded whether or not feature 'archive' is on):
 *   upgrade, lever, Commons project, seam: first owned (level ≥ 1, built, sunk) by anyone;
 *   application: first available; sector: first opened; dispatch: first offered; Charter or History: first chosen;
 *   cast member: their first dispatch offered; an achievement: earned. Unknown subject → never (lint).
 *   M5: a loophole rung: first given a state (opened) in any Ministry; a pledge: first in force (meta.pledgesKept); an
 *   Article: bought; a playbook: learnt; the rival's id (RivalDef.id): office taken.
 * Facts only from design/research/*.md marked [V], or verified by the writer with the source recorded here.
 */
export interface ArchiveDef {
  id: string;
  /** The content id it is about (any kind above). Several notes may share a subject. */
  subject: string;
  /** "The separate condenser, 1769". */
  title: string;
  /** 60–160 words, the paper's archive voice. */
  text: string;
  /** At least one (lint). `grade`: 'V' verified against a primary or scholarly source; 'S' a reputable secondary. */
  sources: { cite: string; url?: string; grade: 'V' | 'S' }[];
  /** Display date ("1769", "c. 1800"). Default ''. */
  date?: string;
}

/**
 * M3: the Proprietor's Day texts (Content.proprietor). Placeholders, all formatted by the core: {workdayBefore},
 * {workdayAfter} (minutes a day, integers), {workdayChange} (absolute per cent, integer, no sign: "40"), {decisionsBefore},
 * {decisionsAfter} (decisions an hour, integers), {decisionsChange}, {sessionsBefore}, {sessionsAfter} (sessions a day,
 * 1 decimal), {automatedPerHour} (integer). The direction picks the template list; the text never says "you" (the
 * proprietor), never scolds, and says plainly when figures went down.
 */
export interface ProprietorText {
  /** The question (shift 3): a letter from a cast member, shown when the card first becomes visible. */
  pamphlet: { cast: string; headline: string; body: string };
  /** Return templates by direction (see SurveyView.direction); at least one per direction (lint). */
  returns: { direction: 'up' | 'down' | 'flat'; headline: string; body: string }[];
  /** The line printed by withdrawReturn ("The Household Survey is discontinued for want of funding"). */
  withdrawn: string;
}

/**
 * M3: the first ending's texts (Content.ending). The retrospective is assembled by ModelApi.retrospective from the
 * player's own milestones: one item per milestone key that has a template (key match: exact, or the prefix before ':'
 * as in 'steady:*'), in the milestones' chronological order. Placeholders: {year}, {run} (the run number), {hours}
 * (cumulative active hours, 1 decimal), {sector} (for keyed milestones), plus the usual.
 */
export interface EndingText {
  credits: { title: string; lines: string[]; continueLabel: string };
  retrospective: { key: string; headline: string }[];
}

/* ------------------------------------------------------------------ */
/* M5 CONTENT: office, the Chair, the rival, loopholes, the Treaty     */
/* ------------------------------------------------------------------ */

/*
 * M5 ("The Other Chair"; design/m5-contract-notes.md §§1–9). Everything here is optional content: with no
 * Content.office no office is ever offered, and with no Content.chair or Content.rival no Ministry can be built
 * (takeOffice refuses). Every new rule reads the state at the start of the step, as M2–M4's do; nothing is random
 * (deterministic draws use mix32, GameState.charterOffer) and nothing reads the wall clock. "YPS" below is
 * YEARS_PER_SECOND; "a model-year boundary" is a step from t0 to t1 with floor(t1 × YPS) > floor(t0 × YPS) (tick and
 * fastForward alike); "an order tick" is the M2 rule (OrdersState).
 */

/**
 * M5: Take office (Content.office). The invitation, the acquisition, the prospectus and the file.
 * THE OFFER: reckon() evaluates `when` on the run being ended (its last state, before the reset); if it holds and office
 * is not taken, the fresh run has GameState.officeOffer = true (else false). A run that does not take office ("Not
 * yet": the page simply starts the run; no action) is offered again at its own Reckoning only if `when` holds again
 * (it does for any later run with Motion open five minutes).
 * M5 content: { all: [ { ending: 'actOne' }, { stat: 'openFor', sector: 'motion', op: '>=', value: 300 } ] }.
 */
export interface OfficeDef {
  when: Cond;
  /** The texts (OfficeText). */
  text: OfficeText;
  /** How many opening items the prospectus quotes (repeats of one upgrade fold into one item). Default PROSPECTUS_ITEMS. */
  prospectusItems?: number;
}

/**
 * M5: the texts of Take office (OfficeDef.text). Placeholders, formatted by the PAGE with content/words.ts's formatter
 * from ProspectusView / FileView (the core stores the figures, not the words): {item:n} (the n-th prospectus item's name,
 * 1-based), {t:n} (its run time, seconds; words.ts prints ordinals: "the eighteenth second", "a minute and twenty-six
 * seconds"), {count:n} (its count), {every:n} (mean interval of a folded repeat, seconds), {share} (FileView
 * .automatedShare, integer per cent), {seasons} (FileView.seasons), {year} (the first polling year), {label} and
 * {dispatch} (in file lines), plus the usual headline placeholders where a NewsItem carries them.
 */
export interface OfficeText {
  /** The Gazette: headline 'acquisition' ("PRYCE CONSOLIDATED ACQUIRES THE WORKS") and its sub-line. */
  acquisition: { headline: string; sub: string };
  /** The Minister's letter (a card, not a dispatch, so it cannot be defaulted away): writer (a cast id), body, button. */
  letter: { cast: string; body: string; button: string };
  /** The Reckoning card's two buttons: "Take office", "Not yet". */
  offer: { take: string; notYet: string };
  /**
   * The prospectus: title; `first` (the first-opening paragraph, with {item:n} … placeholders up to prospectusItems);
   * `firstDefault` (when ProspectusView.defaulted: "the trade's usual method"); `chair` (the paragraph on the last run's
   * foundings in chair sectors; omitted when ProspectusView.motion is null); `close` ("The directors are confident…");
   * `button` ("File it").
   */
  prospectus: { title: string; first: string; firstDefault: string; chair: string; close: string; button: string };
  /**
   * The file card: title; `accepted` and `declined` line templates ({label}, {dispatch}, {year}); `automated` ("Of the
   * purchases made in the Works' name in its last {seasons} seasons, {share}% were made by standing order"); the
   * conclusion by pliant band (the first entry whose pliantBelow > FileView.pliant, else the last); `button`.
   */
  file: {
    title: string; accepted: string; declined: string; automated: string;
    conclusion: { pliantBelow: number; text: string }[];
    button: string;
  };
  /** The broadsheet line printed once when Compute and Code close ("The machines are to be the next Age's business…"),
   *  key 'officeTaken', after the officeTaken headline. Default: none. */
  sealed?: string;
}

/**
 * M5: the Chair (Content.chair). All numbers are content; the core supplies only the defaults named.
 *
 * CONFIDENCE (ChairState.confidence, 0–CONFIDENCE_MAX), in the step at each model-year boundary (tick and fastForward
 * alike), in a Ministry while feature 'chair' is on (in office and in Opposition alike):
 *   C ← clamp(C + relaxPerYear × (C* − C) − lobbyPerYear × L, 0, CONFIDENCE_MAX)       L = levers the rival is lobbying
 *   C* = base + perWellbeing × (W − wellbeingTarget)
 *          + perPriceShare × priceShare + perJobShare × jobShare + perCommonsLevel × Σ GameState.commons.levels
 *          + Σ over pledges in force PledgeDef.confidence + Σ over levers at level ≥ 1 their popularity term
 *   priceShare = Σ_s w_s × levyPart'_s / p_s over open chair sectors (w_s = wellbeingWeight_s ÷ Σ of theirs; capstoned
 *     sectors have no levy and are left out); levyPart'_s = Σ over the sector's levies (duty part, permit part, charge
 *     part) of the part × (1 for 'treasury' or 'commons' recycling, −0.5 for 'dividend': a dividend offsets).
 *   jobShare = Σ over open chair sectors not compensated now (ChairState.compensated[s] > time) of
 *     max(0, 1 − income_s / RivalState.peakIncome[s]) (0 when peakIncome is 0).
 *   W = Derived.wellbeing; all flows from the state at the start of the step.
 * ONE-OFFS act on C at once (clamped), not at the boundary: fineFound at an inspection that finds concealment; crisis at
 * any crisis in an open sector (any sector, chair or not, capstone arrears crises included); campaignPerMandate × Mandate
 * spent by campaign(); a 'confidenceAdd' effect; PledgeDef.atPoll at polling day.
 * Before the first boundary C = confidence.start (set when the Ministry is built). Outside a Ministry nothing runs.
 *
 * ELECTIONS: ChairState.parliament; polling-day rules at ChairState. INSPECTION: ChairState and RivalState. TREASURY:
 * GameState.capital in a Ministry (see ChairDef.treasury). AMENDMENT: LoopholeDef.
 */
export interface ChairDef {
  /** M5 (amend): Mandate every Ministry opens with (createState in office; takeOffice's rebuild and the between-runs
   *  rebuilds keep the larger of the run's Mandate and this). Absent = 0 (the Act I opening). The Ministry's first rule
   *  can be written in its first half minute. */
  startMandate?: number;
  confidence: {
    /** C at the start of every Ministry (55). */
    start: number;
    /** Polling: won ⇔ C + Σ chosen atPoll ≥ winAt (50). */
    winAt: number;
    /** Share of the gap to C* closed at each model-year boundary, 0–1 (0.15). */
    relaxPerYear: number;
    /** C* with nothing happening (50). */
    base: number;
    /** Per point of wellbeing above GlobalParams.wellbeingTarget (negative below). */
    perWellbeing: number;
    /** Per unit of priceShare (normally negative). */
    perPriceShare: number;
    /** Per unit of jobShare (normally negative). */
    perJobShare: number;
    /** Per Commons level built this run. */
    perCommonsLevel: number;
    /** M5 (contract): a POSITIVE magnitude, subtracted from C at each boundary per lever the rival is lobbying. (The
     *  notes call it negative and also subtract it; the contract fixes the sign here.) */
    lobbyPerYear: number;
    /** One-off when an inspection finds concealment (positive). */
    fineFound: number;
    /** One-off at any crisis in an open sector (negative). */
    crisis: number;
    /** campaign(): C += campaignPerMandate × Mandate spent. */
    campaignPerMandate: number;
  };
  /**
   * Parliaments: the first (caretaker, index 0) lasts firstTermYears model years from the Ministry's start; each later
   * one termYears + Σ termYearsAdd (floored at 1). The pledge offer is drawn noticeYears before polling day: `offer`
   * pledges (+ Σ pledgeOfferAdd), of which the player keeps `keep`. A won election pays winMandate Mandate.
   * Content: 10, 15, 3, 3, 2, winMandate a first guess.
   */
  elections: { firstTermYears: number; termYears: number; noticeYears: number; offer: number; keep: number;
               winMandate: number };
  /** Opposition: lever levels repealed per lost election (1); losses in a row that end the Ministry (2). */
  opposition: { repealPerParliament: number; lostInARowEnds: number };
  /**
   * Inspection (feature 'inspection'): inspectors (2) before inspectorAdd; an Inspector rests cooldownYears (5) after an
   * inspection; true R is shown for revealYears (10) after one; the rival's quiet period quietYears (6; see RivalDef
   * .policy for his adjustment); concealment ramps concealPerYear (0.02 of true R per model year) up to concealMax (0.2);
   * fineMul scales the fine and the expected fine (see ChairState, the inspection rules).
   */
  inspection: { inspectors: number; cooldownYears: number; revealYears: number; quietYears: number;
                concealPerYear: number; concealMax: number; fineMul: number };
  /**
   * The Treasury (GameState.capital in a Ministry). Income per second = taxShare × the rival's income per second (chair
   * and capstoned sectors) + levyShare × levy revenue routed 'treasury' (the Mandate share of 'treasury' recycling,
   * GlobalParams.levy.mandateShare, is unchanged and separate). Both 0–1.
   */
  treasury: { taxShare: number; levyShare: number };
  /** compensate(s): cost (£, from the Treasury) = costYears / YPS × max(0, peakIncome_s − income_s) × Π compensationMul
   *  (costYears model years of the income per second the rival has lost); the jobs term ignores s for `years` model
   *  years (ChairState.compensated). */
  compensation: { costYears: number; years: number };
  /** Default amendment cost (Mandate) and drafting time (model years), where a LoopholeDef has no `amend`. */
  amend: { mandateCost: number; years: number };
  /**
   * Hindsight in a Ministry: these fields overlay GlobalParams.hindsight while office is taken (a field present here
   * replaces the global one), plus perParliamentWon (HindsightTerms.parliaments = perParliamentWon × electionsWon).
   * Default: no overlay, perParliamentWon 0.
   */
  hindsight?: Partial<GlobalParams['hindsight']> & { perParliamentWon?: number };
  /**
   * The Treaty (feature 'treaty'): offered between runs while `when` holds (content: { stat: 'settledFromChair', op:
   * '>=', value: 1 }); Precedent paid = max(1, round(perCertifiedDecade × record.certifiedDecades + perSettledFromChair ×
   * record.settledFromChair + perParliamentWon × record.parliamentsWon + perWellbeingYear × record.wellbeingYears)) over
   * MetaState.office.record. Absent: no Treaty.
   */
  treaty?: { when: Cond; perCertifiedDecade: number; perSettledFromChair: number; perParliamentWon: number;
             perWellbeingYear: number };
  /** ChairView.target and ChairView.forecast are shown (non-null) only while this holds (Statecraft's Polling:
   *  { owns: '<node>' }). Default: always shown. */
  showTarget?: Cond;
}

/**
 * M5: a pledge (Content.pledges), offered on the manifesto sheet before polling day (ChairState.parliament.offer).
 * Chosen pledges come INTO FORCE at polling day (ChairState.pledges) and bind the Ministry's hands for the whole of the
 * next Parliament, won or lost; in force they add `confidence` to C* and their `effects` stand. Text: name ≤ 40
 * characters ("No new taxes on motoring"), blurb one line.
 */
export interface PledgeDef {
  id: string;
  name: string;
  blurb: string;
  /** Added to C* while in force. */
  confidence: number;
  /** Added to C once, at the polling day it is chosen for (and counted in the won test). Default: `confidence`. */
  atPoll?: number;
  /**
   * Binds: while in force, setLever (and the Civil Service) refuse a raise above `max` on the lever `lever`, or on every
   * lever of `leverKind` (in `sector` if given). Lowering is always allowed. LeverView.bound carries the pledge's name.
   * Default: binds nothing.
   */
  binds?: { lever?: string; leverKind?: LeverKind; sector?: SectorId; max: number };
  /** Standing effects while in force (a railway for every town: a substitution flowCap through effects…). Default []. */
  effects?: EffectDef[];
  /** M5 (contract): while in force, Treasury income × (1 − treasuryShare) (0–1): a promise the Treasury pays for.
   *  Default 0. */
  treasuryShare?: number;
  /** Offered only while this holds (sector open, feature on…), evaluated when the offer is drawn. Default: always. */
  when?: Cond;
}

/** M5: the rival's character, five readings 0–1, distilled once at takeOffice (MetaState.office.profile). */
export interface RivalProfile {
  /** Purchases per minute in the first ten minutes of meta.firstOpening, scaled by RivalDef.profileFrom.hasteAtPerMinute. */
  haste: number;
  /** Share of the first opening's actions that founded rather than improved. */
  founder: number;
  /** Share of the first opening's fork purchases that took the arm with the larger demand effect (0.5 if none). */
  volume: number;
  /** 1 − min(1, earliest firstBudgetAt over meta.runs / drawnBySeconds); 0 if no line was ever drawn. */
  drawn: number;
  /** Player answers with stance 'accept' ÷ player answers, over the counted casts' dispatches (0.5 if none). */
  pliant: number;
}

/**
 * M5: a kind of answer the rival may give a lever. OPEN union: M6 adds 'offshore' and 'capture'; core and UI handle an
 * unknown kind with a default label and treat it as never available unless a core function prices it.
 */
export type ResponseKind = 'comply' | 'evade' | 'lobby' | 'litigate' | 'conceal' | (string & {});

/**
 * M5: one row of the rival's table (RivalDef.responses). Costs are a model year of his money (£), on the state at the
 * start of the order tick; I = the sector's income per second to him (m × pPre × D, as the player's income was) × 1 /
 * YPS (a model year of it). Every cost × costScale × Π rivalCostMul effects for the kind.
 *   comply    available always. cost = max(0, I(lever at level 0) − I(lever at the level being answered)), each one
 *             solve of the sector with everything else as now. (Notes §3.4's "previous answered level" would price every
 *             periodic re-answer at 0; the contract reads "rule off" literally.) Effect: none.
 *   evade     available while the lever has a rung with status 'open' whose closedBy does not hold (and feature
 *             'loopholes'). cost = LoopholeDef.premium × I. Effect: that rung → 'used' (LoopholeDef rules).
 *   lobby     available while C > carveOutAt' (= lobby.carveOutAt + profile.drawn × policy.drawnLobby) and no carve-out
 *             of this lever was won this Parliament. cost = lobby.costPerPoint × max(0, C − carveOutAt') × I / 100 (a
 *             large firm's points cost more). Effect: RivalState.lobbying[id] = true (C falls lobbyPerYear at each
 *             boundary); at the first order tick with C < carveOutAt', ChairState.carveOuts[id] = parliament.index
 *             ('carveOut' event and headline) and lobbying[id] is cleared.
 *   litigate  available while (time − LeverState.raisedAt) × YPS ≤ litigate.windowYears and the lever has not been
 *             litigated at this level this run. cost = litigate.feeYears × I. Effect: ChairState.litigation[id] = { from:
 *             the level he last answered (RivalState.answers[id].level, 0 if none), until: time + delayYears × Π
 *             litigateYearsMul / YPS } ('litigated' event and headline).
 *   conceal   never a candidate in the answer: a 'conceal' row in RivalDef.responses ENABLES concealment of returns
 *             (ChairState, the inspection rules; gated by its `feature`); its costScale is unused.
 * Ties between equal costs: comply, evade, lobby, litigate, then unknown kinds in table order. An unavailable kind's cost
 * is Infinity.
 */
export interface ResponseDef {
  kind: ResponseKind;
  /** Multiplies this response's cost (a balance knob; playbooks multiply it further). Default 1. */
  costScale?: number;
  /** Available only once this feature is unlocked (evade: 'loopholes'; conceal: 'inspection'). Default: always. */
  feature?: FeatureId;
  /** 'lobby' only: £ per Confidence point (× I / 100) and the carve-out line. */
  lobby?: { costPerPoint: number; carveOutAt: number };
  /** 'litigate' only: the window after a raise, the delay won, the fee in model years of I. */
  litigate?: { windowYears: number; delayYears: number; feeYears: number };
}

/**
 * M5: the rival (Content.rival): Pryce Consolidated. He acts only in a Ministry, only on rival sectors (ActDef.chair).
 *
 * THE POLICY from the profile (MetaState.office.profile), fixed for the save:
 *   paybackMax = lerp(paybackSlow, paybackFast, haste); foundPaybackMax = lerp(foundSlow, foundFast, founder);
 *   fork arms: of each fork (upgrades listing each other in `excludes`) he considers only the arm whose demand effect
 *     (Π of its satMul and halfPriceMul effect values on its own sector; 1 if none) is the larger when volume ≥ 0.5, the
 *     other arm(s) when volume < 0.5 (ties: content order, first arm = "larger");
 *   carveOutAt' = lobby.carveOutAt + drawn × drawnLobby (ResponseDef);
 *   quiet period = inspection.quietYears + round((0.5 − drawn) × quietSpread) + Σ quietYearsAdd (floored at 0);
 *   letters: every dispatch of cast `cast` has weight × (1 + pliant) in the draw while office is taken.
 *
 * THE YEARLY DECISION, at each order tick in a Ministry (never while fresh or a Reckoning is pending, never in
 * projections), after the step's other rules and BEFORE the player's standing orders:
 *   0. Income (every step, not only at ticks): capital += (1 − taxShare) × Σ over rival sectors income_s × dt (income_s
 *      = m × pPre × D, or a capstoned sector's scaled income); the Treasury takes the taxShare (ChairDef.treasury).
 *   1. Purchase: per open, unsettled chair sector in sectorOrder, at most one action, by exactly the Market's candidate
 *      rule and payback (OrdersState: the same core function), with capital = RivalState.capital, upgrades judged
 *      against paybackMax and foundings against foundPaybackMax, fork arms by `volume` (the Market never buys forks; he
 *      does), 'research' and 'prospect' cards never (as the Market), a subsidised target's payback at (1 − value) ×
 *      cost (LeverKind 'subsidy'). Recorded with actor 'rival': capital charged to him, run.opening (if room), events
 *      'upgradeBought' / 'appFounded' / 'stageReached' by 'rival'; NOT run.automated nor run.decisions (they are not the
 *      player's). GameState.orderLog[s] is written as the Market's is.
 *   2. Answers: per lever of a chair sector at level ≥ 1 whose level differs from RivalState.answers[id].level, or with
 *      no answer, or whose answer is older than steady.decadeYears (default 10) model years, or marked due (a rung
 *      closed or returned to 'open'): evaluate every row's cost (ResponseDef), choose the cheapest, record it in
 *      answers[id] (with the comply cost) and apply its effect; 'rivalAnswered' (id = lever, label = kind) when the kind
 *      changed. A lever now at level 0 loses its answer, lobbying and litigation entries.
 *   3. Concealment ramp (ChairState, the inspection rules), per rival sector.
 * Purchases in a later sector of the same tick see the capital spent in earlier ones.
 */
export interface RivalDef {
  /** 'pryce'. */
  id: string;
  /** "Pryce Consolidated" (as printed). */
  name: string;
  /** The cast id of his letters ('pryceChair'). */
  cast: string;
  /** The profile used when meta.firstOpening is absent (the balancer's `efficiency` opening). */
  defaultProfile: RivalProfile;
  /** His table (ResponseDef). Content lists comply first. */
  responses: ResponseDef[];
  /** Profile → policy (above). Paybacks in seconds; drawnLobby in Confidence points; quietSpread in model years. */
  policy: { paybackSlow: number; paybackFast: number; foundSlow: number; foundFast: number; drawnLobby: number;
            quietSpread: number };
  /**
   * The profile from the opening (pure, once, at takeOffice; RivalProfile):
   *   haste = clamp((purchases with t < 600 in meta.firstOpening.actions / 10 − a) / (b − a), 0, 1), [a, b] =
   *     hasteAtPerMinute; founder = founds / actions (0.5 if no actions); volume as RivalProfile; drawn uses
   *     drawnBySeconds; pliant counts the dispatches of the cast ids in `casts` (the Pryce letters of both generations).
   */
  profileFrom: { hasteAtPerMinute: [number, number]; drawnBySeconds: number; casts: string[] };
  /** "Pryce has read your notebooks": a standing etaMul of min(cap, 1 + k × Σ office.handedOver levels) on every chair
   *  sector, in every Ministry (k 0.01, cap 1.25). */
  knowhowTransfer: { k: number; cap: number };
  /** His opening purse: each time a chair sector opens in a Ministry, capital += startCapitalSeconds × that sector's
   *  income per second at its first solve (with the transfer applied). */
  startCapitalSeconds: number;
}

/** M5: a loophole rung's state (LoopholeState.status). */
export type LoopholeStatus = 'open' | 'used' | 'drafting' | 'closed';

/**
 * M5: one rung of a lever's ladder (Content.loopholes; LeverDef.ladder). Rungs are run state (ChairState.loopholes),
 * rebuilt empty each Ministry; only in a Ministry; only while feature 'loopholes' is on.
 * RULES:
 *   - When a laddered lever first reaches level ≥ 1 in a Ministry, its first rung whose `when` holds gets a state
 *     'open' (since = time; 'loopholeOpened'). Rungs whose `when` fails are skipped (M6's rungs that need Abroad).
 *     M5 (amend): no rung opens, is used or acts while feature 'loopholes' is off. A lever raised BEFORE the feature
 *     arrives (the rival has answered it at its current level) opens its first rung at the first order tick after the
 *     arrival, and its answer falls due then (the first loophole appears with the feature, never silently before it).
 *   - Evade (ResponseDef) sets the first 'open' rung 'used' ('loopholeUsed'); if it has an `app` not yet founded, the
 *     rival founds it free (by 'rival'; its ApplicationDef.when should be { loophole: id, status: 'used' }).
 *   - While 'used' (and while 'drafting' after use): the lever's grip escapes by `escape`: a measure's effects act with
 *     times × (1 − escape); a duty's dutyPart and a charge's chargePart × (1 − escape); a cap's or quota's target ÷
 *     (1 − escape) (composed with concealment's ÷ (1 − c)); the rung's `effects` stand with times = the lever's effective
 *     level. A sufficiency, substitution, circularity or other kind: only `effects`.
 *   - closedBy: while it holds the rung is unavailable to the rival (evade cost Infinity); a 'used' rung whose closedBy
 *     holds at an order tick returns to 'open' (its escape and effects stop; its exempt app keeps adoption, frozen by its
 *     own `when`) and the lever's answer falls due.
 *   - amend(id): ModelApi.amend. At draftUntil (the first step whose end time ≥ it, in office; an amendment that
 *     completes in Opposition is held and closes on the first step back in office): status 'closed' ('loopholeClosed');
 *     the next rung of the ladder whose `when` holds gets 'open' ('loopholeOpened'); the lever's answer falls due.
 * Text: name ≤ 40 characters ("Light trucks"), blurb one line ("Vans are counted separately").
 */
export interface LoopholeDef {
  /** Unique game-wide ('motion.mileage.lightTrucks'). */
  id: string;
  /** The lever whose ladder holds it (LeverDef.ladder lists this id). */
  lever: string;
  name: string;
  blurb: string;
  /** The exempt application the rival founds (free) when he first uses this rung. Default: none. */
  app?: string;
  /** Share of the lever's grip that escapes while used, 0–LOOPHOLE_ESCAPE_MAX. */
  escape: number;
  /** Standing effects while used, times = the lever's effective level (the heavier vehicle: satMul on the exempt app).
   *  Default []. */
  effects?: EffectDef[];
  /** The evade cost: premium × I (ResponseDef). */
  premium: number;
  /** Amendment: Mandate cost (no effect scales it) and drafting years (× Π amendYearsMul) and the button's label ("Count every vehicle under 8,500 lb"). Default: ChairDef.amend with label = `name`.
   *  Absent WITH closedBy: the rung cannot be amended, only closed by pairing (LoopholeView.canAmend false). */
  amend?: { mandateCost: number; years: number; label: string };
  /** The robust rung: unavailable to the rival while this holds (a duty in force: { owns: 'motion.duty' }). Default:
   *  none. LoopholeView.robustLabel = its label. */
  closedBy?: Cond;
  /** M5 (contract): the rung opens only if this holds when its turn comes; otherwise it is skipped. Default: always. */
  when?: Cond;
  /** Scene prop key for the exempt thing ('vans', 'borehole'); unknown → none. */
  prop?: string;
}

/**
 * M5: a Treaty Article (Content.articles), bought with Precedent between runs (buyArticle), kept for good: its effects
 * stand in every Ministry. Offered while `requires` holds (between runs). Text: name ("The Ratchet Clause"), blurb.
 */
export interface ArticleDef {
  id: string;
  name: string;
  blurb: string;
  /** Precedent. */
  cost: number;
  effects: EffectDef[];
  /** Default: always. */
  requires?: Cond;
}

/**
 * M5: a playbook the rival learns at a Treaty (Content.playbooks): the one with `treaty` === meta.treaties after the
 * increment joins meta.playbooks (treaty 1 = the first treaty() call, which is the second Treaty counting Take office).
 * Its effects stand in every later Ministry (quietYearsAdd negative, rivalCostMul…).
 */
export interface PlaybookDef {
  id: string;
  name: string;
  blurb: string;
  treaty: number;
  effects: EffectDef[];
}

/* ------------------------------------------------------------------ */
/* STATE (serialisable, plain JSON)                                    */
/* ------------------------------------------------------------------ */

export interface GameState {
  version: number;
  seed: number;
  /** Seconds played this run. */
  time: number;
  capital: number;
  mandate: number;
  population: number;
  peakPopulation: number;
  /** Bought this run: upgrade id → level (1 for one-offs). */
  upgrades: Record<string, number>;
  /** lever id → state. */
  levers: Record<string, LeverState>;
  /** M1 CHANGE (was `eras`): one entry per sector in content, open or closed. */
  sectors: Record<SectorId, SectorState>;
  flags: {
    /** The Coal Question has been researched (or a seated institution reveals). */
    revealed: boolean;
    /** The first ending's condition met this run: every Industry settled for GlobalParams.endingYears (see
     *  steadyYearsAll). Stays true for the rest of the run. */
    won: boolean;
  };
  /**
   * The first ending's streak, in model years. (The name is M1's; the rule has changed twice, the field never.)
   * M3 (finish) RULE: a step counts (steadyYearsAll += the step's model years) when EVERY sector in content.sectorOrder
   * is open and settled (SectorState.settled ≠ null) at the step's start and end; any other step resets it to 0 (so an
   * Industry unsettled by the player or by a lapsed defence, or a closed one, breaks it). Wellbeing is not part of the
   * rule: each settlement was made at Steady State, which already required the wellbeing target. flags.won is set
   * when steadyYearsAll ≥ GlobalParams.endingYears (default STEADY_STATE_YEARS). Not gated by the 'steadyState'
   * feature (Settlement can only exist after it).
   * (Superseded: M1 counted years in which every open sector decoupled; M2 counted wellbeing at the target with every
   * open sector settled or within budget and clear. A save mid-streak under the old rule keeps its number and loses
   * it on the first step that does not meet the new rule; no migration is needed, the shape is unchanged.)
   * M4 RULE (with Content.acts; without them the M3 (finish) rule above, unchanged): let A = the current act (ActDef).
   * If A has an `ending`, a step counts (steadyYearsAll += the step's model years) when every sector in A.ending.sectors
   * is open and settled (SectorState.settled ≠ null; a capstoned sector counts) at the step's start and end; any other
   * step resets it to 0. flags.won is set when steadyYearsAll ≥ endingYears; at that step the core writes
   * meta.endings[A.ending.id] (an EndingRecord), the milestone 'ending:<id>', a 'won' event then an 'ending' event
   * (id = A.ending.id), a 'steadyAll' headline then an 'actEnding' headline ({name} = A.title), and, if A.capstone,
   * meta.world.capstone (CapstoneRecord, one per sector of A.ending.sectors). If A has no ending (a Preview act), or
   * there is no current act, steadyYearsAll stays 0. flags.won stays true for the rest of the run, as in M3, and no
   * second ending is reached in that run; the NEXT run's current act is the following act. Not gated by any feature.
   */
  steadyYearsAll: number;
  news: NewsItem[];        // newest first, capped at 40
  /** Sampled every 5 s of run time, capped at 240 samples (older half thinned). */
  history: HistorySample[];
  run: RunStats;
  /** Survives a Reckoning. */
  meta: MetaState;

  /* --- M2 --- */
  /**
   * M2: decade dividends waiting for a choice, oldest first. A decade whose sector resolves a non-empty decadeChoices
   * list appends { sector, decade, options, mul } (see SteadyParams.decadeChoices; mul = the line's pace dividendMul at
   * the moment of the decade). Unchosen offers never block play and wait until chosen (chooseDecadeDividend) or until
   * the run ends (a Reckoning discards them, unpaid). Overflow: when an append would make the list longer than
   * PENDING_DIVIDENDS_MAX, the OLDEST offer is first resolved as if its option 0 had been chosen (a 'dividendChosen'
   * event with by 'default'). Content puts the modest option first for this reason.
   * M2 (offline fix): inside fastForward there is no overflow: an offer that would make the list longer than
   * PENDING_DIVIDENDS_MAX is simply not made (the decade still counts and still pays its decadeEffects; only the
   * choice is forgone, counted in OfflineReport.dividendsForgone). Choices nobody was there to make never compound,
   * and the returning player finds the list full, not resolved for them. tick() keeps the overflow rule above.
   */
  pendingDividends: PendingDividend[];
  /** M2: the Commons this run: project id → levels owned (≥ 1; absent = 0), and the fund fed by 'commons' recycling (£). */
  commons: { levels: Record<string, number>; fund: number };
  /**
   * M2: things that happened, for the scene and the page to react to instead of diffing views. Oldest first (ascending
   * seq), at most EVENTS_MAX (the oldest dropped). Every event takes seq = ++meta.eventSeq, so seq is unique and
   * increasing across the whole save, across Reckonings. Deterministic: the same inputs give the same events.
   * Consuming without replays: the UI keeps `lastSeen`, sets it to meta.eventSeq whenever it loads or imports a save or
   * starts a new game (so nothing already in the save is replayed), and reacts only to events with seq > lastSeen.
   * A Reckoning starts the new run's list with its 'reckoning' event; the between-runs rebuild (Know-how, Institutions,
   * loadout, Charter, respec) keeps the list.
   */
  events: GameEvent[];
  /** M2: what the last fastForward did (the "While you were away" ledger), or null if none since the run began.
   *  tick() and player actions leave it unchanged; the UI decides when it has been shown. */
  lastOffline: OfflineReport | null;
  /**
   * M2: the Charters offered for this run (ids, at most two, in content order), fixed when reckon() builds the run;
   * [] in a brand-new game (no Reckoning yet) and once the run is no longer fresh it is only informative. The draw:
   *   E = every CharterDef whose `requires` holds against the fresh run reckon() built (before any Charter), in content
   *       order, minus the previous run's Charter (meta.lastRun.charter) if that leaves at least two;
   *   n = |E|; n ≤ 2 → the offer is E; otherwise, with h(x) = mix32(x) defined below and seed = this run's state.seed:
   *       i = h(seed) mod n;  j = (i + 1 + h(seed ^ 0x9E3779B9) mod (n − 1)) mod n;  offer = [E[min(i,j)], E[max(i,j)]].
   *   mix32(x): x = x >>> 0; x = Math.imul(x ^ (x >>> 16), 0x45D9F3B) >>> 0; x = Math.imul(x ^ (x >>> 16), 0x45D9F3B) >>> 0;
   *             return (x ^ (x >>> 16)) >>> 0.
   * Kept unchanged by the between-runs rebuild, so buying Know-how never changes the offer.
   */
  charterOffer: string[];

  /* --- M3 --- */
  /**
   * M3: the dispatch scheduler's run state. Rules (all inside the step, so tick and fastForward run them alike; never in
   * projections (lite), never while a Reckoning is pending or the run is fresh):
   *   Expiry first: each pending dispatch with expiresAt ≤ the step's end time is resolved with its default arm, by
   *     'default' (as answerDispatch would, but costs pay what there is).
   *   Then a DRAW when ALL hold: feature 'dispatches' on; the step's end time ≥ nextAt; pending.length < maxPending; the
   *     step is NOT inside fastForward or useBank ("a letter needs a reader": while away nothing new arrives, so nothing
   *     compounds; a draw that falls due away happens on the first live step after). The draw:
   *       1. candidates = eligible dispatches (DispatchDef); if none: nextAt += dispatchGap(state, draws) and stop.
   *       2. if any id in `queue` is a candidate, take the first such (and remove it from the queue);
   *       3. else keep the candidates with the smallest meta.dispatches.seen count (absent = 0) and pick by weight:
   *          u = mix32(seed ^ Math.imul(draws + 1, 0x9E3779B1)) / 2^32; walk them in content order accumulating
   *          weight / Σ weight; take the first whose running total exceeds u.
   *       draws += 1; push { id, arrivedAt: end time, expiresAt: end time + (expiryYears / YEARS_PER_SECOND) }; offered
   *       += id; meta.dispatches.seen[id] += 1; a 'dispatch' NewsItem (DispatchDef.headline) and a 'dispatchArrived'
   *       event. nextAt is NOT advanced by a draw: the next gap starts when this one is resolved.
   *   On every resolution (player, default or standing order): nextAt = max(nextAt, end time + dispatchGap(state, draws)).
   *   dispatchGap(state, k) = intervalYears / YEARS_PER_SECOND × (1 − jitter / 2 + jitter × u_k),
   *     u_k = mix32(state.seed ^ Math.imul(k + 1, 0x85EBCA6B)) / 2^32; dispatchFirstAt(content) = firstYears /
   *     YEARS_PER_SECOND. A fresh run has nextAt = dispatchFirstAt, draws 0 and empty lists.
   *   If the standing dispatch order is active for the dispatch's cast member (OrdersState.dispatch), it is answered at
   *   once in the same step with its default arm, by 'dispatch' (run.automated += 1; no decision).
   * A Reckoning ends every pending dispatch unanswered (no default effects) and the queue.
   */
  dispatch: {
    pending: PendingDispatch[];
    /** Follow-ups (DispatchArm.next), FIFO, at most 8 (older dropped). */
    queue: string[];
    /** Answers this run, oldest first, at most ANSWERED_MAX (their standing effects stay in force even when trimmed:
     *  see `standing`). */
    answered: AnsweredDispatch[];
    /** Ids offered this run (no repeats within a run). */
    offered: string[];
    /** Draws made this run. */
    draws: number;
    /** Run time of the next draw (seconds). */
    nextAt: number;
    /** Every answer this run whose arm has standing `effects`, as [dispatchId, arm] (never trimmed): the Mods source. */
    standing: [string, number][];
  };
  /**
   * M3: timed modifiers in force (dispatch arms' `modifier`), oldest first. Each applies its effects (looked up from
   * content by source and arm) as standing effects while time < until; it is removed at the end of the first step whose
   * end time ≥ until, with a 'modifierEnded' event. Stacking: different sources stack (effects compose as usual); the
   * SAME source and arm again refreshes `until` to the later of the two (it never stacks with itself). More than
   * MODIFIERS_MAX: the one ending soonest is removed first (no event). A Reckoning clears the list.
   */
  modifiers: ActiveModifier[];
  /** M3: ambient id → run time it was last printed (this run). */
  ambientLast: Record<string, number>;
  /** M3: the Market's last order-tick outcome per open sector, for OrdersView.market.why (see MarketWhy). Run-scoped. */
  orderLog: Record<SectorId, { t: number; outcome: 'bought' | 'none' | 'cash' | 'payback'; id?: string; payback?: number }>;
  /** M3: the History in force has met its forbidUntil this run (its forbid effects no longer apply). */
  historyLifted: boolean;
  /**
   * M3 (finish): headline variants used this run, by slot, so a key's variants come round in turn (the least recently
   * used first) instead of repeating. A slot is the HeadlineKey, or '<key>:<sector>' when the variants are that
   * sector's own (Content.sectorHeadlines). Value: how many headlines of the slot this run has printed. The variant
   * printed is (o + count) mod n, where n is the number of variants and o = (seed + the slot's character codes summed)
   * mod n, fixed per save and slot: every variant once before any repeats. Two headlines of one slot made from the same
   * state (one step) take the same variant (their placeholders differ). Absent = {} (older saves start the rotation
   * afresh). A Reckoning clears it (a fresh run has none). Not shown anywhere.
   */
  headlineUse?: Record<string, number>;
  /* --- M4 --- */
  /**
   * M4 (The Survey): the reveal recorded at the Board's first survey (RenewableDef.firstSurvey), so that the card shows
   * the figures of that moment however long it waits to be read: reported = (Q/K)^beta and true = Q/K at that step
   * (fractions 0–1), the variant (Content.surveyReveal), the calendar year (integer), and whether the follow-up
   * headline has been printed (it is printed on the next step, then followed = true). Derived.surveyReveal is built
   * from it. Absent or null = none this run; a Reckoning clears it.
   */
  surveyReveal?: {
    sector: SectorId; reported: number; true: number; variant: 'small' | 'large' | 'failed'; year: number;
    followed: boolean;
  } | null;
  /* --- M5 (optional: absent = false / null, so M4 states and hand-built test states stay valid) --- */
  /**
   * M5: the invitation to take office stands on this run: reckon() sets it on the fresh run when OfficeDef.when held on
   * the run just ended and office is not taken; false otherwise; takeOffice clears it. Kept by the between-runs rebuilds
   * (as charterOffer). The page offers Take office only while it is true and Derived.freshRun. Absent = false.
   */
  officeOffer?: boolean;
  /**
   * M5: the Ministry (ChairState), or null / absent outside office. Built by takeOffice, and by reckon() and
   * createState(content, meta) whenever meta.office is present: the ONE carry-over step (core inherit.ts) builds it
   * fresh each Ministry (confidence.start, the first Parliament, empty maps, the rival's state with capital 0 until a
   * chair sector opens; RivalDef.startCapitalSeconds). A Reckoning discards it.
   */
  chair?: ChairState | null;
}

/** M3: a dispatch waiting for an answer (GameState.dispatch.pending). */
export interface PendingDispatch {
  id: string;
  /** Run times (seconds). */
  arrivedAt: number;
  expiresAt: number;
}

/** M3: an answered dispatch (GameState.dispatch.answered). `t` is run time; `by` 'player', 'default' or 'dispatch'. */
export interface AnsweredDispatch {
  id: string; arm: number; t: number; by: Actor;
  /** M4: for a wager arm, whether `when` held at the answer (win) or not (lose). Absent for ordinary arms and on
   *  entries saved before M4. */
  won?: boolean;
}

/**
 * M3: a timed modifier (GameState.modifiers). `source` is the dispatch id; effects = that dispatch's arms[arm].modifier.
 * M4: with `branch`, effects = arms[arm].wager[branch].modifier instead; the stacking rule's "same source and arm" means
 * same source, arm and branch. A source beginning 'survey:' is the Board's first survey of sector <s> (arm 0, no
 * branch): effects = [{ type: 'survey', sector: s }], label = RenewableDef.firstSurvey.label ?? "The Board's survey"
 * (resolved by the core, never looked up in Content.dispatches).
 */
export interface ActiveModifier {
  source: string; arm: number; since: number; until: number;
  /** M4: the wager branch whose modifier this is (see above). Absent = the arm's own modifier. */
  branch?: 'win' | 'lose';
}

/**
 * M5: the Ministry's run state (GameState.chair). Run-scoped: built fresh each Ministry by inherit.ts; a Reckoning
 * discards it. Rules below run in the step (tick and fastForward alike unless marked), in a Ministry, while feature
 * 'chair' is on (inspection rules also need 'inspection'; loophole rules 'loopholes').
 *
 * THE PARLIAMENT CLOCK:
 *   - Offer: on the first LIVE step (never inside fastForward or useBank: the offer waits for a live step, as letters
 *     do) whose end time ≥ pollAt − noticeYears / YPS while offer is null: E = every PledgeDef whose `when` holds, in
 *     content order; n = elections.offer + Σ pledgeOfferAdd; if |E| ≤ n, offer = E; else draw without replacement from
 *     the remaining list Rm (initially E), for k = 0 … n − 1: idx = mix32(seed ^ Math.imul(index + 1, 0x9E3779B1) ^ k)
 *     mod |Rm|, take Rm[idx] and remove it; then sort the drawn ids into content order (so "the first `keep`", the
 *     default, are the mildest: content puts them first). seed = state.seed. 'electionCalled' event and headline.
 *   - choosePledges(ids) sets chosen (ModelApi.choosePledges).
 *   - POLLING DAY, the step whose end time ≥ pollAt (in this order): (1) chosen ?? the first `keep` of offer ?? [] →
 *     pledges (in force for the next Parliament; each id into meta.pledgesKept); (2) won ⇔ C + Σ over them (atPoll ??
 *     confidence) ≥ winAt; then C += that Σ (clamped); (3) won: electionsWon += 1, lostInARow = 0, inOpposition = false,
 *     Mandate += winMandate; 'electionWon'. Lost: lostInARow += 1, inOpposition = true, 'electionLost'; unless a standing
 *     'ratchet' effect is in force, the incoming government lowers by repealPerParliament levels (floored at 0) the
 *     chair-sector lever at level ≥ 1 with the largest RivalState.answers[id].comply (ties: content order; a lever with
 *     no answer counts 0), appending { lever, parliament: index } to `repealed` per level ('leverRepealed' by
 *     'opposition'); (4) if lostInARow ≥ lostInARowEnds: 'ministryDefeated' and a Reckoning becomes pending with cause
 *     'defeated' (Derived.pendingReckoning); (5) else the next Parliament: index + 1, start = end time, pollAt = end time
 *     + max(1, termYears + Σ termYearsAdd) / YPS, offer = chosen = null.
 *   - IN OPPOSITION: setLever (and the Civil Service) refuse every raise; lowering is allowed; amend() is allowed (an
 *     amendment completing in Opposition waits, LoopholeDef); campaign() is allowed only here; the rival goes on as
 *     before. The pledges in force bind as ever.
 *
 * INSPECTION AND CONCEALMENT (feature 'inspection'; design/m5-contract-notes.md §4):
 *   - Inspectors: total = max(0, inspection.inspectors + Σ inspectorAdd). inspectors[i] = run time Inspector i is ready
 *     (entries beyond the array, or ≤ time, are ready; the array grows as needed).
 *   - Concealment ramp, at each order tick, per rival sector s (step 3 of the rival's decision), only if RivalDef has a
 *     'conceal' row whose feature is on: let quiet = the rival's quiet period (RivalDef.policy) and fm = fineMul × Π
 *     fineMul; coverage = min(1, Inspectors total ÷ open rival sectors). If a standing 'certify' effect names s:
 *     concealment[s] = 0. Else if (time − (inspected[s] ?? 0)) × YPS ≥ quiet AND (s is capstoned OR (s has a duty,
 *     charge, cap or quota at effective level ≥ 1 AND fm × coverage < 1)): concealment[s] = min(concealMax,
 *     concealment[s] + concealPerYear × the tick's model years); else unchanged.
 *   - What it does (c = concealment[s]): SectorDerived.reportedR = R × (1 − c) (R stays the TRUE figure everywhere it was
 *     read before: decades, clear skies, Steady State, the budget streaks, pressure, the reserve, Hindsight); levy
 *     revenue (duty, permit, charge) × (1 − c); a cap's or quota's target is enforced on the reported figure: the solver's
 *     target becomes capR / (1 − c) (composed with a used rung's ÷ (1 − escape)). For a CAPSTONED sector the scaled
 *     record's R is the reported figure, the true R = R_rec / (1 − c), and the excess (true − reported) is stepped into
 *     its pressure as arrears are (SettledState, M4 arrears stepping; held below ARREARS_COLLAPSE_HOLD), without
 *     entering arrears; after c returns to 0 its pressure decays back to the recorded P as after arrears.
 *   - inspect(s): ModelApi.inspect. The fine (Mandate) = fm × c × L_s × quiet / YPS, with L_s = the sector's levy revenue
 *     per second at the true R × (GlobalParams.levy.mandateShare ?? 0.1): the Mandate the dodged levy would have
 *     earned over the quiet period (0 for a capstoned sector: Confidence and the headline only).
 *   - Certified decades: a decade recorded in office on a chair or capstoned sector is certified when inspected[s] falls
 *     inside its ten-model-year window (SectorState.decadesCertified; RunStats.certifiedDecades).
 *   - Standing inspection (OrdersState.inspection, available while a standing orderUnlock 'inspection' is in force):
 *     at each model-decade boundary of run time (floor(t × YPS / 10) rises), if on, a sector is chosen and open, and an
 *     Inspector is ready: inspects it as inspect() does, by 'inspectorate' (run.automated += 1; not a decision).
 */
export interface ChairState {
  /** C, 0–CONFIDENCE_MAX. */
  confidence: number;
  parliament: {
    /** 0 for the first (caretaker) Parliament. */
    index: number;
    /** Run time it began. */
    start: number;
    /** Run time of polling day. */
    pollAt: number;
    /** The pledges offered (ids, in content order), or null before the offer is drawn. */
    offer: string[] | null;
    /** Chosen by choosePledges (exactly `keep` ids of offer), or null. */
    chosen: string[] | null;
  };
  /** Pledges in force: binding this Parliament (chosen at the last polling day). [] in the first Parliament. */
  pledges: string[];
  inOpposition: boolean;
  lostInARow: number;
  /** This Ministry's elections won. */
  electionsWon: number;
  /** M5 (contract): elections lost this Ministry (RunSummary.ministry.lost). Absent = 0. */
  electionsLost?: number;
  /** Ready times of the Inspectors (run time; see above). */
  inspectors: number[];
  /** Sector → run time of its last inspection this Ministry (absent: never; the quiet period counts from 0). */
  inspected: Record<SectorId, number>;
  /** Sector → what the last inspection found: the concealed share and the run time (only when c > 0). */
  found: Record<SectorId, { share: number; t: number }>;
  /** M5 (contract): inspections this Ministry, and those that found concealment (RunSummary.ministry). Absent = 0. */
  inspections?: number;
  findings?: number;
  /** Sector → run time until which compensation holds (the jobs term ignores it while time < this). */
  compensated: Record<SectorId, number>;
  /** Rung id → its state (LoopholeState). */
  loopholes: Record<string, LoopholeState>;
  /** Lever id → parliament index of a carve-out won by lobbying (the lever acts one level lower that Parliament). */
  carveOuts: Record<string, number>;
  /** Lever id → a raise held up in court: the lever acts at `from` until run time `until`, then at its level. */
  litigation: Record<string, { from: number; until: number }>;
  /** M5 (contract): lever id → the level last litigated this Ministry (litigate's "not litigated at this level"). */
  litigatedAt?: Record<string, number>;
  /** Levers repealed by an incoming government, in order (for the page and the retrospective). */
  repealed: { lever: string; parliament: number }[];
  /** M5 (contract): lever ids whose answer has fallen due (a rung closed or reopened); cleared when answered. */
  due?: Record<string, true>;
  rival: RivalState;
}

/**
 * M5: the rival's run state (ChairState.rival). Rebuilt each Ministry (capital 0, maps empty) by inherit.ts.
 * THE EFFECTIVE LEVEL of a lever in a Ministry (one helper, core leverLevels.ts, used by flows, effects, side effects,
 * popularity, rung effects and views; LeverView.effectiveLevel):
 *   effectiveLevel = litigation[id] && time < litigation[id].until ? litigation[id].from
 *                  : level − (carveOuts[id] === parliament.index ? 1 : 0)
 *   floored at 0. Outside a Ministry it is the level. Mandate costs, upkeep, maxLevel and the answer's "level changed"
 *   test read the LEVEL (the player pays for what was enacted).
 */
export interface RivalState {
  /** £, his purse (RivalDef: income, purchases, the opening purse). */
  capital: number;
  /** Sector → his peak income per second this Ministry (the jobs term). */
  peakIncome: Record<SectorId, number>;
  /** Sector → true minus reported, as a share of true R (0–concealMax), per rival sector. */
  concealment: Record<SectorId, number>;
  /** Lever id → his last answer: kind, the lever level it answered, run time, its yearly cost to him (£ a model year),
   *  and the comply cost at that answer (the repeal rule reads it). */
  answers: Record<string, { kind: ResponseKind; level: number; t: number; cost: number; comply: number }>;
  /** Lever ids he is lobbying now (answer 'lobby', no carve-out yet this Parliament). */
  lobbying: Record<string, boolean>;
}

/** M5: a rung's state (ChairState.loopholes). `since` = run time of the last status change; draftUntil while drafting. */
export interface LoopholeState {
  status: LoopholeStatus;
  since: number;
  draftUntil?: number;
  /** M5 (contract): the status before drafting began ('open' or 'used'): while drafting, the rung acts as it did then. */
  before?: 'open' | 'used';
}

/** M2: who took an action or caused an event. 'default' = the rules themselves (a lapse, an overflow, an offline hold).
 *  Later: 'dispatch' (M3), 'rival' (M5), 'agent' (M7). */
export type Actor = 'player' | 'market' | 'civilService' | 'treasury' | 'default'
  /** M3: the standing dispatch order (OrdersState.dispatch) answered a dispatch with its default arm. */
  | 'dispatch'
  /** M5: the rival (his purchases, foundings, answers, evasions); Standing inspection; the incoming government (a
   *  repeal in Opposition). */
  | 'rival' | 'inspectorate' | 'opposition';

/** M2: one decade dividend offer (GameState.pendingDividends). */
export interface PendingDividend {
  sector: SectorId;
  /** The sector's decade number this run (1-based) that earned it. */
  decade: number;
  /** Two DividendDef ids; chooseDecadeDividend picks option 0 or 1. */
  options: [string, string];
  /** The pace dividendMul applying to the chosen dividend's one-off amounts (the UI shows amounts × mul). */
  mul: number;
}

/**
 * M2: event kinds (GameEvent.kind) and what fills the optional fields. `by` is set on actions (default 'player').
 *   'appAvailable'   sector, id (app)
 *   'appFounded'     sector, id (app), by ('player' | 'market' | 'default' for free and startFounded apps)
 *   'upgradeBought'  sector, id (upgrade), n (its new level), by ('player' | 'market')
 *   'stageReached'   sector, n (the new SectorDerived.stage), id (the upgrade that did it) — after its 'upgradeBought'
 *   'leverEnacted'   sector, id (lever), n (new level), by ('player' | 'civilService'); raises only
 *   'leverLapsed'    sector, id (lever), n (new level), by 'default'
 *   'budgetDrawn'    sector, id (pace id), by ('player' | 'default' for a standing cap's line)
 *   'budgetBroken'   sector
 *   'decade'         sector, n (the sector's decade number this run), id ('lean' | 'full')
 *   'dividendChosen' sector, id (dividend), n (decade), by ('player' | 'default')
 *   'clearSkies'     sector
 *   'steadyState'    sector (once per sector per run, as the 'steadySector' headline)
 *   'settled'        sector, by 'player'
 *   'unsettled'      sector, by ('player' | 'default' when the defence lapsed)
 *   'crisis'         sector, n (crisis number)
 *   'collapse' / 'exhausted'   sector (once: the step that makes the Reckoning pending)
 *   'backfire'       sector
 *   'reveal'         sector (of the card that revealed), or none (a seated institution reveals at run start: no event)
 *   'sectorOpened'   sector
 *   'ageBegins'      sector (the one whose opening began the age), id (the age id)
 *   'commonsBuilt'   id (project), n (new level), sector (the project's, if any), by ('player' | 'treasury')
 *   'charterChosen'  id (charter)
 *   'won'            (steadyAll)
 *   'reckoning'      id (the cause), sector (the cause sector, if any) — the first event of the new run
 *   'featureUnlocked' id (the FeatureId); see FeatureDef
 * M3 CHANGES: 'backfire' and 'steadyState' and 'sectorOpened' carry first: true when it is the first time in the save
 *   (meta.backfiredSectors / meta.steadySectors / meta.sectorsOpened did not have the sector before); 'stageReached'
 *   carries label = the card's `machine` ?? its name.
 * M3 kinds:
 *   'seamSunk'          sector, id (seam), n (seamsSunk after), label (seam name), by 'player'
 *   'biteBack'          sector, id (lever) — first time this run its bite reaches 0.5
 *   'dispatchArrived'   id (dispatch), sector (its sector, if any), label (cast id)
 *   'dispatchAnswered'  id (dispatch), n (arm index), sector (if any), by ('player' | 'default' | 'dispatch')
 *   'modifierEnded'     id (source dispatch), n (arm)
 *   'historyChosen'     id (History) — between runs, like 'charterChosen' (not for null)
 *   'historyCleared'    id (History); first: true the first time it is ever cleared
 *   'returnFiled'       id (return id) ; 'returnPublished' id, n (workday change in whole per cent, signed)
 *   'returnWithdrawn'   id
 *   'archiveUnlocked'   id (note), label (its subject)
 *   'ending'            id ('steadyAll') — once ever, immediately after the run's 'won'
 *   'bankUsed'          n (seconds simulated)
 * All M3 step events take the time at the END of the step, in this order within a step: the M2 order, then expiries
 * ('modifierEnded', default 'dispatchAnswered'), then a draw ('dispatchArrived'), then 'biteBack', then
 * 'historyCleared', then 'archiveUnlocked', then (if orders tick) the standing orders' events. Two thresholds crossed in
 * one step emit two events, in that order (as crises do).
 * M4 kinds:
 *   'thresholdCrossed'  sector — first crossing below θK this run (the crisis event, if one fires at the same step, comes
 *                       first, in the M2 order)
 *   'scarHealed'        sector
 *   'surveyed'          sector — the first step this run on which a survey effect is in force (the true gauge appears);
 *                       first: true and label 'reveal' for the Board's free first survey (RenewableDef.firstSurvey)
 *   'arrears'           sector ; 'arrearsCleared' sector (see SettledState, M4 arrears)
 *   'capstoned'         sector, id (the act) — emitted by reckon() on the new run, one per capstoned sector, after the
 *                       'reckoning' event (the page's cartouche); createState alone and the between-runs rebuilds emit
 *                       none (the rebuilds keep the list)
 * M4 CHANGES: 'won' and 'ending' with Content.acts are the act's (id = ActDef.ending.id on 'ending'; 'won' as before);
 *   'dispatchAnswered' for a wager arm carries label 'won' | 'lost'. M3's 'ending' id 'steadyAll' remains for content
 *   without acts.
 * M4 order within a step: the M3 order up to 'archiveUnlocked', then 'thresholdCrossed', 'scarHealed', 'surveyed',
 *   'arrears' / 'arrearsCleared' (each in sectorOrder), then (if orders tick) the standing orders' events.
 * M5 kinds (each with the headline of the same name where HeadlineKey has one):
 *   'officeTaken'       — takeOffice (between runs; printed into the rebuilt Ministry with the 'acquisition' and
 *                         'officeTaken' headlines, in that order)
 *   'electionCalled'    n (parliament index) — the offer is drawn
 *   'electionWon' / 'electionLost'   n (parliament index), label (Confidence at polling, integer, as a string)
 *   'leverRepealed'     sector, id (lever), n (its new level), by 'opposition'
 *   'ministryDefeated'  — the second loss in a row (the Reckoning 'defeated' is then pending)
 *   'inspected'         sector, n (round(c × 100) found; 0 when clean), by ('player' | 'inspectorate')
 *   'concealmentFound'  sector, n (as 'inspected') — after its 'inspected'
 *   'rivalAnswered'     sector, id (lever), label (the ResponseKind) — when the kind changed (a first answer counts)
 *   'loopholeOpened' / 'loopholeUsed' / 'loopholeClosed'   sector, id (rung), label (the lever id); 'loopholeUsed' by
 *                       'rival'
 *   'litigated'         sector, id (lever), n (the level held up), by 'rival'
 *   'carveOut'          sector, id (lever), by 'rival'
 *   'compensated'       sector, by 'player'
 *   'treaty'            n (meta.treaties after) — between runs, in the rebuilt run's list
 *   'playbookLearnt'    id (playbook) — after 'treaty'
 *   'articleBought'     id (Article) — between runs
 *   M5 CHANGES: 'upgradeBought', 'appFounded' and 'stageReached' may carry by 'rival'; a loophole's exempt app is
 *   founded by 'rival'; 'reckoning' may carry id 'defeated'.
 * M5 order within a step: the M4 order, then 'electionCalled', 'electionWon' / 'electionLost', 'leverRepealed',
 *   'ministryDefeated', 'loopholeClosed' (draft completions) and the 'loopholeOpened' it causes, then (if orders tick)
 *   the rival's decision ('upgradeBought' / 'appFounded' / 'stageReached' by 'rival', 'rivalAnswered', 'loopholeUsed',
 *   'litigated', 'carveOut'), then Standing inspection ('inspected', 'concealmentFound'), then the player's standing
 *   orders' events. Actions emit theirs at once; a laddered lever's first raise to ≥ 1 in a Ministry (setLever, or the
 *   Civil Service) opens its first rung at once ('loopholeOpened' after 'leverEnacted').
 */
export type EventKind =
  | 'appAvailable' | 'appFounded' | 'upgradeBought' | 'stageReached' | 'leverEnacted' | 'leverLapsed'
  | 'budgetDrawn' | 'budgetBroken' | 'decade' | 'dividendChosen' | 'clearSkies' | 'steadyState' | 'settled' | 'unsettled'
  | 'crisis' | 'collapse' | 'exhausted' | 'backfire' | 'reveal' | 'sectorOpened' | 'ageBegins' | 'commonsBuilt'
  | 'charterChosen' | 'won' | 'reckoning'
  /* the unfolding */
  | 'featureUnlocked'
  /* --- M3 --- */
  | 'seamSunk' | 'biteBack' | 'dispatchArrived' | 'dispatchAnswered' | 'modifierEnded' | 'historyChosen'
  | 'historyCleared' | 'returnFiled' | 'returnPublished' | 'returnWithdrawn' | 'archiveUnlocked' | 'ending' | 'bankUsed'
  /* --- M4 --- */
  | 'thresholdCrossed' | 'scarHealed' | 'surveyed' | 'arrears' | 'arrearsCleared' | 'capstoned'
  /* --- M5 --- */
  | 'officeTaken' | 'electionCalled' | 'electionWon' | 'electionLost' | 'leverRepealed' | 'ministryDefeated'
  | 'inspected' | 'concealmentFound' | 'rivalAnswered' | 'loopholeOpened' | 'loopholeUsed' | 'loopholeClosed'
  | 'litigated' | 'carveOut' | 'compensated' | 'treaty' | 'playbookLearnt' | 'articleBought';

/** M2: one event (GameState.events). Plain JSON. */
export interface GameEvent {
  seq: number;
  kind: EventKind;
  /** Run time (seconds) when it happened (for events inside a step: the time at the END of that step). */
  time: number;
  /** Calendar year then (integer). */
  year: number;
  sector?: SectorId;
  id?: string;
  n?: number;
  by?: Actor;
  /** M3: true when this is the first time in the save (see EventKind). Absent otherwise. */
  first?: boolean;
  /** M3: a display name the consumer would otherwise have to look up (a machine, a seam, a cast id; see EventKind). */
  label?: string;
}

/**
 * M2: the "While you were away" ledger of one fastForward call.
 */
export interface OfflineReport {
  /** Seconds asked for (after clamping to ≥ 0) and seconds actually simulated (≤ the effective cap). */
  requested: number;
  simulated: number;
  /** Why it stopped short of `requested`: a hold (offline.holdBefore), the cap, a Reckoning that was ALREADY pending
   *  when it began ('pending'), or null if it ran the whole request. */
  heldBy: 'crisis' | 'collapse' | 'exhausted' | 'cap' | 'pending' | null
    /** M4: it stopped one step before a capstoned sector would go into arrears (holdBefore 'crisis' or 'collapse';
     *  heldSector names it). Banked like 'crisis' (GlobalParams.offline.bankRate). */
    | 'arrears'
    /** M5: it stopped one step before a polling day the Ministry would LOSE (holdBefore 'crisis' or 'collapse'): a
     *  player is never voted out while away. Banked like 'crisis'. A polling day that would be won is crossed. */
    | 'election';
  /** The sector whose crisis, collapse or exhaustion was held off (heldBy 'crisis' | 'collapse' | 'exhausted'; M4: or
   *  'arrears'). */
  heldSector?: SectorId;
  /** Run time when the catch-up began and ended. */
  from: number;
  to: number;
  /** Changes over the catch-up (end − start). */
  capital: number;
  mandate: number;
  population: number;
  /** Decades completed, dividends offered (added to pendingDividends), crises fired (non-zero only with holdBefore
   *  'collapse' or null). */
  decades: number;
  dividends: number;
  crises: number;
  /** M2 (offline fix): decades whose choice was not offered because PENDING_DIVIDENDS_MAX offers were already waiting
   *  (see GameState.pendingDividends). Written by every fastForward; absent on reports saved before the fix (= 0). */
  dividendsForgone?: number;
  /**
   * M2 (offline fix): the change in Derived.hindsightIfReckonNow over the catch-up (end − start, after withholding;
   * may be negative), and the rate it was entered at (GlobalParams.offline.hindsightRate, default 1). Written by every
   * fastForward; absent on reports saved before the fix. A ledger can say: Hindsight +hindsight, at hindsightRate.
   */
  hindsight?: number;
  hindsightRate?: number;
  /** Purchases and foundings the standing orders made (counts, by actor), and Commons levels Treasury rules bought. */
  marketBuys: number;
  civilServiceRaises: number;
  treasuryBuys: number;
  /** Lever ids that lapsed (one entry per level lost), sectors opened, sectors unsettled. */
  lapsed: string[];
  opened: SectorId[];
  unsettled: SectorId[];
  /**
   * Per sector with a budget line at the end: 'held' = it had a line at the start and its decade streak never reset
   * during the catch-up; 'broken' = the streak reset at least once; 'drawn' = the line was drawn during the catch-up;
   * 'settled' = settled at the end (and not unsettled during the catch-up).
   */
  lines: Record<SectorId, 'held' | 'broken' | 'drawn' | 'settled'>;
  /** meta.eventSeq before and after: the events (seq in (fromSeq, toSeq]) the catch-up emitted, as far as they are
   *  still in GameState.events. */
  fromSeq: number;
  toSeq: number;
  /* --- M3 (absent on reports saved before M3 = 0) --- */
  /** M3: pending dispatches resolved by default during the catch-up (no new ones are drawn while away). */
  dispatchesDefaulted?: number;
  /** M3: seconds added to meta.bankedSeconds by this call (see GlobalParams.offline.bankRate). */
  banked?: number;
}

/**
 * M1: a sector's budget line. budgetR(t) = max(floor × r0, r0 × (1 − d)^((min(t, heldAt) − since) × YEARS_PER_SECOND / 10)),
 * d = the sector's decline per decade, floor = steady.budgetFloor (default 0), heldAt absent = ∞.
 * Drawn (when absent) by: drawBudget(); the player raising any lever of the sector (setLever; M1 balance: any raise,
 * not only from level 0, so Tightening a standing cap draws its line); or an active cap lever on the first step with
 * demand once the sector has been open steady.standingDrawYears. drawBudget() on a sector that has one REDRAWS it at
 * the current R and resets the sector's streak (steadyYears 0); decades already earned are kept.
 * M2 CHANGE: d = the declinePerDecade of the line's pace (SteadyParams.paces). Every way of drawing records w0, p0 and
 * the pace; a redraw also resets clearYears and windowLean and starts a new line (clearAt and heldAt absent).
 * Lines drawn by a lever raise or a standing cap take the sector's default (first) pace.
 */
export interface BudgetState {
  /** R (per second) when drawn. */
  r0: number;
  /** Run time (seconds) when drawn. */
  since: number;
  /** Calendar year when drawn (for the ledger). */
  drawnYear: number;
  /**
   * M1 balance: run time at which the line stopped declining because the sector reached Steady State on it (its streak
   * crossed STEADY_STATE_YEARS). Absent while the line still declines. A redraw starts a new, declining line.
   * M2 CHANGE: the Steady streak is SectorState.clearYears (clear skies as well as decoupling).
   */
  heldAt?: number;
  /* --- M2 --- */
  /** Derived.wellbeing when drawn (the "line's own day"; see SteadyParams.decadeWellbeing). */
  w0: number;
  /** The sector's pressure when drawn (the base of the clear level; see SteadyParams.clearBelow). */
  p0: number;
  /** Id of the pace it was drawn at (see SteadyParams.paces). */
  pace: string;
  /** Run time at which the sector first became clear on this line (emits 'clearSkies'); absent until then. */
  clearAt?: number;
  /* --- M4 --- */
  /**
   * M4 (The Survey): the account the line is drawn on: 'own' (the chimney: R, as before) or 'full' (SectorDerived.fullR).
   * Lines drawn (by any means) while feature 'estimates' is on are 'full'; earlier lines keep 'own' (absent = 'own'), and
   * a redraw takes the account of the moment. For a 'full' line r0 is fullR when drawn, and every test that compares R
   * with budgetR uses fullR: withinBudget (and so decoupling and the decades), the Steady streak's within-budget part
   * (sinkHeld), 'budgetHeadroom', the Civil Service's tests, setLever's over-the-line redraw, and caps' capR. A cap or
   * quota on a 'full' line still prices the sector's OWN R (it cannot tax Iron's coke): the permit is solved so that
   * own R ≤ capR − received (received = fullR − R + handedOn, SectorDerived.embodied summed; if that target is ≤ 0 the
   * squeeze limit applies). Clear skies and the sink line are unchanged (they are about the local sky). The page labels
   * each line with its account. HistorySample.budget stays budgetR / baseR.
   */
  account?: 'own' | 'full';
}

/**
 * M2: a settled sector (SectorState.settled). Settling freezes the sector at the values recorded here: it is not solved
 * while settled, so it costs nothing per step and cannot crisis, collapse or exhaust.
 *   Flows while settled (what SectorDerived and the run see): D, R, ps, pPre, income and the per-app demands are these
 *     frozen values; levy revenue 0; substitutedShare, permit and duty parts 0; rebound null; shadowR = promisedR = R;
 *     frontierFold = R / baseR. Pressure stays at P (not stepped); the reserve stays where it was (not drained):
 *     a deliberate simplification, a settled Industry is drawn at a rate the sink absorbs. resourceUsed still grows
 *     by R × dt and serviceDelivered by D × dt × YEARS_PER_SECOND (Hindsight's intensity sees a settled burn).
 *   Wellbeing share while settled (population moves on): wellbeingWeight × defect × ln(1 + D / (N × wellbeingScale))
 *     − pressureWellbeingCost × min(1, P / collapseAt), with today's N.
 *   As a spill source it spills from its frozen ps (against its basePs); as a drawsOn source it draws frozen D.
 *   Excess (the economy and the Industries around it still grow into it):
 *     excess = max(0, (N × spillMul) / (N0 × spillMul0) − 1) + max(0, extraD − extraD0) / max(D, 1e-12)
 *     where N, spillMul and extraD are today's (spillMul and extraD computed for the sector exactly as if it were
 *     solved: spill from earlier sectors, drawsOn and Commons intensity into it).
 *   Defence: settle.upkeepPerSpill × max(0, excess − (settle.freeExcess ?? 0.05)) Mandate per second, added to lever
 *     upkeep (Derived.mandatePerSec is net of it; SectorDerived.settleDefence reports it).
 *   When Mandate cannot pay: the lapse rule (LeverLevelDef.mandateUpkeep) first drops lever levels as in M1; only once
 *     no lever with upkeep is left does it unsettle the settled sector with the largest defence (ties: sectorOrder),
 *     and repeats until upkeep is covered. An unsettled sector resumes as after ModelApi.unsettle (by 'default').
 * M4: a capstoned sector (SectorState.capstoned) holds the CapstoneRecord's SettledState with D, R, appD and income
 *   scaled per head each step (see CapstoneRecord); everything above applies to it with those values, except:
 *   - it uses no room (Derived.ending.room, GlobalParams.settleMax) and pays no settleHold (it is not among the n);
 *   - ARREARS (M4 CHANGE to the lapse rule's last step, for capstoned sectors only): when the settled sector the lapse
 *     rule would unsettle (largest defence; ties: sectorOrder) is capstoned, it goes INTO ARREARS instead
 *     (SectorState.arrears = true; 'arrears' event and headline) and the rule moves on to the next. In arrears:
 *       · its defence is not charged;
 *       · its R and D are the scaled settled values × (1 + max(0, excess − freeExcess)) (the excess served, undefended);
 *         income and appD scale with D;
 *       · its pressure is stepped again from P with that R (P += R × intensity × dt; P ×= exp(−absorption × dt)); for a
 *         'depletion' sector the stock is stepped instead (RenewableDef's step with R_home = that R, no foreign catch)
 *         and P derived from it; its wellbeing share uses that pressure;
 *       · it cannot end the run: crises at its crisisAt fire headlines and Mandate as usual, but its pressure is held at
 *         ARREARS_COLLAPSE_HOLD × collapseAt (a capstone never collapses or exhausts the run);
 *       · it leaves arrears on the first step at which Mandate would cover its defence for that step (Mandate ≥ the
 *         defence × dt after every other upkeep): arrears = false, 'arrearsCleared' event; its pressure then decays back
 *         by absorption (not reset; a depletion stock regrows by G − the scaled settled R × (1 − circularity)) until it
 *         is back at the recorded P (resp. the recorded stock), where it is frozen again.
 *   - ModelApi.unsettle refuses it (same reference).
 */
export interface SettledState {
  /** Run time and calendar year (integer) when settled. */
  since: number;
  sinceYear: number;
  D: number;
  R: number;
  ps: number;
  pPre: number;
  income: number;
  /** Pressure (frozen). */
  P: number;
  eta: number;
  /** Defect factor at settlement (1 except flow sectors with unreviewed work). */
  defect: number;
  /** Population, spill multiplier and extra (drawsOn + Commons) demand at settlement: the bases of `excess`. */
  N0: number;
  spillMul0: number;
  extraD0: number;
  /** Per application (founded ones): demand and adoption at settlement (AppDerived reports these while settled). */
  appD: Record<string, number>;
  appAdoption: Record<string, number>;
  /* --- M3 (absent on settlements made before M3: the views report null while settled) --- */
  /** M3: the load curve at settlement (SectorDerived.load reports it frozen). */
  load?: { factor: number; hours: number[]; capCostEff: number };
  /** M3: travel at settlement (SectorDerived.travel reports it frozen; sprawl keeps decaying only once unsettled). */
  travel?: { speed: number; hoursPerHead: number; roads: number; sprawl: number };
  /** M3: the seen price per founded application at settlement (AppDerived.priceSeen while settled). */
  appPriceSeen?: Record<string, number>;
}

/**
 * M4: one capstoned sector's record (MetaState.world.capstone[s]), taken from its SettledState at the step the act's
 * ending was reached. The per-head service is what persists: at a run's population N the capstone serves
 *   k = min(1, N / N0);  D = D0 × k;  R = R0 × k;  appD[a] = appD0[a] × k;  income = income0 × k × incomeShare
 * (incomeShare = ActDef.capstone.incomeShare ?? CAPSTONE_INCOME_SHARE), and once N > N0 the ordinary settled excess rule
 * applies (SettledState: excess, defence, freeExcess). P, ps, pPre, eta, defect, appAdoption and the M3 snapshots
 * (load, travel, appPriceSeen) are taken as recorded. Why per head: a fresh run starts at population 1, and the
 * ending's frozen totals would give the first minute the ending's whole service.
 * Building (the carry-over step, inherit.ts, used by reckon and by createState(content, meta)): every sector with a
 * record opens at the run's first step, settled = record.settled with since = 0 and sinceYear = the run's start year
 * (both rewritten each run), capstoned = true, pressure = settled.P, its reserve as a fresh run builds it (a renewable's
 * by startScarred), its applications founded where appAdoption has them, levers at 0; settledBefore = true (the
 * settle dividend's one-offs never fire for a capstone; its standing effects are in force).
 */
export interface CapstoneRecord {
  /** ActDef.id. */
  act: string;
  /** Calendar year the ending was reached (integer; the cartouche: "Settled 1911"). */
  year: number;
  /** As recorded; since and sinceYear are rewritten each run to the run's start. */
  settled: SettledState;
}

/** M1 CHANGE (was EraState). */
export interface SectorState {
  open: boolean;
  /** Seconds since this sector opened (0 if closed). */
  openFor: number;
  /** Current efficiency including upgrades, knowhow and autoEta. */
  eta: number;
  /**
   * η at the moment baseR/baseD were recorded (run-start know-how included), so every run starts at etaFold 1.
   * The shadow solve freezes η here. 0 until the baseline is recorded.
   */
  etaAtBase: number;
  /** 'stock': remaining reserve. 'flow': current capacity. */
  reserve: number;
  /** Total reserve ever available this run (Q0 + additions) — the denominator for the gauge and the price. */
  reserveMax: number;
  pressure: number;
  /** Number of crisisAt thresholds already fired. */
  crisesFired: number;
  /** application id → state */
  apps: Record<string, AppState>;
  /** R and D on the first step the sector has demand (normally the moment it opens): the baseline for rFold and frontierFold. */
  baseR: number;
  baseD: number;
  /** p_s at the baseline (for spill). */
  basePs: number;
  /** Exponential moving average of R, time constant 60 s (cosmetic trend arrow only since M1). */
  smoothR: number;
  /** d(smoothR)/dt as a fraction of smoothR per model year. Negative = falling. Cosmetic since M1. */
  trendR: number;
  peakR: number;
  /** M1 CHANGE: the current decoupling streak in model years (see SectorDerived.decoupling); 0 when not decoupling. */
  steadyYears: number;
  /** The sector's direct rebound has exceeded 100% at some point this run. */
  backfired: boolean;
  /** M1: the budget line, or null if none drawn this run. */
  budget: BudgetState | null;
  /** M1: Σ D × dt × YEARS_PER_SECOND this run — service delivered in "unit·years" (e.g. hp·years). */
  serviceDelivered: number;
  /** M1: calendar year at which each decade within budget was completed this run (the decades ledger). */
  decadesWithin: number[];
  /* --- M2 --- */
  /** M2: parallel to decadesWithin: true where that decade was lean (some step of it had W < wellbeingTarget). */
  decadesLean: boolean[];
  /** M2: the current decade window has had a step with W < wellbeingTarget (reset at each decade and streak reset). */
  windowLean: boolean;
  /**
   * M2: the Steady streak in model years: consecutive steps with the sector within budget, W ≥ wellbeingTarget and
   * clear (SectorDerived.sinkHeld). Steady State is earned when it crosses STEADY_STATE_YEARS. 0 when not held. Held
   * (not advanced, not reset) while settled.
   */
  clearYears: number;
  /** M2: the settlement, or null. */
  settled: SettledState | null;
  /** M2: the sector has been settled at least once this run (its settle one-offs have fired). */
  settledBefore: boolean;
  /** M2: dividend ids chosen this run from this sector's decades (standing effects once per entry). */
  dividends: string[];
  /** M2: highest pressure this run (RunSummary.peakPressure = peakPressure / collapseAt). */
  peakPressure: number;
  /* --- M3 --- */
  /** M3: seams sunk this run (SectorDef.seams[0 … seamsSunk − 1]); 0 without seams. */
  seamsSunk: number;
  /* --- M4 (all optional: absent = false / none, so M3 states and hand-built test states stay valid) --- */
  /**
   * M4: this sector is capstoned this run (opened settled at run start from meta.world.capstone; see CapstoneRecord).
   * A capstoned sector: is open from the run's first step; SectorState.settled is the record's SettledState, scaled
   * each step; counts as settled for every rule (the ending, Cond 'settled' and 'sectorsSettled', excess, defence, the
   * lapse rule's ordering) EXCEPT that it uses no room (Derived.ending.room, GlobalParams.settleMax), pays no settleHold,
   * cannot be unsettled by ModelApi.unsettle (refused: same reference), and its levers stay hidden. It never leaves the
   * settled state in the run; under an unpaid defence it goes into arrears (SettledState, M4).
   */
  capstoned?: boolean;
  /** M4: a capstoned sector whose defence could not be paid (SettledState, M4 arrears). */
  arrears?: boolean;
  /** M4: Q has crossed below θK in this run (renewable only; RenewableDef). */
  crossed?: boolean;
  /** M4: the lowest Q / K this run (renewable only; updated every step it is stepped; RunSummary.sectors[s].minStock). */
  minStock?: number;
  /**
   * M4: the last step on which a survey effect was in force on this sector this run: the sink line it showed (sinkR,
   * or null if no line was drawn then), the run time and the calendar year (integer). A held 'quota' acts on this sinkR
   * while unsurveyed; the page letters the blank gauge "No survey since {year}". Absent: never surveyed this run (the
   * first step with a survey emits 'surveyed').
   */
  lastSurvey?: { sinkR: number | null; t: number; year: number };
  /** M4: the 'foreignFleets' headline has been printed this run (ForeignDef.announceAt). */
  foreignAnnounced?: boolean;
  /** M4: on a feed SOURCE, the peak rAdded into each target this run (SectorDerived.feeds), sampled at each
   *  HistorySample (every 5 s of run time) rather than every step: RunSummary.sectors[s].feedR. */
  feedPeak?: Record<SectorId, number>;
  /* --- M5 (optional: absent = none / all false) --- */
  /** M5: parallel to decadesWithin: true where that decade was certified (recorded in office with an inspection of the
   *  sector inside its ten-model-year window; ChairState). Absent = all false. Display and Precedent only. */
  decadesCertified?: boolean[];
  /** M5: hiddenFlow sectors: the return share r when the baseline was recorded (with etaAtBase); the shadow solve
   *  freezes r here. Absent: r at its base (returnShare × the run-start effects). */
  returnAtBase?: number;
}

export interface AppState {
  available: boolean;
  founded: boolean;
  /** Current saturation multiplier from sufficiency levers (starts 1). */
  satMul: number;
  /** Highest demand reached (for lock-in). */
  peakD: number;
  /** M2: highest AppDerived.adoption this run (0–1), updated every step (for the run summary's picture). */
  peakAdoption: number;
  /** M5: a founded application whose ApplicationDef.when fails: its effective saturation is capped here (the value on
   *  the last step `when` held). Absent while `when` holds (or the app has none). */
  frozenSat?: number;
}

export interface LeverState {
  /** May exceed levels.length when the lever has `repeat`. */
  level: number;
  /** Duty: p_ref, the price before duty when the lever first went from 0 to > 0 (0 until the sector has demand).
   *  M1 CHANGE: unused by caps (they follow the budget line). */
  ref: number;
  /** M1: chosen recycle option; absent = the lever's default (recycle[0] ?? 'treasury'). */
  recycle?: LeverRecycle;
  /* --- M3 --- */
  /** M3: side-effect strength 0–1 (LeverDef.sideEffects). Absent = 0 (levers without side effects need not carry it). */
  bite?: number;
  /** M3: the bite has reached 0.5 this run ('biteBack' fired). Absent = false. */
  bitten?: boolean;
  /** M4 (amend): LeverDef.when has held this run (written by the step, checked about once a real second). Absent = false. */
  seen?: boolean;
  /* --- M5 (absent = never this run) --- */
  /** M5: run time the lever last rose from 0 (LeverDef.popularity's clock); removed when it returns to 0. */
  since?: number;
  /** M5: run time of the lever's last raise, any level (the rival's litigation window). */
  raisedAt?: number;
  /* M5: a 'charge' (and a cap or quota with basis 'applied') keeps its fixed reference in `ref` (LeverKind 'charge',
   * LeverDef.basis), snapshotted on the raise from 0 as a duty's is. */
}

export interface NewsItem {
  time: number;
  /** Calendar year (Derived.year) at the time, as an integer. */
  year: number;
  key: HeadlineKey;
  text: string;
  /** M1 CHANGE: was `era`. */
  sector?: SectorId;
}

export interface HistorySample {
  time: number;
  /** M1 CHANGE (was `eras`): sector id → [eta / etaAtBase, R / baseR]. Absent while the sector is closed. */
  sectors: Record<SectorId, [number, number]>;
  /** M1: sector id → budgetR / baseR at the sample time, for sectors with a budget. */
  budget?: Record<SectorId, number>;
  /** M2: sector id → SectorDerived.sinkR / baseR at the sample time, for sectors with a non-null sinkR (the sink line).
   *  M4: a depletion sector's is recorded only while it is surveyed (its sinkR reads null otherwise). */
  sink?: Record<SectorId, number>;
  wellbeing: number;
  /** M5: ChairState.confidence at the sample time, in a Ministry (the Confidence sparkline); absent outside office. */
  confidence?: number;
  /** M5: sector id → SectorDerived.reportedR / baseR for rival sectors while feature 'inspection' is on (the "as
   *  reported" line beside the true one); absent otherwise. */
  reported?: Record<SectorId, number>;
}

export interface RunStats {
  peakWellbeing: number;
  /** M1 CHANGE: model years during which at least one sector was decoupling (informational). */
  decoupledYears: number;
  /** Sum of all resource used this run, per sector. */
  resourceUsed: Record<SectorId, number>;
  clicks: number;
  /** Sectors that reached Steady State during this run. */
  steadySectors: Record<SectorId, boolean>;
  /** M1: ∫ max(0, W − subsistence) d(model years). */
  wellbeingYears: number;
  /** M1: model years with W ≥ wellbeingTarget (ramps the unburnt Hindsight term). */
  yearsAtTarget: number;
  /** M1: decades within budget completed this run, all sectors. */
  budgetDecades: number;
  /** M1: sectors whose first-ever backfire (not in meta.backfiredSectors before) happened this run. */
  firstBackfires: Record<SectorId, boolean>;
  /* --- M2 --- */
  /** M2: decades within budget this run that were lean (included in budgetDecades). */
  leanDecades: number;
  /**
   * M2: successful PLAYER actions in the run: buyUpgrade, foundApp, setLever, setLeverRecycle, drawBudget,
   * chooseDecadeDividend, settle, unsettle, buyCommons, and setOrders while not Derived.freshRun. One per call that
   * changes the state (whatever it changes). Not counted: clicks (run.clicks), refused actions, anything a standing
   * order does (run.automated), and the between-runs actions (Know-how, Institutions, loadout, Charter, respec).
   * M3: also sinkSeam and answerDispatch (by the player). Not counted: fileReturn, withdrawReturn, useBank,
   * chooseHistory, and default or standing-order answers.
   * M5: also inspect, amend, choosePledges, campaign and compensate. Not counted: takeOffice, treaty, buyArticle
   * (between runs), anything the rival or Standing inspection does.
   */
  decisions: number;
  /** M2: decisions per model decade of this run: index k counts decisions taken at run time t with
   *  floor(t × YEARS_PER_SECOND / 10) = k (extended with zeros as needed; past DECISION_DECADES_MAX − 1, the last). */
  decisionsByDecade: number[];
  /** M2: actions standing orders took (Market purchases and foundings, Civil Service raises, Treasury purchases). */
  automated: number;
  /** M2: automated actions per model decade, indexed as decisionsByDecade. */
  automatedByDecade: number[];
  /** M2: the first OPENING_MAX upgrade purchases and foundings of the run, by anyone, in order (see OpeningAction). */
  opening: OpeningAction[];
  /** M2: run time of the first budget line drawn by a player action (drawBudget, or a lever raise that drew one); null
   *  until then. A standing cap's line does not count. */
  firstBudgetAt: number | null;
  /**
   * M2 (offline fix): Hindsight withheld from this run's Reckoning for time away (unrounded; absent = 0). Only
   * fastForward writes it (see GlobalParams.offline.hindsightRate); a Reckoning starts the next run without it. It may
   * dip below 0 after a catch-up in which Hindsight fell (a reserve burnt); HindsightTerms.withheld clamps at 0. No
   * save-version change: an older save simply has no time away recorded; deserialize keeps the field only when finite.
   */
  hindsightWithheld?: number;
  /** M4 (finish): Σ of the hindsightShare one-offs answered this run (EffectDef 'hindsightShare'); absent = 0. Reset at a
   *  Reckoning with the rest of RunStats. deserialize keeps it only when finite. */
  letterShare?: number;
  /* --- M3 --- */
  /** M3: dispatches the player answered this run (each also counts in decisions). */
  dispatchesAnswered: number;
  /** M3: dispatches resolved by default or by the standing dispatch order this run. */
  dispatchesDefaulted: number;
  /* --- M3 (finish): run-scoped flags that used to be read from the last 40 news items (and so could repeat) --- */
  /** M3 (finish): the History in force has been cleared in this run (its goal is checked once a run; Derived.history
   *  .cleared and RunSummary.historyCleared read this). Absent = false. A save without it is migrated from its news
   *  and events (a 'history' item, or a 'historyCleared' event since the last 'reckoning'). */
  historyCleared?: boolean;
  /** M3 (finish): a household return has been published in this run (one publication a run; see ModelApi.fileReturn).
   *  Absent = false. A save without it is migrated from its news (a 'return' item). */
  returnPublished?: boolean;
  /* --- M5 --- */
  /** M5: decades certified this run, all sectors (SectorState.decadesCertified); absent = 0. Feeds office.record. */
  certifiedDecades?: number;
}

/** M2: one recorded opening action (for M5's rival profile). `t` is run time in seconds (game time, not wall time). */
export interface OpeningAction {
  t: number;
  kind: 'upgrade' | 'found';
  /** Upgrade or application id. */
  id: string;
  by: Actor;
}

/** M2: a run's opening, as kept in MetaState. */
export interface OpeningRecord {
  actions: OpeningAction[];
  firstBudgetAt: number | null;
  /** Length of that run (seconds). */
  seconds: number;
  /** The Charter in force in that run, if any. */
  charter?: string;
}

/** M2: which standing order. */
export type OrderId = 'market' | 'civilService' | 'treasury'
  /** M3: the standing dispatch order (default answers for chosen cast members). */
  | 'dispatch'
  /** M5: Standing inspection (ChairState, the inspection rules); available while a standing orderUnlock 'inspection'
   *  is in force; OrdersView.kind 'closing'. */
  | 'inspection';

/**
 * M2: standing orders, automation as policy (MetaState.orders: they persist across Reckonings as the player's settings;
 * a fresh meta has the default below). They run inside the step (so tick and fastForward run them alike) at ORDER
 * TICKS: a step from t0 to t1 is an order tick when floor(t1 × YEARS_PER_SECOND / intervalYears) >
 * floor(t0 × YEARS_PER_SECOND / intervalYears) (intervalYears = GlobalParams.orders.intervalYears ?? 1). They act on
 * the state the step has just produced, after everything else in the step, in this order: Market, Civil Service,
 * Treasury rules. They never run in projections (UpgradeView), while a Reckoning is pending, or while the run is fresh.
 * When no order is active the step pays one comparison. Results with different step lengths (tick's 1 s against
 * fastForward's 5 s) differ only as much as the step itself does: same rules, same boundaries.
 * An order is ACTIVE when available, `on`, and (Market) its sector switch is on.
 *   Available: Market — meta.reckonings ≥ GlobalParams.orders.marketFromReckoning (default 1) or a standing
 *   orderUnlock 'market'; Civil Service and Treasury rules — a standing orderUnlock effect for them is in force.
 *
 * THE MARKET (default on). At each order tick, for each open, unsettled sector in sectorOrder whose switch is on
 * (sectors[s] !== false), it takes AT MOST ONE action, the candidate with the shortest payback:
 *   candidates: (a) every available, unfounded application with foundCost ≤ capital; (b) every upgrade of the sector
 *     with kind 'efficiency' or 'capital' that is visible, not maxed, not excluded, has NO `excludes` (forks are the
 *     player's), and costs ≤ capital. Never 'research' or 'prospect' cards; never levers, budgets or Commons.
 *   payback(a) = cost(a) / gain(a), infinite if the gain is ≤ 0, where (M2 BALANCE) the gain is what the action pays
 *     per second as a mill owner reckons it: the running cost it saves at today's output plus any rise in income,
 *       gain(a) = Σ over open unsettled sectors of D_now × max(0, pPre_now − pPre_after) + max(0, income_after − income_now)
 *     (pPre = resource price / η + capital cost per unit of service, before levies; income = Derived.incomePerSec),
 *     each "after" computed by solving the state with that one action applied (no time passes). An engine is sold on
 *     the coal it saves (Boulton & Watt's royalty was a third of it); an application on the income it brings. So the
 *     Market buys efficiency even while demand is price-inelastic and the card lowers income: the saving is passed on
 *     in the price, and the use grows to meet it.
 *   it acts if the shortest payback ≤ paybackMax; ties: applications before upgrades, then content order.
 *   The action is the same state change as foundApp / buyUpgrade (capital charged, one-offs, headlines), recorded with
 *   by 'market': in run.opening (if room), events ('appFounded' / 'upgradeBought', and 'stageReached'), run.automated
 *   and automatedByDecade; never in run.decisions. Later sectors in the same tick see the capital it spent.
 * THE CIVIL SERVICE (default off; levers chosen per sector). At each order tick, for each open, unsettled sector in
 *   sectorOrder with a budget line and a non-empty `levers` list: if R > budgetR × (1 + BUDGET_TOLERANCE), it raises
 *   ONE level of the listed lever (of that sector, visible, below maxLevel) with the lowest next-level Mandate cost that
 *   Mandate covers (ties: list order), as setLever would ('leverEnacted' by 'civilService'); else, if
 *   W < SectorDerived.decadeWellbeing and R ≤ 0.9 × budgetR, it lowers ONE level of the listed lever with the highest
 *   net upkeep (ties: list order). Each counts once in run.automated.
 * TREASURY RULES (default off). At each order tick, if the Commons are open: the first project in `projects` that a
 *   buyCommons call would accept with capital reduced by keepSeconds × Derived.incomePerSec (the fund is not reduced)
 *   gets one level ('commonsBuilt' by 'treasury', run.automated += 1).
 * Default OrdersState: { market: { on: true, paybackMax: GlobalParams.orders.marketPaybackMax ?? 120, sectors: {} },
 *   civilService: { on: false, levers: {} }, treasury: { on: false, keepSeconds: 60, projects: [] } }.
 * M3: THE DISPATCH ORDER (default off; available while a standing orderUnlock 'dispatch' is in force). Not an order
 *   tick rule: when a dispatch arrives from a cast member with cast[id] === true and the order is active, it is answered
 *   at once with its default arm, by 'dispatch' (see GameState.dispatch). Default dispatch: { on: false, cast: {} }.
 * M3: the Market skips forbidden candidates (EffectDef 'forbid') and, when the History in force suspends 'market', is
 *   unavailable. At each order tick it writes GameState.orderLog[s] for every sector it considered: 'bought' (id = the
 *   upgrade or application), 'none' (no eligible candidate), 'cash' (eligible candidates, none affordable), 'payback'
 *   (affordable ones, best payback > paybackMax; payback = the best, seconds).
 */
export interface OrdersState {
  market: {
    on: boolean;
    /** Seconds. */
    paybackMax: number;
    /** Per-sector switch; a missing key means ON (so a newly opened sector starts with the Market on). */
    sectors: Record<SectorId, boolean>;
  };
  civilService: {
    on: boolean;
    /** Lever ids the Civil Service may move, per sector (ids of other sectors' levers are ignored). */
    levers: Record<SectorId, string[]>;
  };
  treasury: {
    on: boolean;
    /** Capital kept back, in seconds of income. */
    keepSeconds: number;
    /** Commons project ids in priority order. */
    projects: string[];
  };
  /** M3: cast id → answer that cast member's dispatches with the default arm (missing = no). */
  dispatch: { on: boolean; cast: Record<string, boolean> };
  /** M5: Standing inspection: on, and the sector it inspects each model decade (null: none chosen). Absent = { on:
   *  false, sector: null }. Persists across Reckonings with the other orders.
   *  M5 CHANGE to the Market: in a Ministry no sector is the player's to buy in (chair sectors are the rival's, the
   *  capstone is settled), so the player's Market takes no action; its settings are kept; OrdersView.market.rival. */
  inspection?: { on: boolean; sector: SectorId | null };
}

/** M2: a partial update for ModelApi.setOrders: given fields replace the stored ones (maps and lists are replaced whole,
 *  except market.sectors and civilService.levers, which are merged key by key). */
export interface OrdersPatch {
  market?: { on?: boolean; paybackMax?: number; sectors?: Record<SectorId, boolean> };
  civilService?: { on?: boolean; levers?: Record<SectorId, string[]> };
  treasury?: { on?: boolean; keepSeconds?: number; projects?: string[] };
  /** M3: dispatch.cast is merged key by key; unknown cast ids dropped. */
  dispatch?: { on?: boolean; cast?: Record<string, boolean> };
  /** M5: an unknown sector id is dropped (stored as null). */
  inspection?: { on?: boolean; sector?: SectorId | null };
}

export interface MetaState {
  hindsight: number;
  hindsightEarned: number;
  reckonings: number;
  knowhow: Record<string, number>;
  /** M1 CHANGE: institution id → level owned (≥ 1). Was boolean.
   *  M5 CHANGE: 0 is valid: "unlocked, no level" (written by takeOffice and treaty(); InstitutionView.unlocked). Every
   *  "owned" test stays level ≥ 1. */
  institutions: Record<string, number>;
  achievements: Record<string, boolean>;
  /** Sectors that have reached Steady State at least once. */
  steadySectors: Record<SectorId, boolean>;
  /** M1 CHANGE (was furthestEra, an index): sectors ever opened. */
  sectorsOpened: Record<SectorId, boolean>;
  /** Summary of the previous run for the Reckoning card. */
  lastRun?: RunSummary;
  totalSeconds: number;
  /** M1: loadout seats owned. Fresh meta: global.startingSlots ?? 2; raised by one-off slotAdd effects. */
  slots: number;
  /** M1: seated institution ids (each owned), Σ slots ≤ meta.slots. Changed only by setLoadout. */
  loadout: string[];
  /** M1: sectors that have ever backfired (for the first-backfire Hindsight award). */
  backfiredSectors: Record<SectorId, boolean>;
  /* --- M2 --- */
  /** M2: the Charter in force this run (chosen with chooseCharter while fresh), or null. reckon() resets it to null
   *  (and records it in the RunSummary). */
  charter: string | null;
  /** M2: standing orders (see OrdersState); settings that persist across Reckonings. */
  orders: OrdersState;
  /** M2: past runs, oldest first, at most RUN_HISTORY_MAX (the oldest dropped). reckon() appends the run's summary;
   *  `lastRun` is always the last entry. */
  runs: RunSummary[];
  /** M2: the opening of the most recently COMPLETED run (written by reckon()). Absent before the first Reckoning. */
  opening?: OpeningRecord;
  /** M2: the opening of the player's first completed run (written once, by the first reckon() that finds it absent;
   *  M5's rival is seeded from it). */
  firstOpening?: OpeningRecord;
  /** M2: the seq of the last GameEvent emitted (0 in a fresh meta). Never decreases. */
  eventSeq: number;
  /** M2: know-how id → highest level ever owned (one-off effects of a level fire only above it; respec keeps it). */
  knowhowPeak: Record<string, number>;
  /** M2: the highest population of any run (≥ 1), updated every step. */
  peakPopulationEver: number;
  /**
   * The unfolding: features unlocked, id → meta.totalSeconds when each unlocked (see FeatureDef). Kept for good. Absent
   * = {} (a fresh meta has {}). Saves from before the unfolding are grandfathered by deserialize (see SAVE_VERSION).
   */
  features?: Partial<Record<FeatureId, number>>;
  /* --- M3 --- */
  /** M3: dispatch history across the save: times offered, answers per arm by anyone, and per arm by the player
   *  (arrays indexed by arm, extended with zeros). M5's rival and the retrospective read it. */
  dispatches: { seen: Record<string, number>; arms: Record<string, number[]>; playerArms: Record<string, number[]>;
    /** M5 (contract): dispatch id → the player's most recent answer to it: arm, calendar year (integer), run
     *  (meta.reckonings + 1 then). Written by answerDispatch (by 'player') from M5 on; read by the file card (FileView).
     *  Absent = {} (answers before M5 have no year: the file lists them with year null). */
    lastPlayer?: Record<string, { arm: number; year: number; run: number }> };
  /** M3: the History in force this run (chosen while fresh), or null. reckon() resets it to null (recorded in the
   *  RunSummary). */
  history: string | null;
  /** M3: per History ever chosen: runs played with it, whether cleared, and the fastest clear (run seconds). */
  histories: Record<string, { runs: number; cleared: boolean; best: number | null }>;
  /** M3: permanent unlocks of locked Commons projects and Charters (History rewards), and cosmetic keys and titles. */
  unlocks: Record<string, true>;
  /** M3: returns on file, by return id (see ModelApi.fileReturn). */
  returns: Record<string, FiledReturn>;
  /** M3: Archive note id → meta.totalSeconds when unlocked. */
  archive: Record<string, number>;
  /** M3: permanent flags set by the one-off metaFlag effect ('proprietor'). */
  flags: Record<string, boolean>;
  /** M3: endings reached, by id ('steadyAll' in M3; M4 renames nothing, it adds each act's ActDef.ending.id: 'actOne').
   *  M4: milestones gain 'ending:<id>' (an act's ending) and 'capstone' (the first run built with a capstone). */
  endings: Record<string, EndingRecord>;
  /**
   * M3: the first time ever of each thing the retrospective tells, by key (never overwritten; at most MILESTONES_MAX).
   * Keys written by the core: 'reveal'; 'backfire:<s>'; 'sectorOpened:<s>'; 'decade' (the first decade within budget);
   * 'clearSkies:<s>'; 'steady:<s>'; 'settled:<s>'; 'seam:<s>' (first seam sunk); 'dispatch' (first answered);
   * 'history' (first cleared); 'proprietor' (the Proprietor's Day); 'won'. run 0 / at 0 mark "before the records began"
   * (migrated saves).
   * M4 (amend), keys written by the core: 'feed:<source>' (the first founding of an application with feeds in that
   * sector); 'crisis:<s>' (the first crisis of a 'renewable' sector: the first poor season; other sectors write none);
   * 'threshold:<s>' (the first crossing below θK); 'surveyed:<s>' (the first step surveyed, the Board's first survey
   * included); 'scarHealed:<s>'; with Content.acts, 'ending:<actId>' at an act's ending and 'capstone' (the first run
   * built with one) and NOT 'won' (the M3 key is written only by the M3 rule, content without acts).
   */
  milestones: Record<string, { run: number; at: number; year: number }>;
  /** M3: banked seconds (GlobalParams.offline.bankRate; ModelApi.useBank). 0 when banking is off. */
  bankedSeconds: number;
  /* --- M4 --- */
  /**
   * M4: what persists in the WORLD across Reckonings, as opposed to the player's knowledge (Hindsight, Know-how,
   * Institutions, features). Absent = {} (and each member absent = {}). M4 writes `capstone` and `scars`; M7 (The
   * Inheritance) adds reserves, pressure, lock-in, founded uses, population, the generation count and endowments here,
   * so that the prestige shift is a migration, not a rewrite. Nothing world-scoped goes anywhere else. The fresh run is
   * built from it by ONE carry-over step in core (inherit.ts), used by reckon and createState(content, meta) alike; no
   * M4 rule may assume a run starts from a fresh world (design/m4-contract-notes.md §14).
   */
  world?: {
    /** Capstoned sectors, by sector id (CapstoneRecord). Written once per act at its ending, never removed. */
    capstone?: Record<SectorId, CapstoneRecord>;
    /** Scars by renewable sector id (RenewableDef.scar). `since` = meta.totalSeconds when written. */
    scars?: Record<SectorId, { yearsLeft: number; since: number }>;
  };
  /* --- M5 (all optional: absent = the value stated; a fresh meta has none of them) --- */
  /**
   * M5: set by takeOffice, never removed. While present every run is a Ministry (GameState.chair). Fields:
   *   run         meta.reckonings when office was taken;  at  meta.totalSeconds then;
   *   profile     the RivalProfile distilled then (RivalDef.profileFrom), fixed for the save;
   *   sources     the raw figures behind each reading, for the rival's panel ("12 purchases in your first ten minutes"):
   *               haste { n: purchases with t < 600, d: null }; founder { n: founds, d: actions }; volume { n: fork
   *               purchases of the larger-demand arm, d: fork purchases }; drawn { n: earliest firstBudgetAt seconds,
   *               or −1 if none, d: drawnBySeconds }; pliant { n: accepting answers, d: answers }. (Notes: strings; the
   *               contract stores figures and the page words them.)
   *   handedOver  the player's Know-how levels in rival-held trees at that moment (the head start; RivalDef
   *               .knowhowTransfer);
   *   prospectus, file   computed once by takeOffice (the page can show them again);
   *   ministries  Ministries begun (1 after takeOffice; +1 at each Reckoning in office);
   *   record      the Precedent terms accumulated since the last Treaty, added at each Reckoning in office:
   *               certifiedDecades += run.certifiedDecades; settledFromChair += chair sectors settled at the Reckoning;
   *               parliamentsWon += ChairState.electionsWon; wellbeingYears += run.wellbeingYears. Zeroed by treaty().
   */
  office?: {
    run: number; at: number; profile: RivalProfile;
    sources: Record<keyof RivalProfile, { n: number; d: number | null }>;
    handedOver: Record<string, number>;
    prospectus: ProspectusView; file: FileView;
    ministries: number;
    record: { certifiedDecades: number; settledFromChair: number; parliamentsWon: number; wellbeingYears: number };
  };
  /** M5: Precedent to spend on Articles (buyArticle), and all ever earned. Absent = 0. */
  precedent?: number;
  precedentEarned?: number;
  /** M5: Articles bought (kept for good). Absent = {}. */
  articles?: Record<string, true>;
  /** M5: treaty() calls made (Take office not counted). Absent = 0. */
  treaties?: number;
  /** M5: playbook ids the rival has learnt, in order. Absent = []. */
  playbooks?: string[];
  /** M5 (contract): pledge ids that have been in force in any Ministry (Cond `owns` with a pledge id). Absent = {}.
   *  (Notes §11 cites "§14 pledgesKept", which §14 does not define; this is it.) */
  pledgesKept?: Record<string, true>;
}

/**
 * M3: a filed return (MetaState.returns). `figures` are exactly the validated figures (see ModelApi.fileReturn);
 * `run` = meta.reckonings when filed; `at` = meta.totalSeconds when filed; `published`: printed in the paper already;
 * `template`: index into the chosen direction's templates, fixed at publication (null before).
 */
export interface FiledReturn {
  figures: Record<string, number>;
  run: number;
  at: number;
  published: boolean;
  template: number | null;
}

/**
 * M3: the household return's figures, as the UI's play ledger computes them (all counts, ≥ 0; "before" = before the
 * Market first became available on this device, as the ledger's phase mark records it; "after" = since). The UI never
 * files a household return with fewer than these keys; extra keys are dropped.
 *   activeMinutesBefore, activeMinutesAfter   active minutes (page visible, an input in the last 60 s)
 *   sessionsBefore, sessionsAfter             sessions (visible spans after ≥ 10 minutes hidden)
 *   looksBefore, looksAfter                   returns to the visible page
 *   decisionsBefore, decisionsAfter           player decisions observed (increases of run.decisions)
 *   automatedAfter                            standing orders' actions observed since the Market
 *   daysBefore, daysAfter                     calendar days with at least one session
 *   quietDays                                 days with exactly one session of at most 15 active minutes (any phase)
 */
export interface HouseholdFigures {
  activeMinutesBefore: number; activeMinutesAfter: number;
  sessionsBefore: number; sessionsAfter: number;
  looksBefore: number; looksAfter: number;
  decisionsBefore: number; decisionsAfter: number;
  automatedAfter: number;
  daysBefore: number; daysAfter: number;
  quietDays: number;
}

/** M3: what the player files (ModelApi.fileReturn). Untrusted: the core validates it. M3 knows one id, 'household'. */
export interface PlayReturn {
  id: string;
  figures: Record<string, number>;
}

/** M3: an ending reached (MetaState.endings). 'steadyAll' (the first ending) is recorded the first time flags.won is
 *  set in any run: since M3 (finish), every Industry settled at once for GlobalParams.endingYears. Records written under
 *  the earlier rule stand. */
export interface EndingRecord {
  /** Run number (meta.reckonings + 1 then), run time and meta.totalSeconds when reached, calendar year (integer). */
  run: number;
  runSeconds: number;
  totalSeconds: number;
  year: number;
}

export interface RunSummary {
  cause: ReckoningCause;
  causeSector?: SectorId;
  seconds: number;
  /** Calendar year reached (integer). */
  yearReached: number;
  hindsightGained: number;
  peakWellbeing: number;
  /**
   * Per sector open at the end: how much more efficient, how much more resource per second at peak, resource used;
   * M1 adds share of reserve left ('stock' sectors only) and decades within budget.
   * M2 adds (optional, absent on migrated summaries): leanDecades; peakPressure = SectorState.peakPressure / collapseAt;
   * peakAdoption = app id → AppState.peakAdoption for every application founded at the end (absent = never founded);
   * stage = SectorDerived.stage at the end (0 when not authored); steady = Steady State reached this run; settled =
   * settled at the end.
   */
  sectors: Record<SectorId, {
    etaFold: number; peakRFold: number; resourceUsed: number; unburnt?: number; decades?: number;
    leanDecades?: number; peakPressure?: number; peakAdoption?: Record<string, number>; stage?: number;
    steady?: boolean; settled?: boolean;
    /** M3: seams sunk; load factor, speed index and sprawl at the end (absent where the sector has no such kind). */
    seams?: number; loadFactor?: number; speed?: number; sprawl?: number;
    /** M4 (absent on summaries made before M4, and where the sector lacks the kind): the lowest true Q / K this run and
     *  whether it crossed its threshold (renewable); the peak rAdded into each fed target (SectorState.feedPeak; feed
     *  sources); capstoned this run. */
    minStock?: number; crossed?: boolean; feedR?: Record<SectorId, number>; capstoned?: boolean;
    /** M5: SectorState.openFor at the end (seconds; the offer's "open five minutes" for later summaries). M5 also:
     *  certified decades this run, and whether the rival ran it (a chair sector in a Ministry). */
    openFor?: number; certified?: number; rival?: boolean;
  }>;
  /** M1: the Hindsight breakdown at the Reckoning. Absent on summaries migrated from v1. */
  hindsightTerms?: HindsightTerms;
  /* --- M2 (all absent on summaries migrated from v2) --- */
  /** Run number (meta.reckonings after this Reckoning: 1 for the first run). */
  index?: number;
  /** meta.totalSeconds at the Reckoning. */
  totalSecondsAtEnd?: number;
  /** The Charter in force, if any. */
  charter?: string;
  /** run.decisions, run.automated and the per-decade series at the end of the run. */
  decisions?: number;
  automated?: number;
  decisionsByDecade?: number[];
  automatedByDecade?: number[];
  /** Σ Commons levels at the end. */
  commonsLevels?: number;
  /* --- M3 (absent on summaries made before M3) --- */
  /** M3: the History in force, if any, and whether it was cleared in this run. */
  history?: string;
  historyCleared?: boolean;
  /** M3: run.dispatchesAnswered and run.dispatchesDefaulted at the end. */
  dispatchesAnswered?: number;
  dispatchesDefaulted?: number;
  /** run.peakWellbeing is `peakWellbeing`; this is state.peakPopulation. */
  peakPopulation?: number;
  /* --- M5 (present only for a run that was a Ministry) --- */
  /** M5: the Ministry: elections won and lost, inspections made and those that found concealment, rungs closed by
   *  amendment, the Treasury at the end (GameState.capital), chair sectors settled at the end, and the profile in force. */
  ministry?: { electionsWon: number; lost: number; inspections: number; found: number; loopholesClosed: number;
               treasury: number; settledFromChair: SectorId[]; profile?: RivalProfile };
}

/**
 * Why a run ended. M4: OPEN: M7 (The Inheritance) adds 'generation', and later milestones may add more. Code that
 * switches on it must have a default branch (a default label, never an exhaustive switch without one), and a saved
 * RunSummary with an unknown cause must load and display. (A depletion sector never collapses and a capstoned sector
 * never ends a run, so M4 adds no cause.)
 */
export type ReckoningCause = 'exhausted' | 'collapse' | 'chosen'
  /** M5: the Ministry lost ChairDef.opposition.lostInARowEnds elections in a row (ChairState, polling day). No
   *  causeSector. The UI keeps a default label for causes it does not know (M7's 'generation' coexists). */
  | 'defeated';
/*
 * M4 (amend), DEFERRED (recorded, not in the contract): a second crisis name per Industry (SectorDef.pressure has one
 * crisisName; later names live in the crisis headlines); per-level effects on a 'quota' lever; per-Act credits in
 * EndingText; a content slot for UI strings (src/content/boardSurvey.ts exports the Survey card's meanwhile).
 */

/* ------------------------------------------------------------------ */
/* DERIVED (recomputed from state every frame, never stored)           */
/* ------------------------------------------------------------------ */

/** M1: the parts of ModelApi.hindsightOnReckon, for the Reckoning card. All weighted terms are ≥ 0. */
export interface HindsightTerms {
  /** Raw run.wellbeingYears. */
  wellbeingYears: number;
  /** Average burn fold of the run: Σ_s (resourceUsed_s / baseR_s) / Σ_s openFor_s over open sectors with baseR > 0 and
   *  openFor > 0 (unit-free); 1 if there are none. The formula uses max(1, intensity). */
  intensity: number;
  /** perWellbeingYear × wellbeingYears / max(1, intensity)^intensityExponent */
  wellbeing: number;
  /** M2 CHANGE: perBudgetDecade × (run.budgetDecades − run.leanDecades) + (perLeanDecade ?? 0) × run.leanDecades */
  budget: number;
  /** perUnburnt × Σ over open stock sectors of (reserve / reserveMax) × min(1, yearsAtTarget / STEADY_STATE_YEARS)
   *  M4: renewable sectors count as Q / K; resourceStock drawers are not counted (see GlobalParams.hindsight). */
  unburnt: number;
  /** perFirstBackfire × count of run.firstBackfires */
  backfire: number;
  /** perSectorReached × max(0, open sectors − 1). M4: capstoned sectors not counted unless capstone.hindsight. */
  sectorsReached: number;
  /** perSteadySector × count of run.steadySectors */
  steady: number;
  /** M2: (perSettledSector ?? 0) × open sectors settled now. M4: capstoned sectors not counted unless capstone.hindsight. */
  settled: number;
  /**
   * M2 (offline fix): max(0, run.hindsightWithheld ?? 0): Hindsight the seven terms include but a Reckoning does not
   * pay, because it accrued while away (GlobalParams.offline.hindsightRate). Not a weighted term. Present only when
   * > 0 (absent = 0), so a run never fast-forwarded has exactly the M2 shape.
   */
withheld?: number;
  /**
   * M4 (finish): the letters' stake: (sum of the seven terms) × clamp(run.letterShare, −1, ∞), added to the total (which
   * stays ≥ 1). Present only when run.letterShare ≠ 0 (absent = 0, so content without hindsightShare has the M3 shape).
   */
  letters?: number;
  /**
   * M5: in a Ministry, (ChairDef.hindsight.perParliamentWon ?? 0) × ChairState.electionsWon: an eighth weighted term,
   * counted in "the sum of the seven terms" wherever that phrase is used (letters, withheld, total). Present only in
   * office (absent = 0). In a Ministry every other term's weight is GlobalParams.hindsight overlaid by ChairDef.hindsight.
   */
  parliaments?: number;
  /** M2 CHANGE: max(1, round(sum of the seven weighted terms − (withheld ?? 0))) — equals hindsightOnReckon. */
  total: number;
}

/** M1: one line of a checklist built from a Cond. */
export interface CondCheck {
  /** Cond.label, or a plain fallback the core writes ("Own steam.condenser", "steam service delivered ≥ 40k"). */
  label: string;
  met: boolean;
  /** 0–1 for stat leaves (value/target for > and >=; target/value for < and <=), 1/0 for other leaves, null for combinators. */
  progress: number | null;
}

export interface Derived {
  /** M1 CHANGE: calendar year (see AgeDef.yearSpan), fractional. */
  year: number;
  /** M1: the current age: the last age in content.ages with an open sector (null only if content has no ages). */
  age: AgeId | null;
  wellbeing: number;                // 0–100-ish
  incomePerSec: number;
  /** M1: capital one click pays now: clickFlat + clickSeconds × incomePerSec (0 while a Reckoning is pending). */
  clickValue: number;
  /** Net of lever upkeep (M2: and of settlement defences), including the treasury levy share. */
  mandatePerSec: number;
  /** dN/dt per second (see GlobalParams.popGrowth). */
  populationGrowthPerSec: number;
  /** A forced Reckoning is pending (model.tick stops advancing; UI must show the Reckoning screen). */
  pendingReckoning: { cause: ReckoningCause; sector?: SectorId } | null;
  hindsightIfReckonNow: number;
  /** M1: the breakdown of hindsightIfReckonNow. */
  hindsightTerms: HindsightTerms;
  /** M1 CHANGE (was `eras`): open sectors only. */
  sectors: Record<SectorId, SectorDerived>;
  /**
   * M1 CHANGE (was nextEra): the closed sectors whose `after` sectors are all open (the ones that could open next), in
   * sectorOrder, each with its unlock checklist; [] when none.
   * checklist: one CondCheck per child of unlock.when if it is an `all`, else one for `when` itself; for legacy content
   * (no `when`, prevServicePriceBelow set) one stat-style line on the predecessor's service price. Reckonings are
   * reported separately. ready = every condition including reckonings holds (it opens on the next step).
   */
  nextSectors: {
    id: SectorId; reckoningsNeeded: number; reckoningsHave: number; checklist: CondCheck[]; ready: boolean;
  }[];
  /**
   * M1: true while the run is untouched (time === 0 and no upgrade owned). Hindsight can be spent and the loadout
   * changed only then; the UI must not tick while the post-Reckoning screens are open.
   */
  freshRun: boolean;
  /** M1: loadout seats owned and in use. */
  slots: { total: number; used: number };
  /* --- M2 --- */
  /** M2: reference population for scaling the scene's town: max(1, state.peakPopulation, meta.peakPopulationEver).
   *  population / populationRef is 0–1. */
  populationRef: number;
  /** M2: the effective offline cap in seconds (GlobalParams.offline.capSeconds + Σ offlineCapAdd). */
  offlineCapSeconds: number;
  /** M2: the Charters offered (GameState.charterOffer) while freshRun, else []; and the Charter in force (meta.charter). */
  charterOffer: string[];
  charter: string | null;
  /** M2: the Commons: open (meta.reckonings ≥ GlobalParams.commons.fromReckoning), the fund, and the wellbeing all
   *  projects add now (already inside `wellbeing`). */
  commons: { available: boolean; fund: number; wellbeing: number };
  /** M2: standing orders as the UI shows them. */
  orders: OrdersView;
  /**
   * M2: the Know-how respec. allowed = freshRun and some know-how level owned. refund = Hindsight respecKnowhow would
   * return for every tree; refundByTree = the same per tree id (trees with nothing owned are absent).
   */
  respec: { allowed: boolean; refund: number; refundByTree: Record<string, number> };
  /** The unfolding: every FeatureId, true once unlocked (always true for a feature absent from Content.features). */
  features: Record<FeatureId, boolean>;
  /* --- M3 --- */
  /** M3: dispatches (empty and nextIn null while feature 'dispatches' is off). */
  dispatch: DispatchesView;
  /** M3: timed modifiers in force, ending soonest first. */
  modifiers: ModifierView[];
  /** M3: the History in force (meta.history), whether it was cleared this run, whether its forbids have lifted. */
  history: { id: string | null; cleared: boolean; lifted: boolean };
  /** M3: the household survey, once a household return is on file; null otherwise (or while feature 'survey' is off). */
  survey: SurveyView | null;
  /** M3: banked time: seconds, the cap, and whether useBank would run now. */
  bank: { seconds: number; max: number; usable: boolean };
  /**
   * M3: the first ending: reached in any run (meta.endings.steadyAll), and this run's progress to it.
   *   progress     steadyYearsAll / endingYears, 0–1 (1 when endingYears is 0 and every Industry is settled).
   *   allOpen      every sector in sectorOrder is open.
   * M3 (finish), so the page can say what the ending needs without holding the rule:
   *   settled      sectors in sectorOrder that are open and settled now.
   *   total        sectorOrder.length.
   *   years        GameState.steadyYearsAll (model years held with all of them settled).
   *   yearsNeeded  GlobalParams.endingYears with its default.
   *   hold         Mandate per second all settlements' hold costs now (GlobalParams.settleHold; excess defences apart).
   *   nextHold     the same if one more Industry were settled (what settling the next would cost, in total).
   *   room         how many may be settled at once now (GlobalParams.settleMax + settleSlotAdd; = total without a limit).
   *   next         the first Industry in sectorOrder not settled, and what it waits on, in order: 'open' (closed);
   *                'line' (no budget line); 'clear' (its sky is not clear: SectorDerived.sinkHeld false); 'years' (a
   *                clear streak running: `years` of STEADY_STATE_YEARS); 'feature' (Settlement has not arrived);
   *                'room' (at Steady State, but as many are settled as may be: settled ≥ room); 'ready' (ModelApi.settle
   *                would accept it now). null when every Industry is settled.
   * M4 CHANGE (with Content.acts; without them every field keeps its M3 meaning and `act` is null): the fields are read
   *   from the ENDING ACT E = the current act if it has an `ending`, else the last act (in content order) whose ending
   *   has been reached (in M4, after the Act I ending: Act I, so the page keeps showing the settled Coal Age), else none.
   *   With E: reached / record = meta.endings[E.ending.id]; total = E.ending.sectors.length; allOpen, settled and next
   *   over E.ending.sectors (in sectorOrder; a capstoned sector counts as open and settled); progress, years and
   *   yearsNeeded as before (progress 1 when reached and E is not current). Without E: reached false, record null,
   *   progress 0, total 0, settled 0, next null, allOpen false; hold, nextHold and room as M3 in every case.
   *   next.need gains 'requires', ordered after 'feature' and before 'room': at Steady State but settle.requires fails
   *   (its label is SectorDerived.settleBlocked of next.sector).
   */
  ending: {
    reached: boolean; record: EndingRecord | null; progress: number; allOpen: boolean;
    settled: number; total: number; years: number; yearsNeeded: number;
    hold: number; nextHold: number; room: number;
    next: {
      sector: SectorId;
      need: 'open' | 'line' | 'clear' | 'years' | 'feature' | 'room' | 'ready'
        /** M4: see above. */
        | 'requires';
      years: number;
    } | null;
    /** M4: the ending act E (above): its id, name and title (the Act title card), or null (no acts, or no E). Absent =
     *  null (views from a core before M4). */
    act?: { id: string; name: string; title: string } | null;
    /** M4 (polish): the next Institution level that makes room (a settleSlotAdd effect), so the page can say what more
     *  room waits on: its name, its Hindsight price, and the label of its unmet `needs` (null when it has none or it
     *  holds). null when no such level is left. Absent = null. */
    roomBy?: { name: string; cost: number; needs: string | null } | null;
  };
  /** M3: Archive notes unlocked (in content) and in content. */
  archive: { unlocked: number; total: number };
  /* --- M4 (optional: absent = null, as from a core before M4; the M4 core always writes it) --- */
  /**
   * M4 (The Survey): the reveal to show, built from GameState.surveyReveal and Content.surveyReveal: present from the
   * step of the Board's first survey (the 'surveyed' event with first: true) until the run ends; the page shows it once
   * (it keeps its own "seen"). reported and true are fractions 0–1 (as recorded); headline and body are the variant's,
   * substituted. null when there is none this run, or Content.surveyReveal is absent or has no variant of that kind.
   */
  surveyReveal?: {
    sector: SectorId; reported: number; true: number; variant: 'small' | 'large' | 'failed';
    headline: string; body: string;
  } | null;
  /* --- M5 (optional: absent = null / as stated, as from a core before M5; the M5 core always writes them). M5 CHANGES
   *     to existing fields in a Ministry: incomePerSec is the TREASURY's income per second (ChairDef.treasury, net of
   *     pledges' treasuryShare); clickValue is 0 (click is refused); pendingReckoning.cause may be 'defeated';
   *     nextSectors leaves out sectors of closedInOffice acts; hindsightIfReckonNow and hindsightTerms use the overlay. --- */
  /**
   * M5: office. offered = GameState.officeOffer && freshRun && office not taken (the page shows Take office / Not yet);
   * taken = meta.office present; prospectus / file = meta.office's (null before office); sealed = sectors of
   * closedInOffice acts that are in meta.sectorsOpened, while office is taken (the sealed postcards; [] otherwise).
   * For the offer card before office is taken, `preview` is the prospectus and file as takeOffice WOULD store them now
   * (null unless offered).
   */
  office?: {
    offered: boolean; taken: boolean; prospectus: ProspectusView | null; file: FileView | null; sealed: SectorId[];
    preview: { prospectus: ProspectusView; file: FileView } | null;
  };
  /** M5: the Ministry for the page (ChairView); null outside office, or while feature 'chair' is off. */
  chair?: ChairView | null;
  /**
   * M5: the Treaty, between runs: available = feature 'treaty' on, freshRun, office taken, ChairDef.treaty present and
   * its `when` holds (treaty() would accept); precedentIfNow = the Precedent treaty() would pay now; terms = the four
   * weighted terms by name ('certifiedDecades', 'settledFromChair', 'parliamentsWon', 'wellbeingYears'), unrounded.
   * Also: precedent = meta.precedent ?? 0; articles = ArticleView for every Article (content order). null while feature
   * 'treaty' is off or office is not taken.
   */
  treaty?: { available: boolean; precedentIfNow: number; terms: Record<string, number>; precedent: number;
             articles: ArticleView[] } | null;
}

/** M3: Derived.dispatch. */
export interface DispatchesView {
  /** Pending, oldest first. */
  pending: PendingDispatchView[];
  /** Seconds of run time until the next draw may happen; null while drawing is paused (feature off, list full, fresh,
   *  a Reckoning pending). */
  nextIn: number | null;
}

/** M3: one pending dispatch as the panel shows it (all text already substituted). */
export interface PendingDispatchView {
  id: string;
  def: DispatchDef;
  cast: CastDef | null;
  headline: string;
  body: string;
  /** Seconds left before the default is taken. */
  expiresIn: number;
  defaultArm: number;
  arms: {
    label: string; outcome: string; price: string;
    /** Resolved hard costs now (capital in £ = capitalSeconds × income per second). */
    capital: number; mandate: number;
    /** answerDispatch would accept this arm now. */
    affordable: boolean;
    /** The arm's effects and modifier, for the UI's effect formatter. */
    effects: EffectDef[]; modifier: { effects: EffectDef[]; years: number; label?: string } | null;
    /** M4: a wager arm's hint and its two outcome lines, substituted (DispatchArm.wager); null for an ordinary arm.
     *  Absent = null (views from a core before M4). The view never says which way it would go. */
    wager?: { hint: string; win: string; lose: string } | null;
  }[];
}

/** M3: one timed modifier for the page. */
export interface ModifierView {
  source: string;
  arm: number;
  /** DispatchArm.modifier.label ?? the arm's label. */
  label: string;
  effects: EffectDef[];
  /** Seconds of run time left. */
  remaining: number;
}

/**
 * M3: the household survey (Derived.survey), from meta.returns.household. Rates guard their denominators: a rate with
 * a zero denominator is null, and a change with a null or zero base is null.
 *   workdayBefore = activeMinutesBefore / daysBefore; workdayAfter likewise (active minutes per day played)
 *   decisionsPerHourBefore = decisionsBefore / (activeMinutesBefore / 60); After likewise
 *   automatedPerHour = automatedAfter / (activeMinutesAfter / 60)
 *   sessionsPerDayBefore = sessionsBefore / daysBefore; After likewise
 *   minutesPerSessionBefore = activeMinutesBefore / sessionsBefore; After likewise
 *   workdayChange = workdayAfter / workdayBefore − 1; decisionsChange likewise
 *   direction = 'up' if workdayChange > 0.05, 'down' if < −0.05, else 'flat' (null change → 'flat')
 *   pure: the model's own decisions per model decade, before the Market (the mean over meta.runs entries with
 *     index 1 of Σ decisionsByDecade / its length) and after (entries with index ≥ 2, likewise); null when none.
 * The second pair of twin gauges is automatedPerHour ("Decisions automated") against decisionsPerHourAfter ("The
 * proprietor's decisions per hour").
 */
export interface SurveyView {
  filedRun: number;
  published: boolean;
  workdayBefore: number | null; workdayAfter: number | null; workdayChange: number | null;
  decisionsPerHourBefore: number | null; decisionsPerHourAfter: number | null; decisionsChange: number | null;
  automatedPerHour: number | null;
  sessionsPerDayBefore: number | null; sessionsPerDayAfter: number | null;
  minutesPerSessionBefore: number | null; minutesPerSessionAfter: number | null;
  direction: 'up' | 'down' | 'flat';
  pure: { decisionsPerDecadeBefore: number | null; decisionsPerDecadeAfter: number | null };
  /** The published return, substituted (Content.proprietor), or null before publication. */
  text: { headline: string; body: string } | null;
}

/** M3: one History for the picker (ModelApi.historyViews, content order). */
export interface HistoryView {
  def: HistoryDef;
  /** requires holds and feature 'histories' is on. */
  offered: boolean;
  inForce: boolean;
  /** meta.histories[id] or zeros. */
  runs: number;
  cleared: boolean;
  best: number | null;
  /** offered, Derived.freshRun, and not already in force. */
  canChoose: boolean;
}

/** M3: one Archive note (ModelApi.archiveViews, content order; locked notes included with unlocked false and no text). */
export interface ArchiveView {
  id: string;
  subject: string;
  /** The subject's display name (card, lever, application, project, seam, dispatch headline, History, Charter, cast
   *  member, achievement or sector name), or the id if unknown. */
  subjectName: string;
  title: string;
  date: string;
  unlocked: boolean;
  /** meta.totalSeconds at unlock, or null. */
  at: number | null;
  /** Empty while locked. */
  text: string;
  sources: ArchiveDef['sources'];
}

/** M3: one item of the retrospective Gazette (ModelApi.retrospective), oldest first. */
export interface RetroItem {
  key: string;
  run: number;
  year: number;
  /** meta.totalSeconds at the milestone. */
  at: number;
  sector?: SectorId;
  /** Substituted EndingText.retrospective headline. Milestones with no matching template are left out. */
  headline: string;
}

/** M3: why the Market did or did not act in a sector (OrdersView.marketWhy). */
export type MarketWhy =
  | { reason: 'unavailable' | 'off' | 'sectorOff' | 'settled' | 'fresh' | 'pending' | 'waiting' }
  | { reason: 'bought'; id: string; at: number }
  | { reason: 'none' | 'cash'; at: number }
  | { reason: 'payback'; payback: number; at: number };

/** M2: Derived.orders. */
export interface OrdersView {
  market: {
    available: boolean;
    /** The stored settings (MetaState.orders.market). */
    on: boolean;
    paybackMax: number;
    /** GlobalParams.orders.paybackChoices ?? [30, 120, 600]. */
    paybackChoices: number[];
    /** Resolved switch for every OPEN sector (true where the stored map has no key). */
    sectors: Record<SectorId, boolean>;
    /** M5: in a Ministry, true: the Market row is shown as the rival's policy ("Pryce Consolidated: buys whatever pays
     *  back within {n} seconds. (Your Market; his purse.)", n = ChairView.rival.paybackMax); `available` reads false
     *  (the player's Market has nothing to buy). Absent = false. */
    rival?: boolean;
  };
  civilService: { available: boolean; on: boolean; levers: Record<SectorId, string[]> };
  treasury: { available: boolean; on: boolean; keepSeconds: number; projects: string[] };
  /** Seconds of run time until the next order tick. */
  nextTickIn: number;
  /* --- M3 --- */
  /** M3: per OPEN sector, why the Market did or did not act: the static reasons first ('unavailable' — not yet
   *  available or suspended by the History; 'off'; 'sectorOff'; 'settled'; 'fresh'; 'pending'), else the last order
   *  tick's outcome from GameState.orderLog ('bought' | 'none' | 'cash' | 'payback'), else 'waiting' (no tick yet). */
  marketWhy: Record<SectorId, MarketWhy>;
  /** M3: the standing dispatch order. */
  dispatch: { available: boolean; on: boolean; cast: Record<string, boolean> };
  /** M3: shift 3's label per order, fixed by the contract: market 'opening'; civilService, treasury and dispatch
   *  'closing'. The UI shows it only once meta.flags.proprietor is true. M5: inspection 'closing'. */
  kind: Record<OrderId, 'opening' | 'closing'>;
  /* --- M5 (optional; absent = as stated) --- */
  /** M5: Standing inspection: available (a standing orderUnlock 'inspection' and feature 'inspection'), the stored
   *  settings. Absent = unavailable. */
  inspection?: { available: boolean; on: boolean; sector: SectorId | null };
}

/** M1 CHANGE (was EraDerived). */
export interface SectorDerived {
  eta: number;
  /** eta / etaAtBase (1 before the baseline exists). */
  etaFold: number;
  /** p_r incl. permit price. */
  resourcePrice: number;
  /** M1: p_r without the permit (depletion or utilisation price). */
  resourcePriceBase: number;
  /** M1: permit price per unit of resource (0 unless a cap binds). */
  permitPrice: number;
  /** M1: effective capital cost c per unit of service (capCost × Π capCostMul). */
  capCost: number;
  /** M1: effective margin m. */
  margin: number;
  /** M1: substituted share σ (0 without substitution levers). */
  substitutedShare: number;
  /**
   * M1: the price before any levy: p_pre = (1 − σ) × (resourcePriceBase / η + c) + σ × 1.5 × c.
   * Player income = m × p_pre × D.
   */
  preLevyPrice: number;
  /** M1: permit part of the service price: (1 − σ) × permitPrice / η. */
  permitPart: number;
  /** M1: duty part of the service price (see LeverKind 'duty'). */
  dutyPart: number;
  /** p_s the customer pays: preLevyPrice + permitPart + dutyPart. */
  servicePrice: number;
  demand: number;                   // D, service per second
  resourceUse: number;              // R per second
  rFold: number;                    // R / baseR (1 before the baseline)
  /**
   * M1: the SHADOW: R this sector would burn right now with η frozen at etaAtBase, everything else identical (founded
   * applications, satMul, population, reserve and depletion price, spill and drawsOn inputs, levers, budget and cap).
   * "What this economy would burn with no efficiency gains at all." 0 before the baseline.
   */
  shadowR: number;
  /** M1 CHANGE: shadowR / etaFold — what the cards promised for today's economy. Was baseR / etaFold. */
  promisedR: number;
  /**
   * M1 CHANGE: DIRECT rebound, measured against the shadow:
   *   rebound = (R − promisedR) / (shadowR − promisedR)
   * Share of the promised savings eaten by extra use of the same applications; > 1 is backfire. New applications,
   * population and depletion move shadowR as well, so they no longer count. Under a binding cap R ≈ shadowR, so the
   * meter reads ≈ 100%: the savings became service, the cap set the coal. null until etaFold > 1.001, or while
   * shadowR ≤ 0 or shadowR − promisedR ≤ 1e−9 × shadowR.
   */
  rebound: number | null;
  /**
   * M1: shadowR / baseR — growth at frozen efficiency since the baseline: new applications (frontier), population
   * (economy-wide) and scarcity together. rFold = frontierFold × R / shadowR. 1 before the baseline.
   */
  frontierFold: number;
  income: number;
  /** M1: levy revenue per second (dutyPart × D + permitPrice × R); never income. */
  levyRevenue: number;
  /** 'stock': reserve / reserveMax. 'flow': 1 − utilisation. */
  reserveFraction: number;
  /** Seconds until exhaustion (reserve reaching EXHAUSTED_BELOW × reserveMax) at the current net drain ('stock'), Infinity otherwise. */
  secondsLeft: number;
  pressureFraction: number;         // P / collapseAt
  /** M1: the fraction of collapseAt at which the next crisis fires (crisisAt[crisesFired]), null once all have fired. */
  nextCrisisFraction: number | null;
  /** Cosmetic trend arrow (SectorState.trendR). */
  trendR: number;
  /** M1: today's budget line R, or null if no budget is drawn. */
  budgetR: number | null;
  /** M1: budget drawn and R ≤ budgetR × (1 + BUDGET_TOLERANCE). */
  withinBudget: boolean;
  /**
   * M1 CHANGE (one definition used everywhere): withinBudget AND wellbeing ≥ wellbeingTarget AND no Reckoning pending.
   * Replaces v1's "trendR < −0.001": a held line counts, short dips earn nothing unless a whole decade is served, and a
   * budget must be drawn before anything counts (efficiency-only play never decouples).
   * M2 CHANGE: wellbeing ≥ decadeWellbeing (not the target). This is the DECADE streak's condition (steadyYears).
   * A settled sector reports true while wellbeing ≥ wellbeingTarget.
   */
  decoupling: boolean;
  /** Current streak in model years (SectorState.steadyYears). */
  steadyYears: number;
  /** M1: decades within budget completed this run (SectorState.decadesWithin.length). */
  budgetDecades: number;
  wellbeingShare: number;           // this sector's contribution to wellbeing
  apps: Record<string, AppDerived>;
  /* --- M2 --- */
  /** M2: the wellbeing decades are judged against now (SteadyParams.decadeWellbeing); wellbeingTarget without a budget. */
  decadeWellbeing: number;
  /** M2: decades this run that were lean (count of true in SectorState.decadesLean). */
  leanDecades: number;
  /** M2: the pace of the current line (BudgetState.pace), or null without a budget. */
  pace: string | null;
  /** M2: the clear level clearP (SteadyParams.clearBelow), or null without a budget. */
  clearP: number | null;
  /**
   * M2: clear skies: a budget exists, P ≤ clearP, and the net pressure rate is not rising:
   *   pressureIn − deletionOut − absorption × P ≤ CLEAR_RATE_TOLERANCE × collapseAt
   * (absorption = SectorDef.absorption + Σ absorptionAdd; pressureIn and deletionOut as the step uses them).
   * Settled sectors report true.
   */
  clear: boolean;
  /**
   * M2: the sink line: the R at which equilibrium pressure equals clearP, at today's η, shares and intensity:
   *   sinkR = (clearP × absorption + deletionOut) × R / pressureIn
   * (pressure inflow is linear in R at fixed η and shares, whether its source is 'resource' or 'service').
   * null without a budget, when absorption ≤ 0 (Code: its stock has no sink and must be deleted down; clear can still
   * be reached through deletion), when pressureIn ≤ 0 or R ≤ 0, and while settled. Drawn on the sparkline as R / baseR.
   */
  sinkR: number | null;
  /** M2: the Steady streak in model years (SectorState.clearYears). */
  clearYears: number;
  /** M2: withinBudget AND wellbeing ≥ wellbeingTarget AND clear AND no Reckoning pending: the Steady streak's condition.
   *  Settled sectors report false (their streak is held, not advanced). */
  sinkHeld: boolean;
  /** M2: settled (SectorState.settled ≠ null). */
  settled: boolean;
  /** M2: ModelApi.settle would succeed now. */
  canSettle: boolean;
  /** M2: while settled, the excess and the defence it costs (Mandate per second; see SettledState); else 0 and 0. */
  settleExcess: number;
  settleDefence: number;
  /** M2: the machine stage (largest UpgradeDef.stage among owned upgrades of this sector, 0 if none); null when no
   *  upgrade of this sector has a `stage` (the scene keeps its own heuristic). */
  stage: number | null;
  /** M2: model years until an active cap with no line draws one (steady.standingDrawYears − openFor × YEARS_PER_SECOND,
   *  at least 0); null when no cap lever of the sector is active or a budget exists. */
  standingDrawIn: number | null;
  /* --- M3 (each null where the sector lacks the kind, or while its feature is off) --- */
  /** M3: the seam ladder (feature 'seams'). */
  seams: SeamsView | null;
  /** M3: the load curve (feature 'load'; live, or frozen from SettledState.load while settled; null if settled
   *  before M3). */
  load: LoadView | null;
  /** M3: travel (feature 'travel'; live, or frozen from SettledState.travel while settled). */
  travel: TravelView | null;
  /** M3: free at the point of use (feature 'freeAtUse'): present when any founded application's seen price differs
   *  from p_s. bill = Σ (p_s − p_a) × D_a over those with p_a < p_s (£ per second); freeShare = their D share. */
  free: { bill: number; freeShare: number } | null;
  /** M3: Code's mechanic exposed (sectors with pressureUpkeep > 0; no feature gate, it is the Industry's gauge): the
   *  share of capacity eaten by upkeep, min(0.95, P × pressureUpkeep / capacity), and deletion out-flow and pressure
   *  in-flow per second. */
  upkeep: { share: number; deletionOut: number; pressureIn: number } | null;
  /* --- M4 (each optional: absent = the null / false stated, as from a core before M4; the M4 core always writes every
   *     one). M4 CHANGES to existing fields: for a 'renewable' sector reserveFraction is the TRUE Q / K and secondsLeft
   *     Infinity; while it is NOT surveyed, sinkR and clearP read null (no sink line on the page) while
   *     pressureFraction keeps the TRUE value (the core's rules and crises use it; the page shows
   *     stock.reportedPressureFraction instead). A resourceStock drawer's reserveFraction and secondsLeft are the
   *     owner's. A capstoned sector reports as a settled one, with its scaled values (in arrears: the arrears values). --- */
  /** M4: this sector's age belongs to an act with `preview` (ActDef.preview); the page labels it "Preview". It plays
   *  under the ordinary rules and is never part of an act's ending set. False without Content.acts. */
  preview?: boolean;
  /** M4: SectorState.capstoned. */
  capstoned?: boolean;
  /** M4: SectorState.arrears. */
  arrears?: boolean;
  /** M4: on a reserve OWNER drawn on by another sector (SectorDef.resourceStock): the drain by source this step, R per
   *  second net of each one's circularity, by sector id (own included); null if nothing draws on it. */
  drawnBy?: Record<SectorId, number> | null;
  /**
   * M4: on a feed SOURCE (Iron), the order book: per target sector currently fed, in sectorOrder:
   *   factor     Π f over this sector's feeding apps into that target (≤ 1; ApplicationDef.feeds).
   *   rAdded     target R now − target R solved with this sector's feeds removed (same state, no time), per second; ≥ 0
   *              normally. Computed at most once per derive bucket (as M3's temptation views: PROJECTION_BUCKET), null
   *              in projections.
   *   lineShare  rAdded / the target's budgetR when the target has a budget line, else null.
   * null when this sector has no application with feeds, or none founded.
   */
  feeds?: { to: SectorId; factor: number; rAdded: number | null; lineShare: number | null }[] | null;
  /**
   * M4 (amend): on a feed TARGET (Steam), what every source feeds into it, as one figure for the order book and the
   * letters: factor = Π of every feed factor into it (stat 'feedFactor'); rAdded = Σ over sources of their rAdded into it
   * (each source removed alone; per derive bucket, as SectorDerived.feeds); share = rAdded ÷ its R (stat 'feedShare'),
   * null when R is 0. null when nothing feeds it now (no founded feeding application of an open source). Not gated by
   * feedsKnownWhen (the target's own price shows it). Absent = null.
   */
  fed?: { factor: number; rAdded: number | null; share: number | null } | null;
  /** M4: the label of the failing settle.requires while the sector is at Steady State (clearYears ≥
   *  STEADY_STATE_YEARS and sinkHeld) and unsettled, else null. (Cond.label, or the core's plain fallback.) */
  settleBlocked?: string | null;
  /**
   * M4: the stock gauges ('renewable' only; null otherwise).
   *   reported   catch per trip, (Q/K)^beta, 0–1                       — always
   *   true       Q/K, 0–1, or null while NOT surveyed                  — the survey's gauge
   *   surveyed   a survey effect (EffectDef 'survey') is in force
   *   regen      G(Q) per second now (null while not surveyed)
   *   foreign    { share, R } now (null without ForeignDef; share is shown always: the sails are visible)
   *   scar       { yearsLeft } from meta.world.scars, or null
   *   crossed    SectorState.crossed
   *   reportedPressureFraction  1 − reported: what the fleet's depletion gauge shows while unsurveyed
   *   world      the true Q/K, ALWAYS, for the scene's living world only (gulls, shoals, boats out; the soundscape's sea
   *              life). The page's gauges and text must not read it: they read `true` (null while unsurveyed).
   * A settled or capstoned renewable reports its frozen Q (foreign null).
   */
  stock?: {
    reported: number; true: number | null; surveyed: boolean; regen: number | null;
    foreign: { share: number; R: number } | null; scar: { yearsLeft: number } | null; crossed: boolean;
    reportedPressureFraction: number;
    world: number;
  } | null;
  /**
   * M4 (The Survey; feature 'estimates'): the full account: the resource used on this sector's behalf, wherever burnt.
   *   fullR = R − handedOn + received
   * Attribution, per derive, deterministic, conserving totals (Σ fullR = Σ R over open sectors, foreign catch excluded):
   *   - a source with feeds (Iron) splits its R across its founded applications by demand share; an application's share
   *     with feeds is handed on to its targets in proportion to (1 − f_t) for each target t (for '*', every fed open
   *     sector); applications without feeds keep their share;
   *   - drawsOn: the drawn service's share of the target's R (drawn D ÷ target D × target R) is handed from the target
   *     (Steam) to the drawer (Fishing);
   *   - a settled sector's frozen R takes part with its frozen adoption and draws;
   *   - foreign catch is nobody's (not attributed).
   * One pass in sectorOrder over the solve's edge order (an R handed on is not handed on again). null while 'estimates'
   * is off.
   */
  fullR?: number | null;
  /** M4: what fullR received, by source sector, in sectorOrder (entries with R > 0 only); null while 'estimates' is off. */
  embodied?: { from: SectorId; R: number }[] | null;
  /**
   * M4 (The Survey): years of the resource left ('stock' sectors and their resourceStock drawers; null otherwise).
   *   flat     the old reading, "at this year's rate": secondsLeft × YEARS_PER_SECOND (the net drain to the exhaustion
   *            threshold; for a drawer the owner's total drain), model years; null when secondsLeft is Infinity.
   *   growing  years to exhaustion if the drain grows at the sector's trend g (SectorState.trendR, per model year; the
   *            owner's for a drawer) when g > 0: ln(1 + g × flat) / g; equals flat when g ≤ 0; null while 'estimates'
   *            is off or flat is null.
   * Both assume no new seam (the formula sheet says so).
   */
  yearsLeft?: { flat: number | null; growing: number | null } | null;
  /* --- M5 (each optional: absent = the value stated, as from a core before M5; the M5 core always writes every one).
   *     M5 CHANGES to existing fields: `preview` per ActDef.chair; resourceUse is always the TRUE R (consumed water on a
   *     hiddenFlow sector); levyRevenue is net of concealment; servicePrice includes chargePart; income on a chair
   *     sector is the rival's. --- */
  /** M5: the official gauge: R × (1 − concealment) on a rival sector while feature 'inspection' is on; R otherwise. The
   *  page shows this as the Industry's R ("as reported") unless inspectedUntil is in the future. Absent = resourceUse. */
  reportedR?: number;
  /** M5: run time until which the true R is shown (last inspection + revealYears / YPS), or null. */
  inspectedUntil?: number | null;
  /** M5: what the last inspection found (ChairState.found[s]), or null. */
  found?: { share: number; t: number } | null;
  /** M5: run time of the last inspection this Ministry (ChairState.inspected[s]), or null if never ("last inspected
   *  1961" / "never"). */
  inspectedAt?: number | null;
  /** M5: run by the rival: a chair sector or a capstoned sector in a Ministry. Absent = false. */
  rival?: boolean;
  /** M5: the charge part of the service price now (LeverKind 'charge'; 0 without one). Absent = 0. */
  chargePart?: number;
  /** M5: hidden flow (SectorDef.hiddenFlow only; null otherwise): water applied (R_applied) and consumed (R) per
   *  second, and the return share r now. Settled: frozen. */
  water?: { applied: number; consumed: number; returnShare: number } | null;
  /** M5: decades certified this run (count of true in SectorState.decadesCertified). Absent = 0. */
  certifiedDecades?: number;
  /** M5: the rival's upgrade purchases in this sector this run (count of levels; "Pryce has bought 14"). null outside a
   *  rival sector. */
  rivalBought?: number | null;
}

/** M3: SectorDerived.seams. */
export interface SeamsView {
  sunk: number;
  total: number;
  /** The current resource-price multiplier from seams (1 before any). */
  priceMul: number;
  ladder: {
    def: SeamDef;
    sunk: boolean;
    /** The next one only: reachBelow and requires hold now. False for the others. */
    reachable: boolean;
    /** Capital cost now (after cost effects). */
    cost: number;
    /** ModelApi.sinkSeam would accept it now. */
    canSink: boolean;
    /** A forbid effect is in force on it. */
    forbidden: boolean;
  }[];
  /** M3 (finish): the temptation's trade, shown where the player decides (design: each Industry's
   *  mechanic pays the burner and tests the restrainer). Once the Industry's mechanic feature is on and it has a budget
   *  line drawn: R the Industry would burn with this taken now ÷ R without it, both solved free of any cap (the use the
   *  line would have to hold back), − 1. Else null (absent on views from before M3 finish). Recomputed at most once per
   *  PROJECTION_BUCKET seconds of run time while nothing structural changes.
   *  Here: sinking the next seam now (null when none is left). */
  wantedChange?: number | null;
}

/** M3: SectorDerived.load. */
export interface LoadView {
  /** LF, 0–1. */
  factor: number;
  /** H[h], service per second in each hour (LOAD_HOURS values). */
  hours: number[];
  peak: number;
  /** c before and after the idle-plant mark-up. */
  capCostBase: number;
  capCostEff: number;
}

/** M3: SectorDerived.travel. */
export interface TravelView {
  /** v(D) and the free speed s. */
  speed: number;
  freeSpeed: number;
  roads: number;
  /** (D / K)^b. */
  congestion: number;
  hoursPerHead: number;
  /** Σ lockIn × peakD over founded applications (service per second locked in) and its share of D (0 if D is 0). */
  sprawl: number;
  sprawlShare: number;
}

export interface AppDerived {
  available: boolean;
  founded: boolean;
  demand: number;
  /** demand / current effective saturation, 0–1. M2: in a settled sector, the frozen SettledState values. */
  adoption: number;
  /** Available, not founded, capital ≥ foundCost, no Reckoning pending (M2: and the sector not settled).
   *  M3: and not forbidden; the cost is `foundCost` below (after costMulOf effects). */
  canFound: boolean;
  /* --- M3 --- */
  /** M3: the price this application's users see (= servicePrice without priceSeen). */
  priceSeen: number;
  /** M3: foundCost after costMulOf effects. */
  foundCost: number;
  /** M3: a forbid effect is in force on it. */
  forbidden: boolean;
  /** M3 (finish): the temptation's trade, shown where the player decides (design: each Industry's
   *  mechanic pays the burner and tests the restrainer). Once the Industry's mechanic feature is on and it has a budget
   *  line drawn: R the Industry would burn with this taken now ÷ R without it, both solved free of any cap (the use the
   *  line would have to hold back), − 1. Else null (absent on views from before M3 finish). Recomputed at most once per
   *  PROJECTION_BUCKET seconds of run time while nothing structural changes.
   *  Here: for an available, unfounded application that IS the mechanic (a load profile other than the default, a
   *  travel use with lockIn, an ApplicationDef.priceSeen), founding it now. */
  wantedChange?: number | null;
  /* --- M4 --- */
  /** M4: this application's feeds as factors now (target sector id → f, ApplicationDef.feeds; '*' expanded to every
   *  other open sector; 1 while unfounded), or null if it has no feeds. Absent = null (a core before M4). For an
   *  application with feeds, wantedChange (once its conditions hold) also counts the fed Industries' R change
   *  (core: temptation.ts). */
  feeds?: Record<SectorId, number> | null;
  /** M4 (amend): false while the sector's mechanic.feedsKnownWhen fails (feeds then null); true otherwise. Absent = true. */
  feedsKnown?: boolean;
  /* --- M5 --- */
  /** M5: 'elastic' when (p_seen / p_i)^k_i > 1 (adoption below half: cheaper service clears more land: Jevons), else
   *  'saturated' (cheaper service spares land: Borlaug); p_seen = priceSeen, p_i the effective halfPrice. A label on
   *  any sector, no new arithmetic. Absent = not computed. M5 CHANGE: canFound is false in a chair sector. */
  regime?: 'elastic' | 'saturated';
  /** M5: ApplicationDef.when fails now (frozen or unavailable; AppState.frozenSat). Absent = false. */
  frozen?: boolean;
  /** M5 (amend): while ApplicationDef.when fails, its label (Cond.label or the core's fallback, as LeverView.waiting);
   *  else null. Absent = null (a core before the amendment; an application without `when`). */
  waiting?: string | null;
}

export interface UpgradeView {
  def: UpgradeDef;
  level: number;
  /** Capital cost of the next purchase (after cost multipliers). */
  cost: number;
  /** Sector open (M2: and not settled), prerequisites met, and not locked. Excluded fork arms stay visible. */
  visible: boolean;
  /** Visible, not maxed, not excluded, and capital ≥ cost. */
  affordable: boolean;
  maxed: boolean;
  /** M1: id of the owned upgrade that excludes this one (fork already taken), else null. */
  excludedBy: string | null;
  /** Efficiency cards: the engineer's promise, 1 / Π etaMul − 1, e.g. −0.6 for "−60% coal per unit of power". */
  promisedChange: number | null;
  /**
   * M1 (replaces projectedChange): "This decade". For visible, unmaxed, unexcluded 'efficiency' and 'capital' cards,
   * once flags.revealed: simulate two clones PROJECTION_YEARS ahead (200 s, steps of 5 s; population, depletion and
   * availability all move; nothing else is bought, no app is founded), one with this upgrade applied free.
   *   projectedDecade = R_with / R_without − 1 for the upgrade's sector at the horizon (null if R_without ≤ 0).
   * Otherwise null.
   */
  projectedDecade: number | null;
  /**
   * M1: "Brings within reach". Same two simulations: every application of the upgrade's sector that is not yet
   * available now, whose visibleBelow the with-upgrade path's service price reaches within the horizon and the
   * without path's does not. projectedChange = R(with-upgrade end state, that app founded) / R(with-upgrade end state)
   * − 1, i.e. "+180% coal if founded". Ordered by visibleBelow descending. [] when projectedDecade is null.
   */
  bringsWithinReach: { appId: string; projectedChange: number }[];
  /* --- M3 --- */
  /** M3: a forbid effect is in force on it (it stays visible; `affordable` is false). M3 CHANGE: `visible` also needs
   *  UpgradeDef.when; `cost` includes costMulOf effects. */
  forbidden: boolean;
  /** M3 (finish): the temptation's trade, shown where the player decides (design: each Industry's
   *  mechanic pays the burner and tests the restrainer). Once the Industry's mechanic feature is on and it has a budget
   *  line drawn: R the Industry would burn with this taken now ÷ R without it, both solved free of any cap (the use the
   *  line would have to hold back), − 1. Else null (absent on views from before M3 finish). Recomputed at most once per
   *  PROJECTION_BUCKET seconds of run time while nothing structural changes.
   *  Here: for a visible, unmaxed card with a priceSeen effect (a business model, a flat rate), under feature
   *  'freeAtUse', buying it now (its other effects included). */
  wantedChange?: number | null;
  /* --- M5 --- */
  /** M5: a card of a chair sector in a Ministry: the rival's order book, read-only (affordable false; buyUpgrade
   *  refuses); `level` counts his purchases. Absent = false. */
  byRival?: boolean;
  /** M5: with byRival: his payback on it now (seconds; Infinity if no gain; subsidies applied), or null. Absent = null. */
  rivalPayback?: number | null;
  /** M5: with byRival: a 'subsidy' lever in force pays this share of its cost (0 if none). Absent = 0. */
  subsidised?: number;
}

export interface LeverView {
  def: LeverDef;
  level: number;
  /** M1: highest reachable level (levels.length, plus repeat steps; Infinity only if repeat has no bound at all). */
  maxLevel: number;
  /** M1: resolved definition of the current level (synthesised for repeat levels), null at level 0. */
  current: LeverLevelDef | null;
  /** M1: resolved definition of the next level, null at maxLevel. */
  next: LeverLevelDef | null;
  visible: boolean;
  /** Mandate needed for the next level (0 where an institution makes it free), null if at max. */
  nextCost: number | null;
  canRaise: boolean;
  /** Net Mandate upkeep per second at the current level. */
  upkeep: number;
  /** M1: options offered (empty for kinds other than duty and cap) and the one in force (null for those kinds). */
  recycleOptions: LeverRecycle[];
  recycle: LeverRecycle | null;
  /** M2: recycleOptions with their resolved wording (LeverDef.recycleBlurb ?? Content.recycleText ?? defaults) and
   *  whether setLeverRecycle would accept each now ('commons' needs the Commons open). */
  recycleChoices: { option: LeverRecycle; name: string; blurb: string; available: boolean }[];
  /* --- M3 --- */
  /** M3: side effects: LeverState.bite, whether it is growing now (level ≥ 1 and `unless` not met), whether the pairing
   *  holds, and the texts; null for levers without sideEffects, or while feature 'sideEffects' is off. */
  bite: { value: number; growing: boolean; unlessMet: boolean; blurb: string; unlessLabel: string } | null;
  /** M3: a forbid effect is in force on it (canRaise false; lowering allowed). */
  forbidden: boolean;
  /** M4 (amend): while LeverDef.when hides the lever, its label (Cond.label or the core's fallback); else null. Absent =
   *  null (a core before the amendment). */
  waiting?: string | null;
  /* --- M5 (optional: absent = null / the value stated; the M5 core always writes them). M5 CHANGE: canRaise is false
   *     in Opposition and above a pledge's max. --- */
  /**
   * M5: the answer line, for a lever of a chair sector while feature 'chair' is on (else null): every row of the rival's
   * table priced (ResponseDef) for the lever at its NEXT level (its current level if maxed), on the current state, in
   * ascending cost (ties: comply, evade, lobby, litigate, table order), with whether each is available (an unavailable
   * one has cost Infinity); chosen = the cheapest available kind, which is exactly what the rival would answer at the
   * next order tick if the player enacted that level now and nothing else changed (exit criterion 4 asserts equality).
   * Computed at most once per lever per PROJECTION_BUCKET (20 s) while nothing structural changes, as temptation views.
   * `level` is the level priced.
   */
  rivalAnswer?: { level: number; options: { kind: ResponseKind; cost: number; available: boolean }[];
                  chosen: ResponseKind } | null;
  /** M5: the rival's current answer to the lever (RivalState.answers[id]), or null. */
  answered?: { kind: ResponseKind; cost: number; since: number } | null;
  /** M5: the effective level (RivalState doc); = level outside a Ministry. Absent = level. */
  effectiveLevel?: number;
  /** M5: the name of the pledge in force that binds it (PledgeDef.binds), or null. */
  bound?: string | null;
  /** M5: the max level that pledge allows, or null. */
  boundMax?: number | null;
  /** M5: run time a litigation holds it until, or null. */
  litigatedUntil?: number | null;
  /** M5: a carve-out won by lobbying acts this Parliament. Absent = false. */
  carvedOut?: boolean;
  /** M5: the rival is lobbying against it now (the hoarding). Absent = false. */
  lobbied?: boolean;
  /** M5: its current term in C* (LeverDef.popularity), or null without popularity or outside office. */
  popularity?: number | null;
  /** M5: the lever's rungs that have a state this Ministry (LoopholeView, ladder order); [] without a ladder, outside
   *  office or while feature 'loopholes' is off. Absent = []. */
  ladder?: LoopholeView[];
}

/** M2: one Commons project for the Commons panel (ModelApi.commonsViews, content order). */
export interface CommonsView {
  def: CommonsDef;
  level: number;
  maxLevel: number;
  /** Next level's capital cost and Mandate cost; null when maxed. */
  cost: number | null;
  mandateCost: number | null;
  /** Commons open, `requires` holds, and `sector` (if given) open. */
  visible: boolean;
  maxed: boolean;
  /** fund + capital ≥ cost and Mandate ≥ mandateCost (false when maxed). */
  affordable: boolean;
  /** visible, not maxed, affordable, no Reckoning pending. */
  canBuy: boolean;
  /** Wellbeing this project adds now, and what one more level would add on top (0 when maxed). */
  wellbeing: number;
  nextWellbeing: number;
  /** Price-proof service demand per second it adds now to intensity.sector (0 if none or that sector is closed). */
  intensityNow: number;
}

/** M1: one Know-how node for the Hindsight shop. */
export interface KnowhowView {
  def: KnowhowDef;
  level: number;
  /** Hindsight cost of the next level, null if maxed. */
  cost: number | null;
  /** Tier gate met (see KnowhowDef.tier). Excluded nodes still report true here. */
  requirementsMet: boolean;
  maxed: boolean;
  /** Id of the owned node in the same branch, if this one is excluded. */
  excludedBy: string | null;
  /** meta.hindsight ≥ cost (false when maxed). */
  affordable: boolean;
  /** requirementsMet, not maxed, not excluded, affordable, and Derived.freshRun. */
  canBuy: boolean;
  /** M5: the node's tree is held by the rival while office is taken (knowhowTrees[tree].holder 'rival'): shown as
   *  "Industrial Know-how: held by Pryce Consolidated", canBuy false. Absent = false. M5 CHANGE: canBuy (and the node's
   *  visibility, `visible`) also need KnowhowDef.when. */
  held?: boolean;
  /** M5: KnowhowDef.when holds (or the node has none). Absent = true. */
  visible?: boolean;
}

/** M1: one Institution for the Hindsight shop and the loadout. */
export interface InstitutionView {
  def: InstitutionDef;
  /** Level owned (0 = not unlocked). */
  level: number;
  maxLevel: number;
  /** Hindsight for the next level (level 1 = def.cost), null at max. */
  nextCost: number | null;
  /** `requires` met. */
  requirementsMet: boolean;
  /** meta.hindsight ≥ nextCost (false at max). */
  affordable: boolean;
  seated: boolean;
  /** def.slots ?? 1 */
  slots: number;
  /** requirementsMet, below max, affordable, and Derived.freshRun. */
  canBuy: boolean;
  /** Owned, not seated, free seats ≥ slots, and Derived.freshRun. */
  canSeat: boolean;
  /** M4 (amend): owned, or InstitutionDef.when holds (canBuy needs it too). Absent = true (a core before the amendment). */
  visible?: boolean;
  /** M4 (polish): the label of the next level's unmet `needs` (canBuy is false while it is set); null when there is none
   *  or it holds. Absent = null. */
  needs?: string | null;
  /** M5: unlocked: meta.institutions has an own key for it (level ≥ 0). An unlocked Institution at level 0 (after Take
   *  office or a Treaty) is shown as "unlocked, not bought" and its level 1 ignores `needs` (it was bought once); it
   *  cannot be seated until level ≥ 1. M5 (amend): its `when` still applies (visibility and purchase), so a "not in a
   *  Ministry" gate holds for a wiped Institution too. Absent = level ≥ 1. */
  unlocked?: boolean;
}

/* --- M5 views --- */

/**
 * M5: the prospectus (MetaState.office.prospectus; Derived.office). Computed once, by takeOffice, from meta:
 *   first     meta.firstOpening.actions folded: consecutive or not, every purchase of one upgrade id is ONE item (t = its
 *             first time, count = purchases, every = M5 (amend): the mean interval in seconds between its purchases made up to
 *             the LAST QUOTED item's time (the pace it reads at), null with fewer than two in that window); a founding
 *             is its own item (count 1); items in order of first time, the first prospectusItems of them; names from
 *             content (UpgradeDef / ApplicationDef name; the id if unknown). [] when defaulted.
 *   defaulted true when meta.firstOpening is absent or empty: the page uses OfficeText.prospectus.firstDefault.
 *   motion    the foundings in chair-act sectors (ActDef.chair) in meta.opening (the run just ended), in order, as { id,
 *             name, t }; null when there are none. (Named for Motion; no sector id is hard-coded.)
 */
export interface ProspectusView {
  defaulted: boolean;
  first: { id: string; name: string; t: number; count: number; every: number | null; kind: 'upgrade' | 'found' }[];
  motion: { id: string; name: string; t: number }[] | null;
}

/**
 * M5: the file on the late proprietor (MetaState.office.file; Derived.office). Computed once, by takeOffice:
 *   accepted / declined  the player's answers to dispatches of RivalDef.profileFrom.casts whose arm has stance 'accept'
 *             / 'refuse' (from meta.dispatches.lastPlayer where present, year and recency from it; else from playerArms,
 *             one entry per dispatch and arm answered, year null, after the dated ones, in content order); at most
 *             FILE_ITEMS each, most recent first; label = the arm's label.
 *   pliant    MetaState.office.profile.pliant.
 *   automatedShare  Σ automated ÷ Σ (automated + decisions) over meta.runs (0 if none): "{share}% were made by standing
 *             order" (an approximation: run summaries keep actions, not purchases).
 *   seasons   the number of meta.runs entries counted.
 */
export interface FileView {
  accepted: { dispatch: string; label: string; year: number | null }[];
  declined: { dispatch: string; label: string; year: number | null }[];
  pliant: number;
  automatedShare: number;
  seasons: number;
}

/** M5: Derived.chair. Every figure is from the current state; times are seconds of run time. */
export interface ChairView {
  /** C now, and C* (null unless ChairDef.showTarget holds). */
  confidence: number;
  target: number | null;
  /** C projected to polling day if C* stayed as now: C* + (C − C*) × (1 − relaxPerYear)^(years to polling, whole
   *  boundaries) (null unless showTarget holds). */
  forecast: number | null;
  /** ChairDef.confidence.winAt (the line on the chart). */
  winAt: number;
  /** The Parliament: index, seconds to polling day, the offer (PledgeView, null before it is drawn), chosen ids, how
   *  many to keep, and the polling calendar year (integer). */
  parliament: { index: number; pollIn: number; offer: PledgeView[] | null; chosen: string[] | null; keep: number;
                pollYear: number };
  /** Pledges in force. */
  pledges: PledgeView[];
  inOpposition: boolean;
  lostInARow: number;
  electionsWon: number;
  /** campaign() would accept now (in Opposition, Mandate > 0). */
  canCampaign: boolean;
  /** Inspectors (feature 'inspection'; total 0 while off): ready now, total, seconds until the next is ready (null if
   *  one is ready or there are none). */
  inspectors: { ready: number; total: number; nextReadyIn: number | null;
    /** M5 (contract): per Inspector, in index order, seconds until ready (0 = ready): the sill's cooldown rings. */
    readyIn: number[] };
  rival: RivalView;
  /** The Treasury (feature 'treasury'; null while off): income per second, the tax part, the levy part. */
  treasury: { perSec: number; taxPerSec: number; levyPerSec: number } | null;
  /** Every rung with a state this Ministry, in content order (feature 'loopholes'; [] while off). */
  loopholes: LoopholeView[];
  repealed: { lever: string; parliament: number }[];
  /** Per open chair sector: compensate() would accept now, its cost, and the run time compensation holds until (or
   *  null). Empty while feature 'treasury' is off. */
  compensation: Record<SectorId, { canCompensate: boolean; cost: number; until: number | null }>;
}

/** M5: ChairView.rival. */
export interface RivalView {
  name: string;
  capital: number;
  /** His income per second after tax. */
  incomePerSec: number;
  profile: RivalProfile;
  /** The raw figures behind each reading (MetaState.office.sources). */
  sources: Record<keyof RivalProfile, { n: number; d: number | null }>;
  paybackMax: number;
  foundPaybackMax: number;
  /** His quiet period now (model years; RivalDef.policy). */
  quietYears: number;
  /** Per open chair sector: the candidate he would take at the next tick (id, payback in seconds), or null. */
  next: Record<SectorId, { id: string; payback: number } | null>;
  /** His current answer to each lever (content order). */
  answers: { lever: string; kind: ResponseKind; cost: number; since: number }[];
  /** The playbooks he has learnt (ids, in order). */
  playbooks: string[];
}

/** M5: one pledge for the manifesto sheet. binds: the bound lever's or kind's description in words from content names
 *  ("Fuel duty escalator at most level 1"), or null. */
export interface PledgeView {
  id: string; name: string; blurb: string; confidence: number; atPoll: number; binds: string | null;
}

/** M5: one rung for the lever card and the Ministry panel. */
export interface LoopholeView {
  id: string;
  lever: string;
  status: LoopholeStatus;
  name: string;
  blurb: string;
  /** amend() would accept now. */
  canAmend: boolean;
  /** Mandate cost of amending, or null if it cannot be amended (closedBy without amend). */
  amendCost: number | null;
  /** The amendment's label (LoopholeDef.amend.label ?? name), or null if it cannot be amended. */
  amendLabel: string | null;
  /** Drafting years it would take now (× amendYearsMul), or null. */
  amendYears: number | null;
  /** Seconds of drafting left while 'drafting', else null. */
  draftLeft: number | null;
  /** M5 (contract): the whole drafting time in seconds while 'drafting' (draftUntil − since: the drafting bar), else
   *  null. */
  draftTotal: number | null;
  /** closedBy's label (Cond.label or the core's fallback), or null. */
  robustLabel: string | null;
  /** closedBy holds now (the rung is shut to the rival). */
  robust: boolean;
  prop: string | null;
}

/** M5: one Article for the Articles tab (Derived.treaty.articles). */
export interface ArticleView {
  def: ArticleDef;
  bought: boolean;
  /** `requires` holds (or none). */
  offered: boolean;
  /** offered, not bought, Precedent ≥ cost, Derived.freshRun, feature 'treaty' on. */
  canBuy: boolean;
}

/* ------------------------------------------------------------------ */
/* M5 (amend): reserved for the one consolidated amendment (week two).  */
/* ------------------------------------------------------------------ */
/*
 * M5 (amend): the lanes' gap reports are routed by the coordinator to the contract lane for ONE amendment commit. Each
 * amendment goes here as a list entry naming the type it changes and the hunk marked `M5 (amend):` at that type.
 * Entries:
 *   - AppDerived.waiting (new, optional): the label of a failing ApplicationDef.when, as LeverView.waiting.
 *   - ProspectusView doc: `every` is the mean interval among the card's purchases up to the last quoted item's time.
 *   - InstitutionView.unlocked / ModelApi M5 CHANGES (wording): an Institution unlocked at level 0 skips its level-1
 *     `needs` only; its `when` still applies (contract decision 13 narrowed: a "not in a Ministry" gate holds).
 *   - DispatchDef.recur (new, optional): 'parliament' lets a letter recur once per Parliament in a Ministry.
 *   - LoopholeDef doc: rungs and feature 'loopholes' arriving mid-run (a lever raised before it opens its first rung at
 *     the first order tick after the arrival; its answer falls due).
 */

/* ------------------------------------------------------------------ */
/* MODEL API                                                           */
/* ------------------------------------------------------------------ */

export interface ModelApi {
  /**
   * Fresh run. Pass the previous meta to carry Hindsight, know-how, institutions and the loadout over.
   * sectorOrder[0] opens at t = 0 with its free applications founded and its baseline recorded; seated institutions
   * and know-how apply (start capital, start reserves, start levers, reveal). A fresh meta has slots = startingSlots ?? 2.
   * M2: the Charter in meta.charter applies like a seated institution (startFounded applications founded, loans in
   * force); events [] and charterOffer [] (reckon() fills both for its run); pendingDividends [], commons
   * { levels: {}, fund: 0 }, lastOffline null. A fresh meta also has charter null, the default OrdersState, runs [],
   * eventSeq 0, knowhowPeak {}, peakPopulationEver 1.
   * M3: the History in meta.history applies like a second Charter (its `suspend` list removes Know-how, the seated
   * Institutions, the Charter or the Market from this run; meta.histories[id].runs += 1 is written by chooseHistory,
   * not here). A fresh run has dispatch { pending: [], queue: [], answered: [], offered: [], draws: 0, standing: [],
   * nextAt: dispatchFirstAt }, modifiers [], ambientLast {}, orderLog {}, historyLifted false; every SectorState
   * seamsSunk 0; LeverState bite and bitten absent until a side effect ramps; run.dispatchesAnswered 0 and
   * dispatchesDefaulted 0. A fresh meta
   * also has the M3 MetaState fields empty (dispatches { seen: {}, arms: {}, playerArms: {} }, history null, histories
   * {}, unlocks {}, returns {}, archive {}, flags {}, endings {}, milestones {}, bankedSeconds 0) and orders.dispatch
   * { on: false, cast: {} }. The signature is unchanged: a History, like a Charter, is chosen on the fresh run
   * (chooseHistory), not passed in.
   * M4: the run is built from the meta by the ONE carry-over step (core inherit.ts; also used by reckon): every sector
   * with a meta.world.capstone record opens capstoned (CapstoneRecord), a renewable starts at K or, while scarred, at
   * startScarred × K (RenewableDef.startScarred). A fresh meta has world {} (or absent). No 'capstoned' events here
   * (reckon emits them). GameState.surveyReveal absent.
   */
  createState(content: Content, meta?: MetaState, seed?: number): GameState;

  /**
   * Advance by dt seconds. dt is clamped to [0, MAX_TICK_SECONDS]; it is stepped in sub-steps of at most 1 s.
   * Each step (all open sectors, in sectorOrder): η, applications (availability, sufficiency drift, peaks), reserve,
   * pressure and crises, baseline, trend, serviceDelivered, backfire (direct rebound > 1, first time this run:
   * SectorState.backfired, 'backfire' headline and achievement, meta.backfiredSectors and run.firstBackfires if new),
   * budget auto-draw for active caps (after steady.standingDrawYears), decoupling streak (steadyYears += dt × YEARS_PER_SECOND while decoupling, else
   * reset — a reset of a streak holding ≥ 1 decade emits 'budgetBroken'; each time the streak crosses a multiple of
   * decadeYears a decade is recorded: decadesWithin, run.budgetDecades, decade effects, 'decade' headline; crossing
   * STEADY_STATE_YEARS holds the sector's budget line (BudgetState.heldAt) and sets run.steadySectors / meta.steadySectors, achievement 'steadyState', 'steadySector' headline
   * (once per sector per run) and, if the sector is new to meta.steadySectors, firstSteadyEffects); then population,
   * Mandate and lapses, sector unlocks ('sectorOpened', and 'ageBegins' when it is the first open sector of its age,
   * meta.sectorsOpened), steadyYearsAll and the win, run stats (wellbeingYears, yearsAtTarget, decoupledYears,
   * peakWellbeing), achievements with `when`. Built-in achievements: 'backfire' (above); 'jevonsWasRight' (every
   * efficiency upgrade of a sector that is not excluded by a fork owned, and peakR / baseR ≥ 10); 'degrowthByAccident'
   * (population < 0.6 × peak, some open sector with trendR < 0, wellbeing < target); 'steadyState' (above);
   * 'firstReckoning' (in reckon). Returns the same reference while a Reckoning is pending.
   *
   * M2 CHANGES to the step, in order. Every per-sector rule reads the state and flows at the START of the step, as M1's
   * decoupling does, so the step agrees with what Derived reported for that state.
   *   - Settled sectors skip the per-sector rules above except: openFor += dt (η is recomputed only on unsettle);
   *     resourceUsed and serviceDelivered accrue from the frozen R and D. No crisis, collapse, exhaustion, decade or
   *     streak change; their apps are not updated.
   *   - Unsettled sectors also update AppState.peakAdoption (from AppDerived.adoption) and SectorState.peakPressure.
   *   - A budget auto-drawn for an active cap takes the default pace, w0 = Derived.wellbeing, p0 = the pressure, and
   *     emits 'budgetDrawn' by 'default'.
   *   - The decade streak uses SectorDerived.decoupling (wellbeing ≥ decadeWellbeing). On a decoupling step,
   *     windowLean ||= (W < wellbeingTarget) BEFORE the crossing test; at a crossing the decade is recorded with
   *     decadesLean.push(windowLean), run.leanDecades += windowLean ? 1 : 0, then windowLean = false. A decade fires
   *     the sector's decadeEffects (one-offs × the line's pace dividendMul), the 'decade' headline and event, and, if the
   *     sector resolves a non-empty decadeChoices list, appends a PendingDividend (see GameState.pendingDividends). On a
   *     non-decoupling step the decade streak, windowLean and clearYears reset to 0 / false.
   *   - The Steady streak: clearYears += dy while SectorDerived.sinkHeld, else 0. The first step on a line with
   *     SectorDerived.clear true sets BudgetState.clearAt and emits 'clearSkies' (headline and event). Steady State
   *     (M2 CHANGE: was the decade streak crossing STEADY_STATE_YEARS) is clearYears crossing STEADY_STATE_YEARS, with
   *     every M1 consequence listed above (heldAt, run/meta.steadySectors, achievement, headline, firstSteadyEffects)
   *     and the 'steadyState' event.
   *   - Mandate: upkeep = lever upkeep + Σ settlement defences; the lapse rule is extended as in SettledState.
   *   - Commons fund: commons.fund += fundShare × (levy revenue routed to 'commons') × dt.
   *   - A sector opening in the step founds any of its applications named by a standing startFounded effect.
   *   - steadyYearsAll: as GameState.steadyYearsAll (M2 CHANGE).
   *   - meta.peakPopulationEver = max(itself, population).
   *   - Every headline the step emits whose HeadlineKey has an EventKind of the same meaning also emits that event
   *     (see EventKind), in the same order ('steadySector' → 'steadyState', 'steadyAll' → 'won').
   *   - Last, if the step is an order tick, the standing orders run (see OrdersState).
   *
   * M3 CHANGES to the step. Every rule reads the state at the START of the step, as in M2.
   *   - Solve: the mechanic kinds (see "M3 MECHANICS") and the M3 effects act inside computeFlows; nothing in the step
   *     needs to know them except as below.
   *   - Per unsettled sector, after the applications block: lockInDecay (ApplicationDef.lockInDecay) on peakD.
   *   - Levers: bite ramps per LeverDef.sideEffects (after Mandate and lapses, so a lapsed lever is judged at its new
   *     level from the next step); 'biteBack' once per lever per run.
   *   - Timed modifiers: those with until ≤ the step's end time are removed ('modifierEnded').
   *   - Dispatches: expiry, then a draw, as GameState.dispatch says (no draw inside fastForward or useBank).
   *   - Ambient: at an ambient tick, outside fastForward and useBank, one AmbientDef (see AmbientDef).
   *   - The History in force: forbidUntil checked each step (historyLifted); goal checked about once a real second
   *     (as achievements with `when`): the first time it holds this run, meta.histories[id].cleared = true, best =
   *     min(best, run time), reward.unlock ids into meta.unlocks (and achievement granted, cosmetic and title into
   *     meta.unlocks as keys 'cosmetic:<key>' and 'title:<text>'), 'history' headline, 'historyCleared' event,
   *     milestone 'history' if absent.
   *   - Archive: notes whose subject rule now holds are unlocked (about once a real second; ArchiveDef).
   *   - Milestones (MetaState.milestones): written at the moment each first happens (keys listed there).
   *   - The win (M3 finish: every Industry settled for GlobalParams.endingYears; see GameState.steadyYearsAll): when
   *     flags.won is first set in a run and meta.endings.steadyAll is absent, write it (EndingRecord), the
   *     milestone 'won', the 'ending' headline and event after 'won'. The run continues ("The ledger continues"); a
   *     later win in a later run sets flags.won and 'won' as in M2 but no second 'ending'.
   *   - Mandate: a 'measure' lever's upkeep counts as any lever's.
   *   - Standing orders: the Market skips forbidden candidates and writes orderLog; nothing else changes.
   * Settled sectors: as M2; their levers are at 0, so their bite decays; lockInDecay does not run while settled.
   *
   * M4 CHANGES to the step (each one line in step.ts calling its module; every rule reads the state at the START of the
   * step, as in M2 and M3):
   *   - Solve: feeds (ApplicationDef.feeds), the shared reserve's price (SectorDef.resourceStock) and the renewable's
   *     reported price act inside computeFlows; a capstoned sector's settled flows are scaled per head (CapstoneRecord).
   *   - Reserves: an owner's reserve is drained by its drawers too (SectorDef.resourceStock); a renewable's stock is
   *     stepped (RenewableDef's step), with crossing, scar, derived pressure ('depletion') and its crises; scars tick.
   *   - Surveys: the Board's first survey (RenewableDef.firstSurvey; live steps only); 'surveyed' on the first surveyed
   *     step of the run; SectorState.lastSurvey updated on every surveyed step; the reveal's follow-up headline on the
   *     step after the reveal.
   *   - Foreign fleets: 'foreignFleets' headline once a run (ForeignDef.announceAt).
   *   - Mandate and lapses: capstoned sectors go into arrears instead of unsettling; arrears stepping and clearing
   *     (SettledState, M4).
   *   - steadyYearsAll and the win: the M4 rule with Content.acts (GameState.steadyYearsAll); at an act's ending, the
   *     capstone records.
   *   - Run records: SectorState.minStock every step; SectorState.feedPeak at each HistorySample.
   *   - Events and headlines in the M4 order (EventKind).
   */
  tick(state: GameState, content: Content, dt: number): GameState;
  /**
   * Offline catch-up: steps of at most 5 s, capped at Derived.offlineCapSeconds (M2 CHANGE: was offlineCapSeconds).
   * M2: it never ends a run unseen. With holdBefore = GlobalParams.offline.holdBefore (default 'collapse'): it checks
   * each step's result before keeping it; if the step fired a crisis in any sector (holdBefore 'crisis'), or made a
   * Reckoning pending by collapse or exhaustion (holdBefore 'crisis' or 'collapse'), it DISCARDS that step and stops,
   * returning the state one step before. The remaining time is forfeited (banked time is a later milestone). The held
   * crisis or collapse then happens in live play, seconds after the player returns; a further fastForward from a held
   * state holds again at once (simulated 0), so the board waits for the player. Standing orders run inside the steps
   * exactly as in tick. The returned state carries lastOffline (see OfflineReport), also when it simulated 0 seconds.
   * M2 (offline fix): two rules apply only inside fastForward: Hindsight accrues at GlobalParams.offline.hindsightRate
   * (RunStats.hindsightWithheld), and a full pendingDividends list forgoes new offers instead of overflowing (see
   * GameState.pendingDividends). Both are deterministic and leave tick() untouched.
   * QA FIX (B6): a third rule inside fastForward only: budget lines do not decline while away. Before each step, every
   * open, unsettled sector's line without heldAt has BudgetState.since moved on by the step's length, so budgetR stays
   * where it stood on leaving and resumes its decline in play. (A line held on leaving was lost to its own decline:
   * the cap leaked, a locked-in floor overtook it, or wellbeing fell under the drawn level, with nobody to answer.)
   * OfflineReport.lines tells a redraw from the pause. Decades still accrue away on a line that holds, as before.
   * A call with seconds ≤ 0 (after clamping; NaN counts as 0) returns the same reference and writes nothing. If a
   * Reckoning is already pending it simulates nothing (heldBy 'pending').
   * M3: inside fastForward no dispatch is drawn and no ambient headline printed; pending dispatches still expire to
   * their defaults (OfflineReport.dispatchesDefaulted); timed modifiers still end; bites ramp; Histories and the Archive
   * are checked as in tick. After the call, banked time per GlobalParams.offline.bankRate (OfflineReport.banked).
   * M4: with holdBefore 'crisis' or 'collapse' it also holds one step before a capstoned sector would go into arrears
   * (heldBy 'arrears'). Scars tick away as in tick. The Board's first survey never happens inside fastForward (it waits
   * for the first live step). A renewable's threshold crossing is not itself held (its crisis at 1 − θ is, under
   * 'crisis').
   */
  fastForward(state: GameState, content: Content, seconds: number): GameState;

  derive(state: GameState, content: Content): Derived;

  /* --- player actions: each returns the new state, or the same reference if the action is not allowed --- */
  /* M2: every in-run action below that changes the state counts once in run.decisions / decisionsByDecade (see
   *     RunStats.decisions) and emits its events with by 'player'. Every in-run action except setOrders (and reckon
   *     itself) is refused while a Reckoning is pending.
   * M3: sinkSeam and answerDispatch are decisions too (add them to RunStats.decisions' list). fileReturn,
   *     withdrawReturn, useBank and chooseHistory are not. Every M3 action is refused while its feature is off (see
   *     M3FeatureId). buyUpgrade, foundApp, setLever (raises) and buyCommons are refused for forbidden things; their
   *     capital costs include costMulOf effects. */
  /** capital += Derived.clickValue; run.clicks++. */
  click(state: GameState, content: Content): GameState;
  /** Refused if not visible, maxed, excluded, unaffordable, or a Reckoning is pending. One-off effects fire.
   *  M2: refused in a settled sector (its upgrades are not visible); recorded in run.opening ('upgrade', 'player');
   *  events 'upgradeBought', then 'stageReached' if SectorDerived.stage rose. */
  buyUpgrade(state: GameState, content: Content, upgradeId: string): GameState;
  /** M2: refused in a settled sector; recorded in run.opening ('found', 'player'); event 'appFounded'. */
  foundApp(state: GameState, content: Content, appId: string): GameState;
  /**
   * Raise or lower a lever to `level` (0 … maxLevel). Raising charges Mandate (levels at or below an institution's
   * startLever level are free); lowering is free and immediate. Raising a lever from 0 snapshots duty's ref; raising any
   * lever (M1 balance: from any level) draws the sector's budget at the current R if it has none.
   * M2: the line it draws takes the default pace, w0 = Derived.wellbeing and p0 = the sector's pressure, and sets
   * run.firstBudgetAt if null. Refused for a settled sector's levers. Event 'leverEnacted' on raises.
   * The unfolding / QA (B17): raising a CAP lever from level 0 while the sector is over its budget line
   * (R > budgetR × (1 + BUDGET_TOLERANCE)) first redraws the line at the current R, at the line's own pace (as drawBudget
   * would: w0, p0, streaks reset; decades kept), so a cap never cuts use to a line the economy has outgrown. No line is
   * drawn by a raise while the 'budget' feature is locked.
   */
  setLever(state: GameState, content: Content, leverId: string, level: number): GameState;
  /** M1: choose where a duty or cap lever's revenue goes. Refused for options the lever does not offer. Free.
   *  M2: 'commons' is refused until the Commons are open; refused when the option is already in force. */
  setLeverRecycle(state: GameState, content: Content, leverId: string, option: LeverRecycle): GameState;
  /**
   * M1: draw (or redraw) the sector's budget line at its current R. Requires flags.revealed, the sector open with R > 0,
   * and no pending Reckoning. Redrawing resets the sector's streak; earned decades are kept. Free. Emits 'budgetDrawn'.
   * M2: `pace` is a pace id of the sector's resolved paces (default: the first; an unknown id is refused). Records w0,
   * p0 and the pace; a redraw also resets clearYears and windowLean. Refused for a settled sector. Sets
   * run.firstBudgetAt if null.
   */
  drawBudget(state: GameState, content: Content, sector: SectorId, pace?: string): GameState;
  /**
   * M2: resolve the OLDEST pending dividend of `sector` with option 0 or 1: removes it from pendingDividends, appends
   * the chosen id to SectorState.dividends, fires its one-offs (mandateAdd and capitalAdd × its mul), emits
   * 'dividendChosen'. Refused if the sector has no pending dividend, the option is not 0 or 1, or a Reckoning is pending.
   */
  chooseDecadeDividend(state: GameState, content: Content, sector: SectorId, option: number): GameState;
  /**
   * M2: settle the sector. Allowed when the sector is open and not settled, SectorDef.settle exists, flags.revealed,
   * (M3 finish: fewer Industries are settled than Derived.ending.room allows,)
   * no Reckoning is pending, and the sector is AT Steady State now: clearYears ≥ STEADY_STATE_YEARS and
   * SectorDerived.sinkHeld. Effect: SectorState.settled = a SettledState snapshot of the sector's current flows (D, R,
   * ps, pPre, income, pressure, η, defect, N, spillMul, extraD, per-app demand and adoption); every lever of the sector
   * goes to level 0 (ref 0; their upkeep stops; their recycle choice is kept); settle.dividend's standing effects come
   * into force, and its one-offs fire if settledBefore was false (then settledBefore = true); 'settled' headline and
   * event. The budget line, decades and dividends are kept; the Market and the Civil Service skip the sector.
   * M4: also refused while SectorDef.settle.requires fails (SectorDerived.settleBlocked); capstoned sectors are already
   * settled (refused) and do not count against the room. A renewable's settlement snapshots Q (frozen).
   */
  settle(state: GameState, content: Content, sector: SectorId): GameState;
  /**
   * M2: end the settlement (also what the lapse rule does when a defence cannot be paid, with by 'default'). Effect:
   * settled = null; the sector resumes from its frozen state (reserve, pressure and apps as they were; η recomputed for
   * today's openFor, so an autoEta sector resumes with the gains of the settled years; levers stay at 0); steadyYears,
   * clearYears and windowLean reset (Steady State must be earned again before settling again; the line keeps its
   * heldAt); settle.dividend stops. 'unsettled' headline and event. Free; refused if not settled or a Reckoning is
   * pending. The cost is what is lost: the dividend, the levers, the streak, and whatever the economy has grown into.
   * M4: refused (same reference) for a capstoned sector, by the player or by the lapse rule (which puts it into arrears).
   */
  unsettle(state: GameState, content: Content, sector: SectorId): GameState;
  /**
   * M2: buy the next level of a Commons project whose CommonsView reports canBuy. The capital cost is taken from
   * commons.fund first, then from capital; the Mandate cost from Mandate. One-off effects fire. 'commonsBuilt' headline
   * and event.
   */
  buyCommons(state: GameState, content: Content, id: string): GameState;
  /**
   * M2: change standing orders (MetaState.orders) with a partial patch. paybackMax is clamped to [1, 86400] and
   * keepSeconds to [0, 86400]; non-finite numbers, unknown sector ids, lever ids not of that sector and unknown project
   * ids are dropped. Settings of an order that is not available are stored but inert. Returns the same reference if
   * nothing changes. Counts as a decision unless Derived.freshRun. Allowed at any time, also while a Reckoning is pending.
   */
  setOrders(state: GameState, content: Content, patch: OrdersPatch): GameState;
  /** End the run. Uses the pending cause if there is one, else 'chosen'. Returns the fresh next run.
   *  M2: see hindsightOnReckon for everything it records. */
  reckon(state: GameState, content: Content): GameState;
  /**
   * M1 CHANGE: allowed only while Derived.freshRun (between runs). Buys the next level of a node whose KnowhowView
   * reports canBuy. One-off effects (slotAdd) fire. The fresh run is rebuilt from the new meta (createState with the
   * same seed), keeping its news, Mandate, clicks and any capital earned by clicking.
   * M2: one-offs fire only if the new level exceeds meta.knowhowPeak[id], which is then raised. Every between-runs
   * rebuild (this, buyInstitution, setLoadout, chooseCharter, respecKnowhow) also keeps events, charterOffer and
   * lastOffline.
   */
  buyKnowhow(state: GameState, content: Content, id: string): GameState;
  /** M1 CHANGE: buys the next level (level 1 unlocks). Allowed only while Derived.freshRun; rebuilds the run as buyKnowhow. */
  buyInstitution(state: GameState, content: Content, id: string): GameState;
  /**
   * M1: replace the loadout. Allowed only while Derived.freshRun. Refused unless every id is owned, ids are distinct,
   * and Σ slots ≤ meta.slots. Rebuilds the run as buyKnowhow.
   */
  setLoadout(state: GameState, content: Content, ids: string[]): GameState;
  /**
   * M2: choose this run's Charter from Derived.charterOffer (or null to have none). Allowed only while
   * Derived.freshRun; refused for an id not in the offer, or if it is already the one in force. Sets meta.charter,
   * rebuilds the run as buyKnowhow, then adds the 'charter' headline and a 'charterChosen' event (neither for null).
   */
  chooseCharter(state: GameState, content: Content, id: string | null): GameState;
  /**
   * M2: Know-how respec. Allowed only while Derived.freshRun. Every know-how node (of `tree` only, if given; a node's
   * tree is KnowhowDef.tree ?? 'general') goes to level 0, and meta.hindsight += respecRefund × Σ over the removed
   * levels l = 0 … level − 1 of cost × costGrowth^l (the price list, not what was paid). Branch exclusions of the cleared
   * nodes lift. One-off effects are neither reversed nor granted again (knowhowPeak is kept). A node of tier ≥ 2 left
   * without a tier − 1 node in its tree keeps its level (tiers gate buying, not owning). Refused if nothing in scope is
   * owned. Rebuilds the run as buyKnowhow. Not a decision.
   */
  respecKnowhow(state: GameState, content: Content, tree?: string): GameState;

  /* --- views for the UI --- */
  /** Called about once a second and after each action; runs projections (the core caches them).
   *  M2: projections never run standing orders. */
  /** With `sector`, only that sector's eligible cards are projected; every card is still returned, the others with
   *  `projectedDecade: null` and `bringsWithinReach: []`. Without it, every eligible card is projected. Projections are
   *  cached on the state's structure and a 20 s time bucket, so a projected line may lag the exact one by up to a bucket. */
  upgradeViews(state: GameState, content: Content, sector?: SectorId): UpgradeView[];
  leverViews(state: GameState, content: Content): LeverView[];
  /** M1: the Hindsight shop, Know-how half (content order). */
  knowhowViews(state: GameState, content: Content): KnowhowView[];
  /** M1: the Hindsight shop, Institutions half, and the loadout (content order). */
  institutionViews(state: GameState, content: Content): InstitutionView[];
  /** M2: the Commons panel (content order; invisible projects included with visible false). */
  commonsViews(state: GameState, content: Content): CommonsView[];
  /**
   * M2: the calendar year (fractional) at run time `time` of the current run: the AgeDef.yearSpan formula evaluated
   * with each sector's openFor replaced by openFor − (state.time − time), a sector counting as open at `time` when that
   * is ≥ 0 (sectorOrder[0] is open from 0). For time = state.time it equals Derived.year. Times after state.time
   * extrapolate with the sectors open now; negative times are treated as 0. Used for "held since 1840" and the ledger.
   */
  yearAt(state: GameState, content: Content, time: number): number;
  /**
   * M1 CHANGE: Hindsight a Reckoning now would pay: HindsightTerms.total (see GlobalParams.hindsight). Reckoning adds
   * it to meta.hindsight and hindsightEarned, fills meta.lastRun (with hindsightTerms), reckonings++, grants
   * 'firstReckoning', and returns createState(content, newMeta, nextSeed) with a 'reckoning' headline.
   * M2: reckon() also builds the RunSummary with its M2 fields and appends it to meta.runs (trimmed to RUN_HISTORY_MAX;
   * lastRun = that summary); writes meta.opening (and meta.firstOpening if absent) from run.opening, run.firstBudgetAt,
   * the run's length and its Charter; sets meta.charter = null; then, on the new run, draws charterOffer (see
   * GameState.charterOffer) and emits the 'reckoning' event. Pending dividends, the Commons and settlements end with
   * the run; meta.orders carries over.
   * M3: reckon() also records the History (RunSummary.history, historyCleared) and sets meta.history = null; records
   * dispatchesAnswered/Defaulted and per-sector seams, loadFactor, speed and sprawl; ends pending dispatches, the queue
   * and the modifiers unpaid; publishes an unpublished household return into the new run's news if meta.flags.proprietor
   * (see fileReturn). meta.dispatches, histories, unlocks, returns, archive, flags, endings, milestones and the bank
   * carry over.
   * M4: reckon() records the RunSummary's M4 sector fields (minStock, crossed, feedR, capstoned); builds the new run
   * with the carry-over step (createState, M4) and emits one 'capstoned' event per capstoned sector after the
   * 'reckoning' event (and the milestone 'capstone' the first time); meta.world carries over (it is never reset).
   * GameState.surveyReveal does not carry over. Hindsight's capstone exclusions: GlobalParams.hindsight.
   */
  hindsightOnReckon(state: GameState, content: Content): number;

  /* --- M3 actions --- */
  /**
   * M3: sink the next seam of `sector` (SectorDef.seams[seamsSunk]). Refused unless: feature 'seams' on; the sector open,
   * unsettled and 'stock'; a next seam exists; it is reachable (p_s ≤ reachBelow and `requires`); not forbidden;
   * capital ≥ its cost (after costMul and costMulOf); no Reckoning pending. Effect: capital −= cost; reserve and
   * reserveMax += tons; seamsSunk += 1; 'seamSunk' headline and event (by 'player'); milestone 'seam:<s>' if absent. A
   * decision. The Market never sinks seams.
   */
  sinkSeam(state: GameState, content: Content, sector: SectorId): GameState;
  /**
   * M3: answer a pending dispatch with arm `arm` (0-based). `id` selects which pending dispatch (default: the oldest).
   * Refused unless: feature 'dispatches' on; it is pending; the arm exists; its `cost` is affordable (Mandate ≥ mandate
   * and capital ≥ capitalSeconds × Derived.incomePerSec); no Reckoning pending. Effect, in order: pay the cost; fire the
   * arm's one-off effects (reserveAdd at once); its standing effects join dispatch.standing (once per answer, rest of
   * run); its modifier (if any) is added to modifiers with since = time, until = time + years / YEARS_PER_SECOND
   * (stacking per GameState.modifiers); `next` (if any) is appended to the queue; the pending entry is removed;
   * answered += { id, arm, t: time, by: 'player' }; meta.dispatches.arms[id][arm] += 1 and playerArms[id][arm] += 1;
   * run.dispatchesAnswered += 1; the 'answered' headline (if the arm has a reply) and 'dispatchAnswered' event;
   * milestone 'dispatch' if absent; nextAt per GameState.dispatch. A decision.
   * A default resolution (expiry, the standing order) does the same with the default arm, by 'default' or 'dispatch',
   * paying what there is, counting run.dispatchesDefaulted and meta.dispatches.arms (not playerArms), no decision.
   * M4: a wager arm (DispatchArm.wager) evaluates its `when` on the state after the cost is paid and before any effect,
   * records AnsweredDispatch.won, then applies the arm's own effects, modifier and reply, then the branch's (in that
   * order); the event's label is 'won' | 'lost'. A wager arm is never a default arm (lint), so defaults never wager.
   */
  answerDispatch(state: GameState, content: Content, arm: number, id?: string): GameState;
  /**
   * M3: choose this run's History (or null for none). Allowed only while Derived.freshRun and feature 'histories' is
   * on; refused for an id not offered (HistoryView.offered) or already in force. Sets meta.history; if not null,
   * meta.histories[id].runs += 1 (and −1 on the History it replaces, if that was chosen in this same fresh run, so
   * switching back and forth counts one run); rebuilds the run as buyKnowhow; then a 'historyChosen' event (not for
   * null). Not a decision. A History composes with the Charter (see HistoryDef).
   */
  chooseHistory(state: GameState, content: Content, id: string | null): GameState;
  /**
   * M3: file a return: the one bridge from the UI's wall clock into the model (shift 3). The figures are untrusted
   * input and are validated; any failure refuses the whole return (same reference):
   *   - feature 'survey' on; ret is an object with `id` a string and `figures` a plain object;
   *   - id === 'household' (M3 knows no other); every key of HouseholdFigures present;
   *   - each value a finite number, 0 ≤ value ≤ RETURN_FIGURE_MAX; values are floored to integers (all are counts);
   *   - consistency: sessions ≤ looks on each side; days ≤ sessions on each side; quietDays ≤ daysBefore + daysAfter;
   *   - at most one filing per id per run: refused if meta.returns[id].run === meta.reckonings, unless the figures are
   *     identical (then the same reference is returned and nothing is written).
   * Keys not in HouseholdFigures are dropped. Effect: meta.returns[id] = { figures, run: meta.reckonings, at:
   * meta.totalSeconds, published: false, template: null } (a later filing replaces an earlier one); 'returnFiled' event.
   * If meta.flags.proprietor is already true, the return is published at once (see below) — else it waits for the card.
   * Publication (here, when the card is bought, or at reckon()): published = true; template = mix32(state.seed ^
   * meta.reckonings) mod (number of Content.proprietor.returns templates of SurveyView.direction); a 'return' NewsItem
   * with the substituted headline; 'returnPublished' event (n = round(workdayChange × 100), 0 if null); milestone
   * 'proprietor' if absent. At most one publication per run (the paper's annual statistics): a filing in a run that has
   * already published waits for the next reckon(), which publishes an unpublished household return into the new run's
   * news (only while meta.flags.proprietor). Wall-clock time itself never enters the core; the state stays a pure
   * function of its inputs. Not a decision. Allowed while a Reckoning is pending.
   */
  fileReturn(state: GameState, content: Content, ret: PlayReturn): GameState;
  /**
   * M3: withdraw a return (the "Close the Household Survey" switch): deletes meta.returns[id] (so the save holds no
   * figures), prints Content.proprietor.withdrawn as a 'returnWithdrawn' item and event. Refused (same reference) if no
   * such return is on file. Allowed always (whatever the features), also while a Reckoning is pending. Not a decision.
   * meta.flags.proprietor stays (the reveal happened); Derived.survey becomes null.
   */
  withdrawReturn(state: GameState, content: Content, id: string): GameState;
  /**
   * M3: spend banked time (optional; GlobalParams.offline.bankRate). Simulates s = min(seconds, meta.bankedSeconds) as
   * fastForward does (steps of 5 s, the same holds, the away rules: Hindsight at hindsightRate, no dividend overflow,
   * no dispatch draws, no ambient news), WITHOUT the offline cap, and subtracts the seconds actually simulated from the
   * bank. Refused (same reference) when feature 'bank' is off, s ≤ 0, or a Reckoning is pending. Writes no lastOffline;
   * emits 'bankUsed' (n = seconds simulated). The UI may call it in small slices beside tick to play banked time at 2×.
   * Not a decision.
   */
  useBank(state: GameState, content: Content, seconds: number): GameState;

  /* --- M3 views --- */
  /** M3: the History picker (content order). */
  historyViews(state: GameState, content: Content): HistoryView[];
  /** M3: the Archive (content order). */
  archiveViews(state: GameState, content: Content): ArchiveView[];
  /** M3: the retrospective Gazette from meta.milestones and Content.ending (oldest first; see EndingText). */
  retrospective(state: GameState, content: Content): RetroItem[];

  /* --- M5 actions (design/m5-contract-notes.md §13) ---
   * M5 CHANGES to existing actions (each only in a Ministry, i.e. GameState.chair non-null, unless stated):
   *   - buyUpgrade and foundApp refuse a chair sector's cards and applications (they are the rival's: UpgradeView.byRival).
   *   - click is refused (Derived.clickValue 0).
   *   - setLever refuses raises while ChairState.inOpposition, and a raise above a pledge's binds.max (LeverView.bound);
   *     a raise records LeverState.raisedAt (and `since` on a raise from 0, removed on a return to 0); a 'charge' (and a
   *     cap or quota with basis 'applied') snapshots `ref` on the raise from 0; a laddered lever's first raise to ≥ 1
   *     opens its first rung (LoopholeDef). The Civil Service is bound the same way.
   *   - buyKnowhow refuses a node of a rival-held tree while office is taken, and any node whose KnowhowDef.when fails
   *     (in or out of office). buyInstitution accepts level 1 of an unlocked (level 0) Institution at def.cost, ignoring
   *     the level-1 `needs` (M5 (amend): its `when` still applies). setLoadout refuses an Institution at level 0.
   *   - settle in a Ministry is allowed on chair sectors (a settlement from the Chair) as on any sector; the Reckoning
   *     adds the chair sectors settled at its moment to office.record.settledFromChair.
   *   - reckon: cause 'defeated' when pending (ChairState); in office, office.ministries += 1 and office.record is added
   *     to (MetaState.office); RunSummary.ministry and sectors[s].openFor / certified / rival recorded; OfficeDef.when
   *     evaluated on the ended run sets the fresh run's officeOffer (not in office); the new run is built by inherit.ts
   *     as a Ministry when office is taken (the chair state fresh; the rival's capital per RivalDef.startCapitalSeconds;
   *     rungs empty; the capstone held by the rival; Compute and Code closed by closedInOffice).
   *   - createState(content, meta) with meta.office present builds a Ministry the same way.
   *   - hindsightOnReckon: the overlay and the `parliaments` term (HindsightTerms).
   *   - fastForward: with holdBefore 'crisis' or 'collapse' it holds one step before a polling day the Ministry would
   *     lose (OfflineReport.heldBy 'election'); it draws no pledge offer while away.
   *   - answerDispatch (by the player) writes meta.dispatches.lastPlayer[id].
   *   - deserialize: v6 (SAVE_VERSION).
   * Every M5 in-run action below is refused while a Reckoning is pending, outside a Ministry, and while its feature is
   * off ('chair' for choosePledges and campaign; 'inspection' for inspect; 'loopholes' for amend; 'treasury' for
   * compensate); it returns the same reference when refused.
   */
  /**
   * M5: Take office (§1). Allowed only while Derived.freshRun, GameState.officeOffer, office not taken, and Content
   * .office, .chair and .rival present. Not a decision. Effect (the first Treaty reset, D2), in order:
   *   1. meta.office = { run: meta.reckonings, at: meta.totalSeconds, profile and sources (RivalDef.profileFrom, from
   *      meta; defaultProfile when meta.firstOpening is absent), handedOver = every meta.knowhow entry of a tree whose
   *      knowhowTrees[tree].holder is 'rival' (those entries removed from meta.knowhow; knowhowPeak kept), prospectus,
   *      file, ministries: 1, record zeros };
   *   2. meta.hindsight = 0; every meta.institutions entry → 0 (kept unlocked); meta.loadout = []; meta.flags.office =
   *      true (meta.charter and meta.history are left as chosen);
   *   3. feature 'chair' unlocked at once if its `when` holds (M5FeatureId);
   *   4. the run rebuilt as a Ministry (createState with the same seed; GameState.chair built; officeOffer false), its
   *      news and events kept as a between-runs rebuild keeps them;
   *   5. 'officeTaken' event; headlines 'acquisition' (OfficeText.acquisition.headline) then 'officeTaken' (then
   *      OfficeText.sealed, if any sector was sealed).
   */
  takeOffice(state: GameState, content: Content): GameState;
  /**
   * M5: send the soonest-ready Inspector to sector `sector` (§4). Refused unless feature 'inspection' is on, the sector
   * is an open rival sector, and an Inspector is ready. Effect: that Inspector is ready again at time + cooldownYears /
   * YPS; inspected[s] = time; inspections += 1; if c = concealment[s] > 0: Mandate += the fine (ChairState), C +=
   * fineFound, found[s] = { share: c, t: time }, concealment[s] = 0, findings += 1, events 'inspected' (n = round(c ×
   * 100)) then 'concealmentFound', headline 'concealmentFound'; else 'inspected' (n 0) and headline 'inspectedClean'.
   * The true R is shown until time + revealYears / YPS (SectorDerived.inspectedUntil). A decision.
   */
  inspect(state: GameState, content: Content, sector: SectorId): GameState;
  /**
   * M5: draft an amendment closing rung `loopholeId` (§5). Refused unless feature 'loopholes' is on, the rung has a state
   * 'open' or 'used', it can be amended (LoopholeDef.amend, or no closedBy), and Mandate ≥ its cost. Allowed in
   * Opposition. Effect: Mandate −= cost; status 'drafting' (before = the old status) with draftUntil = time + years ×
   * Π amendYearsMul / YPS; while drafting the rung acts as `before`; completion per LoopholeDef. A decision.
   */
  amend(state: GameState, content: Content, loopholeId: string): GameState;
  /**
   * M5: choose the pledges to stand on (§2). Refused unless the offer is drawn and polling day not passed, `ids` are
   * exactly `keep` distinct ids of the offer, and they differ from `chosen`. Effect: parliament.chosen = ids in content
   * order. May be called again before polling day. A decision.
   */
  choosePledges(state: GameState, content: Content, ids: string[]): GameState;
  /**
   * M5: campaign in Opposition (§2): spend `mandate` Mandate for Confidence. Refused unless in Opposition, mandate is
   * finite and > 0, and Mandate ≥ mandate. Effect: Mandate −= mandate; C += campaignPerMandate × mandate (clamped). A
   * decision.
   */
  campaign(state: GameState, content: Content, mandate: number): GameState;
  /**
   * M5: compensate the rival's displaced workers in `sector` (§6). Refused unless feature 'treasury' is on, the sector is
   * an open chair sector with income below the rival's peak there, not compensated now, and the Treasury (capital) ≥ the
   * cost (ChairDef.compensation). Effect: capital −= cost; compensated[s] = time + years / YPS; 'compensated' event and
   * headline. A decision.
   */
  compensate(state: GameState, content: Content, sector: SectorId): GameState;
  /**
   * M5: the Treaty (§9). Allowed only while Derived.freshRun and Derived.treaty.available. Not a decision. Effect:
   * meta.precedent and precedentEarned += precedentIfNow; office.record zeroed; meta.hindsight = 0; every meta.knowhow
   * entry of a tree NOT held by the rival → removed (a respec without refund; knowhowPeak kept); every Institution →
   * level 0 (kept unlocked); loadout []; meta.treaties += 1; the PlaybookDef with treaty === meta.treaties (if any)
   * appended to meta.playbooks; the run rebuilt (createState, same seed; officeOffer and charterOffer kept as a rebuild
   * keeps them); events 'treaty' then 'playbookLearnt' (if one), headlines likewise.
   */
  treaty(state: GameState, content: Content): GameState;
  /**
   * M5: buy an Article (§9). Allowed only while Derived.freshRun, feature 'treaty' on, office taken, the Article offered
   * (requires), not bought, and meta.precedent ≥ its cost. Effect: precedent −= cost; meta.articles[id] = true; the run
   * rebuilt as buyKnowhow; 'articleBought' event and headline. Not a decision.
   */
  buyArticle(state: GameState, content: Content, id: string): GameState;

  /* --- persistence --- */
  serialize(state: GameState): string;
  /** Returns null if the string is not a usable save. Migrates older versions (see SAVE_VERSION). */
  deserialize(text: string, content: Content): GameState | null;
}
